ZL_PackedData = {
"-- zLoot journal data. Generated from InstanceJournal (public domain). Do not edit by hand.\nlocal M=ZLLib.MediaPath local F=ZLLib.AbilityFlags local T=ZLLib.InstanceType\nZLDB=ZLDB or {} ZLDB.DG={} ZLDB.R={}\nZLDB.DG[\"BFD\"]={\nName=\"Blackfathom Deeps\",\nStory=\"Once dedicated to the night elves' goddess Elune, Blackfathom Deeps was thought to have been destroyed during the Sundering, lost beneath the ocean. Millennia later, members of the Twilight's Hammer cult were drawn to the temple by whispers and foul dreams. After sacrificing untold numbers of innocents, the cult was rewarded with a new task: to protect one of the Old Gods' most cherished creatures, a pet that is still in need of nurturing before he can unleash his dark powers on the world.\",\nBackground=M..\"dungeons\\\\bfd\\\\background\",\nGridBackground=M..\"dungeons\\\\bfd\\\\grid-background\",\nMapId=7,\nIconScale=0.9,\nMinLevel=22,\nMaxLevel=31,\nEntrances={{MapContinentId=1,MapCoordinateX=14.1,MapCoordinateY=14.4,MapZoneId=1}},\nType=T.Dungeon,\nKey=\"BFD\",\nBosses={\n{Id=\"4887\",Name=\"Ghamoo-ra\",Story=\"When the Twilight's Hammer cult arrived, its followers roused and imprisoned one of the last peaceful creatures living in Elune's temple. The cult delighted in tormenting the giant turtle for years, flaying its mind and body until it succumbed to madness. Naming the beast Ghamoo-Ra, the cultists trained it to attack outsiders and defend the Old Gods' shrine.\",Portrait=M..\"dungeons\\\\bfd\\\\ghamoora-portrait\",Frame=M..\"dungeons\\\\bfd\\\\ghamoora-frame\",MapCoordinateX=22.5,MapCoordinateY=41,L=\"6907:50,6908:50,80718:35\"},\n{Id=\"4831\",Name=\"Lady Sarevess\",Story=\"The Twilight's Hammer granted Lady Sarevess her own private cove within Blackfathom Deeps, continuously sending her fresh sacrifices. The cultists hope that her rituals and research will result in magical protection that will allow them to worship the terrifying hydra at the deeps' core without fear of becoming his next meal.\",Portrait=M..\"dungeons\\\\bfd\\\\sarevess-portrait\",Frame=M..\"dungeons\\\\bfd\\\\sarevess-frame\",MapCoordinateX=6.7,MapCoordinateY=25.8,L=\"888:33,3078:33,11121:33\"},\n{Id=\"6243\",Name=\"Gelihast\",Story=\"The Old Gods called, and Gelihast answered, forcing his way into Blackfathom Deeps and slaughtering nearly a dozen surprised Twilight's Hammer cultists with his twin swords. Impressed by his ferocity and brutality, the cult allowed him to stay, and he built his own shrine to offer sacrifices and receive blessings from the ominous presence in the temple ruins.\",Portrait=M..\"dungeons\\\\bfd\\\\gelihast-portrait\",Frame=M..\"dungeons\\\\bfd\\\\gelihast-frame\",MapCoordinateX=38,MapCoordinateY=38.2,L=\"1470:15,80720:35,6906:50,6905:50\"},\n{Id=\"12902\",Name=\"Lorgus Jett\",Story=\"A mysterious member of the Twilight's Hammer, said to possess shamanic abilities depsite being a human. Rumors says he was a member of the Knight of the Silver Hand before deserting and joining the Twilight's Hammer.\",Portrait=M..\"dungeons\\\\bfd\\\\jett-portrait\",Frame=M..\"dungeons\\\\bfd\\\\jett-frame\",MapCoordinateX=42.3,MapCoordinateY=62.7},\n{Id=\"62530\",Name=\"Velthelaxx the Defiler\",Story=\"An ancient satyr, skulking in the ancient temple to Elune.\",Portrait=M..\"dungeons\\\\bfd\\\\velthelaxx-portrait\",Frame=M..\"dungeons\\\\bfd\\\\velthelaxx-frame\",MapCoordinateX=55.3,MapCoordinateY=63.6,L=\"58120:25,58121:25,58122:25,58123:25\"},\n{Id=\"4830\",Name=\"Old Serra'kis\",Story=\"Many of the creatures swimming beneath the Moonshrine Ruins were killed for food after the Twilight's Hammer cult took up residence, but the largest thresher in the water proved to be uncatchable, and those who persisted in hunting it inevitably died in the attempt.\",Portrait=M..\"dungeons\\\\bfd\\\\serrakis-portrait\",Frame=M..\"dungeons\\\\bfd\\\\serrakis-frame\",MapCoordinateX=53.4,MapCoordinateY=78.3,L=\"6904:33,6902:33,6901:33\"},\n{Id=\"4832\",Name=\"Twilight Lord Kelris\",Story=\"When the cultists found a strange three-headed creature in the belly of Blackfathom Deeps, Twilight Lord Kelris was convinced the hydra was a herald of the Old Gods' return to Azeroth... and his ticket to immortality. Kelris personally supervises the growth of the monster, even feeding him his own subjects to satisfy his wild hunger.\",Portrait=M..\"dungeons\\\\bfd\\\\kelris-portrait\",Frame=M..\"dungeons\\\\bfd\\\\kelris-frame\",MapCoordinateX=53.5,MapCoordinateY=87.5,L=\"1155:50,6903:35,80719:15\"},\n{Id=\"4829\",Name=\"Aku'mai\",Story=\"Aku'mai, an ancient evil, carries within her a small measure of the Old Gods' power. This three-headed hydra is greatly feared for her mindless savagery and insatiable hunger for living flesh, but the Twilight's Hammer worships her as a divine sign that the Old Gods will soon return.\",Portrait=M..\"dungeons\\\\bfd\\\\akumai-portrait\",Frame=M..\"dungeons\\\\bfd\\\\akumai-frame\",MapCoordinateX=77.8,MapCoordinateY=91.1,L=\"6909:33,6910:33,6911:33,51217:1\"},\n}}\nZLDB.DG[\"BM\"]={\nName=\"The Black Morass\",\nStory=\"Deep within the Caverns of Time, the Infinite Dragonflight seeks to alter the course of history by preventing the opening of the Dark Portal. Should they succeed, the orcs would never arrive on Azeroth, and the pivotal events that shaped the world's defense against the Burning Legion would be undone. To preserve the timeline, brave adventurers must venture back seventeen years into the swamplands of the Black Morass. There, they must protect the Guardian Medivh as he conducts his ritual, ensuring that the dark gateway opens and the threads of fate remain unbroken.\",\nBackground=M..\"dungeons\\\\bm\\\\background\",\nGridBackground=M..\"dungeons\\\\bm\\\\grid-background\",\nMapId=31,\nZoneId=2,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=34.3,MapCoordinateY=85.2,MapDestinationZoneId=2,MapZoneId=4}},\nType=T.Dungeon,\nKey=\"BM\",\nBosses={\n{Id=\"65113\",Name=\"Chronar\",Story=\"Once a proud defender of the timeways, Chronar broke his sacred oaths to the Bronze Dragonflight to consort with the Infinite. Now a twisted husk of his former self, he wields a 'Time-Worn Spear', a weapon he claimed from a human hero in a past conflict, as he works tirelessly to shatter the very history he once swore to protect.\",Portrait=M..\"dungeons\\\\bm\\\\chronar-portrait\",Frame=M..\"dungeons\\\\bm\\\\chronar-frame\",MapCoordinateX=32,MapCoordinateY=27.4,MapId=2,MapIsBelow=true,L=\"61016:17,61018:17,61019:17,61036:17,61047:17,61048:17,70226:1\"},\n{Id=\"61575\",Name=\"Epidamu\",Story=\"As the temporal anomalies within the morass intensify, creatures from across the boundaries of time are drawn to the conflict. Epidamu serves as a harbinger of the Infinite's will, using its reality-warping powers to siphon the essence of the swamp and manifest the Corrupted Sand that plagues the broken timelines.\",Portrait=M..\"dungeons\\\\bm\\\\epidamu-portrait\",Frame=M..\"dungeons\\\\bm\\\\epidamu-frame\",MapCoordinateX=26.1,MapCoordinateY=17.2,MapId=2,MapIsBelow=true,L=\"50431:12,61032:12,61041:12,61045:12,61055:12,61056:12,61698:12,61700:12\"},\n{Id=\"61316\",Name=\"Drifting Avatar of Sand\",Story=\"Formed from the collective weight of shattered possibilities, the Drifting Avatar of Sand is a mindless construct of the Infinite Dragonflight. It acts as a literal hourglass of doom, embodying the Corrupted Sand that leaks from the wounds in the timeline, crushing any who seek to repair the chronal damage.\",Portrait=M..\"dungeons\\\\bm\\\\avatar-portrait\",Frame=M..\"dungeons\\\\bm\\\\avatar-frame\",MapCoordinateX=32.8,MapCoordinateY=12.9,MapId=2,L=\"61015:14,61020:2,61024:14,61033:14,61038:14,61042:14,61044:14,61057:14,70226:1\"},\n{Id=\"65116\",Name=\"Time-Lord Epochronos\",Story=\"A high-ranking strategist of the Infinite Dragonflight, Epochronos oversees the tactical assault on Medivh's ritual. He views the linear flow of time as a cage and seeks to unlock a future where the Legion's ultimate defeat is averted, believing that his 'corrections' to the past are for the greater good of the multiverse.\",Portrait=M..\"dungeons\\\\bm\\\\epochronos-portrait\",Frame=M..\"dungeons\\\\bm\\\\epochronos-frame\",MapCoordinateX=29,MapCoordinateY=25.2,MapId=2,L=\"50428:12,50430:12,61017:12,61021:12,61022:12,61028:12,61049:1,61054:12,61058:12,70226:1\"},\n{Id=\"65124\",Name=\"Mossheart\",Story=\"The ancient bog beasts of the Black Morass have long been sensitive to the energies of the land. Mossheart, once a peaceful protector of the mire, has been driven to a state of primal fury by the temporal radiation leaking from the Dark Portal. It now lashes out at anything-bronze or infinite-that disturbs the murky depths of its home.\",Portrait=M..\"dungeons\\\\bm\\\\mossheart-portrait\",Frame=M..\"dungeons\\\\bm\\\\mossheart-frame\",MapCoordinateX=69.1,MapCoordinateY=51,MapId=1,L=\"61050:16,61051:16,61059:16,61060:16,61061:16,61062:16,70226:1\"},\n{Id=\"65125\",Name=\"Antnormi\",Story=\"Formerly a sister-in-arms to the bronze dragon Keridormi, Antnormi's betrayal is perhaps the most personal of all. Convinced that the arrival of the orcs is a tragedy that must be erased, she has embraced the Infinite path. She stands as the final obstacle in the southern timeway, willing to kill her former kin to see her vision of a 'pure' history realized.\",Portrait=M..\"dungeons\\\\bm\\\\antnormi-portrait\",Frame=M..\"dungeons\\\\bm\\\\antnormi-frame\",MapCoordinateX=48,MapCoordinateY=74.6,MapId=1,L=\"50427:50,61053:50,50429:33,61037:33,61046:33,51217:100,61014:1,61027:33,61031:33,61040:33,61043:1,70226:3\"},\n{Id=\"65122\",Name=\"Rotmaw\",Story=\"A massive crocolisk of legendary appetite, Rotmaw has feasted upon the displaced chronal energies of the swamp for years. The beast has grown unnaturally large and aggressive, its maw dripping with entropic rot. It cares little for the preservation of time, seeing the invaders of the Black Morass only as a much-needed feast.\",Portrait=M..\"dungeons\\\\bm\\\\rotmaw-portrait\",Frame=M..\"dungeons\\\\bm\\\\rotmaw-frame\",MapCoordinateX=25,MapCoordinateY=79.6,MapId=1,L=\"61023:12,61025:12,61029:12,61030:12,61034:12,61063:12,61699:12,61701:12,70226:1\"},\n}}\nZLDB.DG[\"BRD\"]={\nName=\"Blackrock Depths\",\nStory=\"The smoldering Blackrock Depths are home to the Dark Iron dwarves and their emperor, Dagran Thaurissan. Like his predecessors, he serves under the iron rule of Ragnaros the Firelord, a merciless being summoned into the world centuries ago. The presence of chaotic elementals has attracted Twilight's Hammer cultists to the mountain domain. Along with Ragnaros' servants, they have pushed the dwarves toward increasingly destructive ends that could soon spell doom for all of Azeroth.\",\nBackground=M..\"dungeons\\\\brd\\\\background\",\nGridBackground=M..\"dungeons\\\\brd\\\\grid-background\",\nMapId=14,\nIconScale=0.6,\nMinLevel=50,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=24.6,MapCoordinateY=12.6,MapZoneId=6}},\nType=T.Dungeon,\nKey=\"BRD\",\nBosses={\n{Id=\"9018\",Name=\"High Interrogator Gerstahn\",Story=\"The Twilight's Hammer cultist Gerstahn has always indulged in life's finer things: exotic foods, fine clothes, and gem-encrusted torture tools. Day and night, her prisoners' bloodcurdling cries echo throughout the Dark Iron clan's infamous Detention Block. Gerstahn proudly calls this horrific noise her symphony of screams, and she is always eager to add another voice to the chorus.\",Portrait=M..\"dungeons\\\\brd\\\\gerstahn-portrait\",Frame=M..\"dungeons\\\\brd\\\\gerstahn-frame\",MapCoordinateX=51.3,MapCoordinateY=93.6,L=\"11624:25,11625:25,11626:25,22240:25,51217:5,70226:2\"},\n{Id=\"9025\",Name=\"Lord Roccor\",Story=\"Lord Roccor loathes the scheming and backstabbing of his fellow fire elementals. To avoid serving alongside his kind in the Molten Core, the mighty being purposefully angered the Firelord. Roccor's risky gambit paid off: he was expelled from the core and forced to guard Blackrock Depths in isolation.\",Portrait=M..\"dungeons\\\\brd\\\\roccor-portrait\",Frame=M..\"dungeons\\\\brd\\\\roccor-frame\",MapCoordinateX=54.3,MapCoordinateY=77.9,IsRare=true,L=\"11624:25,11625:25,11626:25,22240:25,51217:5,11631:25,11632:25,22234:25,22397:25,11813:15,70226:2,11630:16\"},\n{Id=\"9319\",Name=\"Houndmaster Grebmar\",Story=\"Grebmar Fleabeard's hounds are the only family he's ever known. Long ago, the orphaned dwarf began breeding canines to serve as companions and guard dogs. When the houndmaster isn't patrolling Blackrock Depths with his loyal beasts, he often treats them to the Grim Guzzler's finest Dark Iron ale.\",Portrait=M..\"dungeons\\\\brd\\\\grebmar-portrait\",Frame=M..\"dungeons\\\\brd\\\\grebmar-frame\",MapCoordinateX=56.3,MapCoordinateY=69.1,L=\"11623:25,11627:25,11628:25,11629:25,51217:5,70226:2\"},\n{Id=\"9031\",Name=\"Ring of Law\",Story=\"There is only one punishment for crimes committed against the Dark Iron dwarves: death. Ancient tradition calls for the guilty to pay the blood price in the Ring of the Law by battling savage creatures gathered from across Azeroth. To date, it is unknown if anyone has ever survived this brutal crucible.\",Portrait=M..\"dungeons\\\\brd\\\\ring-portrait\",Frame=M..\"dungeons\\\\brd\\\\ring-frame\",MapCoordinateX=53.7,MapCoordinateY=71.7,L=\"11675:33,11677:33,11731:33,51217:5,70226:2,11678:15,11679:25,11685:25,11686:25,11730:25,22257:30,22271:30,22266:25,11726:15,11610:100,11702:25,11703:25,11722:25,22270:25,11633:25,11634:25,11635:25,11729:25,11662:25,11665:25,11728:25,11824:25\"},\n{Id=\"9024\",Name=\"Pyromancer Loregrain\",Story=\"Once a respected member of the Earthen Ring, Loregrain joined the Twilight's Hammer cult for reasons that remain a mystery to his former allies. He eventually journeyed to Blackrock Depths, where he took a sudden interest in the famed Dark Iron architect Franclorn Forgewright. The purpose of his current obsession is unclear, but Loregrain remains loyal to his cult and an enemy of all who oppose it.\",Portrait=M..\"dungeons\\\\brd\\\\loregrain-portrait\",Frame=M..\"dungeons\\\\brd\\\\loregrain-frame\",MapCoordinateX=57.1,MapCoordinateY=76,IsRare=true,L=\"70226:2,11207:16,11750:25,11749:25,11748:25,11747:25\"},\n{Id=\"9041\",Name=\"Warder Stilgiss\",Story=\"After years of dedication to Emperor Thaurissan, the cunning mage Stilgiss was entrusted with protecting his clan's coffers in the Black Vault. The loyal dwarf's close friend Houndmaster Grebmar celebrated the occasion by gifting one of his vicious dogs--Verek--to Stilgiss. The mage has put the beast to good use, keeping it at his side to scare off the vault's would-be thieves.\",Portrait=M..\"dungeons\\\\brd\\\\stilgiss-portrait\",Frame=M..\"dungeons\\\\brd\\\\stilgiss-frame\",MapCoordinateX=60.6,MapCoordinateY=53,IsRare=true,L=\"11782:25,11783:25,11784:25,22241:25,11755:13,22242:13,70226:2\"},\n{Id=\"9476\",Name=\"Watchman Doomgrip\",Story=\"As the watchman of the Black Vault, Doomgrip takes his occupation very seriously. If adventurers were to attempt to steal the contents of the vault, they would be certain to meet the wrath of the Dark Iron dwarf...\",Portrait=M..\"dungeons\\\\brd\\\\vault-portrait\",Frame=M..\"dungeons\\\\brd\\\\vault-frame\",MapCoordinateX=61.8,MapCoordinateY=54.6,L=\"22256:2,22205:2,22254:1\"},\n{Id=\"9056\",Name=\"Fineous Darkvire\",Story=\"Chief Architect Fineous Darkvire earned his title by passing off the ideas of more gifted masons as his own. His arrogance and scheming have drawn the ire of his predecessor, Franclorn Forgewright, from beyond the grave. The ghost of the late chief architect seeks to reclaim his incredibly powerful hammer--Ironfel--from Darkvire before it can be used for ill.\",Portrait=M..\"dungeons\\\\brd\\\\darkvire-portrait\",Frame=M..\"dungeons\\\\brd\\\\darkvire-frame\",MapCoordinateX=62.8,MapCoordinateY=41.2,L=\"11839:25,11841:25,11842:25,22223:25,56098:9,51217:5,70226:2,11840:5\"},\n{Id=\"9017\",Name=\"Lord Incendius\",Story=\"Baron Geddon taught Incendius to harness his destructive powers, but the baron never expected his protégé to grow so lethally efficient. Increasingly wary that Incendius might usurp him, Geddon sent the blazing elemental out of the Molten Core to guard the Dark Iron dwarves' fabled Black Anvil.\",Portrait=M..\"dungeons\\\\brd\\\\incendius-portrait\",Frame=M..\"dungeons\\\\brd\\\\incendius-frame\",MapCoordinateX=57.8,MapCoordinateY=48.5,L=\"11764:25,11765:25,11766:25,11767:25,51217:5,70226:2\"},\n{Id=\"9016\",Name=\"Bael'Gar\",Story=\"The monstrous molten giant Bael'Gar lumbers across the Dark Iron Highway, a stunning feat of dwarven engineering carved into Blackrock Depths. Ragnaros pulled the giant from the heart of the Firelands to guard a massive sealed door at one end of the highway. According to legend, only the Firelord and the Dark Iron clan's highest-ranking members know what lies beyond the mysterious gate.\",Portrait=M..\"dungeons\\\\brd\\\\baelgar-portrait\",Frame=M..\"dungeons\\\\brd\\\\baelgar-frame\",MapCoordinateX=35.1,MapCoordinateY=64.6,L=\"11802:25,11803:25,11805:25,11807:25,51217:5,70226:2\"},\n{Id=\"9033\",Name=\"General Angerforge\",Story=\"Through a lifetime of study, General Angerforge has become an expert on dwarven military history and tactics. He recently incurred Emperor Dagran Thaurissan's fury by writing a scathing treatise on his clan's failures in past conflicts. This political blunder aside, Angerforge is a Dark Iron to his core. He will bleed--and die, if necessary--to protect his people and his emperor.\",Portrait=M..\"dungeons\\\\brd\\\\angerforge-portrait\",Frame=M..\"dungeons\\\\brd\\\\angerforge-frame\",MapCoordinateX=42.7,MapCoordinateY=66.2,L=\"11810:20,11816:20,11817:20,11820:20,11821:20,51217:5,70226:2\"},\n{Id=\"8983\",Name=\"Golem Lord Argelmach\",Story=\"Argelmach's lifelong obsession with immortality drove him to forge enchanted constructs in his own image. Rumor has it that he has also dabbled in some form of black magic that would allow the golem lord's new creations to act as vessels for his spirit should his flesh-and-blood body be destroyed.\",Portrait=M..\"dungeons\\\\brd\\\\argelmach-portrait\",Frame=M..\"dungeons\\\\brd\\\\argelmach-frame\",MapCoordinateX=42.4,MapCoordinateY=52.1,L=\"11669:25,11819:25,11822:25,11823:25,51217:5,70226:2\"},\n{Id=\"9537\",Name=\"Hurley Blackbreath\",Story=\"To say Blackbreath is a regular at the Grim Guzzler would be something of an understatement. In over a decade, the mischievous drunkard has left the tavern only once to steal a top-secret recipe for Thunderbrew Lager. Blackbreath has occasionally sobered up enough to make the concoction himself, and he claims it grants unimaginable strength and courage.\",Portrait=M..\"dungeons\\\\brd\\\\blackbreath-portrait\",Frame=M..\"dungeons\\\\brd\\\\blackbreath-frame\",MapCoordinateX=51.2,MapCoordinateY=47.8,L=\"11735:25,18043:25,18044:25,22275:25,70226:2\"},\n{Id=\"9543\",Name=\"Ribbly Screwspigot\",Story=\"Screwspigot has a bad habit of borrowing money and squandering it on get-rich-quick schemes. His latest failure--Ribbly's Chewable Gunpowder--earned him a place on the hit list of Booty Bay's kingpin, Baron Revilgaz. Screwspigot has since fled to the Grim Guzzler, hoping to elude bounty hunters, friends, and family looking to cash in on the baron's bounty.\",Portrait=M..\"dungeons\\\\brd\\\\ribbly-portrait\",Frame=M..\"dungeons\\\\brd\\\\ribbly-frame\",MapCoordinateX=51.9,MapCoordinateY=51.3,L=\"2663:25,2662:25,11742:25,11612:3\"},\n{Id=\"9502\",Name=\"Phalanx\",Story=\"Until recently, drunken brawls raged within the Grim Guzzler on an almost daily basis. Barkeep Plugger Spazzring has reduced the frequency of these scuffles with Phalanx, a mighty golem bouncer programmed to maintain order in the tavern and eliminate raucous patrons with extreme force.\",Portrait=M..\"dungeons\\\\brd\\\\phalanx-portrait\",Frame=M..\"dungeons\\\\brd\\\\phalanx-frame\",MapCoordinateX=54.5,MapCoordinateY=50.6,L=\"11744:33,11745:33,22212:33,70226:2\"},\n{Id=\"9499\",Name=\"Plugger Spazzring\",Story=\"They say that at the Grim Guzzler everyone knows your name. This sense of camaraderie is due to the hard work of Spazzring, a leper gnome who sought a new life in Blackrock Depths after the fall of Gnomeregan. Despite his history of dabbling with evil as a warlock, he takes pride in his job as the tavern's barkeep, making sure that his patrons' mugs never run dry.\",Portrait=M..\"dungeons\\\\brd\\\\spazzring-portrait\",Frame=M..\"dungeons\\\\brd\\\\spazzring-frame\",MapCoordinateX=53.1,MapCoordinateY=49.4,L=\"18653:18,12793:18,12791:18\"},\n{Id=\"9156\",Name=\"Ambassador Flamelash\",Story=\"For his unwavering service to Ragnaros, Flamelash ascended to the rank of ambassador to the Dark Iron clan. This depraved being initially despised his dwarven allies, but he has come to respect their penchant for destruction. As a show of solidarity, Flamelash guards the Chamber of Enchantment, a sacred location used by the dwarves to empower their weaponry.\",Portrait=M..\"dungeons\\\\brd\\\\flamelash-portrait\",Frame=M..\"dungeons\\\\brd\\\\flamelash-frame\",MapCoordinateX=56.2,MapCoordinateY=39.5,L=\"11809:25,11812:25,11814:25,11832:25,11808:2,70226:2,51217:5\"},\n{Id=\"8923\",Name=\"Panzor the Invincible\",Story=\"An elusive golem, rarely seen among the general population of Blackrock Depths. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\brd\\\\panzor-portrait\",Frame=M..\"dungeons\\\\brd\\\\panzor-frame\",MapCoordinateX=50.6,MapCoordinateY=29.2,IsRare=true,L=\"11785:25,11786:25,11787:25,22245:25\"},\n{Id=\"9040\",Name=\"The Seven\",Story=\"Centuries ago, sorcerer-thane Thaurissan and seven of his most powerful Dark Iron allies accidentally summoned Ragnaros into Azeroth and damned their entire clan to enslavement. Although the Seven perished during the ritual, their restless spirits still linger in Blackrock Depths, cursed to serve their elemental master and the current Dark Iron ruler.\",Portrait=M..\"dungeons\\\\brd\\\\seven-portrait\",Frame=M..\"dungeons\\\\brd\\\\seven-frame\",MapCoordinateX=55.9,MapCoordinateY=20.7,L=\"11920:25,11923:25,11929:25,11926:25,11921:25,11922:25,11925:25,11927:25\"},\n{Id=\"9938\",Name=\"Magmus\",Story=\"Ambassador Flamelash charged the molten giant Magmus with guarding Emperor Dagran Thaurissan's throne room, but not even this act put the Dark Iron ruler's concerns to rest. Ever fearful of assassins, the emperor also granted Magmus control over a series of fire-breathing statues outside his royal chambers.\",Portrait=M..\"dungeons\\\\brd\\\\magmus-portrait\",Frame=M..\"dungeons\\\\brd\\\\magmus-frame\",MapCoordinateX=76.8,MapCoordinateY=10.4,L=\"11746:20,11935:20,22208:20,22395:20,22400:20,70226:2,51217:5\"},\n{Id=\"9019\",Name=\"Emperor Dagran Thaurissan\",Story=\"Emperor Dagran Thaurissan rules alongside Princess Moira of the rival Bronzebeard clan. Debate rages over whether the emperor ensorcelled his bride or she willingly joined him. Whatever the truth, Thaurissan's continued presence bodes ill for the future of his clan. So long as he lives, the Dark Irons will remain pawns of Ragnaros, and a dire threat to kingdoms throughout Azeroth.\",Portrait=M..\"dungeons\\\\brd\\\\emperor-portrait\",Frame=M..\"dungeons\\\\brd\\\\emperor-frame\",MapCoordinateX=85.6,MapCoordinateY=10.4,L=\"51217:100,56104:30,11924:20,11928:20,11932:20,11934:20,22207:20,11815:20,11930:20,11931:20,11933:20,22204:20,70226:3,11684:1,12553:25:n1,12554:25:n1,12556:25:n1,12557:25:n1\"},\n}}\nZLDB.DG[\"CG\"]={\nName=\"Crescent Grove\",\nStory=\"Hidden above the waterfalls of Mystral Lake, the Crescent Grove was once a tranquil sanctuary where druids and peaceful residents like Kalanar Brightshine tended to the forest in harmony. However, a dark shadow has fallen over the grove, clouding the minds of all who dwell within. The Foulweald furbolgs, fleeing madness in the north, found no refuge here; instead, they were twisted into the aggressive Groveweald tribe, their shamans and elders further fueling their savagery. Even the druidic protectors, led by Keeper Ranathos, have fallen silent or emerged warped by a deeper, more sinister source of corruption. Now, the Cenarion Circle calls upon brave souls to delve into the depths of the stone labyrinth and root out the evil festering at the grove's heart before it spreads across all of Kalimdor.\",\nBackground=M..\"dungeons\\\\cg\\\\background\",\nGridBackground=M..\"dungeons\\\\cg\\\\grid-background\",\nMapId=34,\nIconScale=0.9,\nMinLevel=33,\nMaxLevel=39,\nEntrances={{MapContinentId=1,MapCoordinateX=51,MapCoordinateY=77.3,MapZoneId=1}},\nType=T.Dungeon,\nKey=\"CG\",\nBosses={\n{Id=\"92107\",Name=\"Grovetender Engryss\",Story=\"Under the influence of the furbolg elders' persistent delusions, Grovetender Engryss has abandoned his original duty to protect the sanctuary. He now lashes out with irrational ferocity, acting as a tireless shield for the spiritual leaders whose maddening whisperings have entirely warped his sense of purpose.\",Portrait=M..\"dungeons\\\\cg\\\\engryss-portrait\",Frame=M..\"dungeons\\\\cg\\\\engryss-frame\",MapCoordinateX=52.1,MapCoordinateY=36.7,L=\"83220:24,83221:24,83222:24,83223:24,83224:5,51217:1\"},\n{Id=\"92109\",Name=\"Keeper Ranathos\",Story=\"Keeper Ranathos was originally stationed at the grove to repel the spreading taint, but his own erratic reports eventually signaled a tragic failure. Now fully corrupted and warped, he embodies the very evil he once fought, serving as a grim warning of the darkness that has taken hold beneath the waterfalls of Mystral Lake.\",Portrait=M..\"dungeons\\\\cg\\\\ranathos-portrait\",Frame=M..\"dungeons\\\\cg\\\\ranathos-frame\",MapCoordinateX=43.3,MapCoordinateY=43.5,L=\"83225:24,83226:24,83227:24,83228:24,83229:5,51217:1\"},\n{Id=\"92108\",Name=\"High Priestess A'lathea\",Story=\"Information regarding High Priestess A'lathea is absent from current Cenarion Circle research, leaving her as a shadowy figure known only to reside within the deeper reaches of the Crescent Grove.\",Portrait=M..\"dungeons\\\\cg\\\\alathea-portrait\",Frame=M..\"dungeons\\\\cg\\\\alathea-frame\",MapCoordinateX=57.6,MapCoordinateY=68.1,L=\"51217:1,83210:10,83211:30,83209:30,83208:30\"},\n{Id=\"92111\",Name=\"Fenektis the Deceiver\",Story=\"Beyond his reputation as a hostile and cunning presence inside the grove, Fenektis the Deceiver remains a total enigma to scholars and adventurers alike.\",Portrait=M..\"dungeons\\\\cg\\\\fenektis-portrait\",Frame=M..\"dungeons\\\\cg\\\\fenektis-frame\",MapCoordinateX=44,MapCoordinateY=78.9,L=\"83212:25,83213:25,83214:25,83215:25,51217:1\"},\n{Id=\"92110\",Name=\"Master Raxxieth\",Story=\"Identified as the core of the rot within the Crescent Grove, Master Raxxieth is the sinister architect of the region's downfall. He thrives on the misery and madness he has sown among both the furbolg and the druidic keepers, and his removal is the only hope for preventing the corruption from spreading as far as Mulgore.\",Portrait=M..\"dungeons\\\\cg\\\\raxxieth-portrait\",Frame=M..\"dungeons\\\\cg\\\\raxxieth-frame\",MapCoordinateX=60.3,MapCoordinateY=88.6,L=\"60258:1,51217:5,83219:25,83218:25,83217:25,83216:25\"},\n}}\nZLDB.DG[\"DEADMINES\"]={\nName=\"The Deadmines\",\nStory=\"Once the greatest gold production center in the human lands, the Deadmines were abandoned when the Horde razed Stormwind city during the First War. Now the Defias Brotherhood has taken up residence and turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook.\",\nBackground=M..\"dungeons\\\\deadmines\\\\background\",\nGridBackground=M..\"dungeons\\\\deadmines\\\\grid-background\",\nMapId=21,\nIconScale=0.9,\nMinLevel=16,\nMaxLevel=24,\nEntrances={{MapContinentId=2,MapCoordinateX=25,MapCoordinateY=51,MapZoneId=32}},\nType=T.Dungeon,\nKey=\"DEADMINES\",\nBosses={\n{Id=\"61961\",Name=\"Jared Voss\",Story=\"Jared Voss is the son of William Voss, a renowned alchemist whose shop and home were burned down with Stormwind and never rebuilt, leaving his family homeless and bitter toward the nobility responsible. Jared, apprenticed to the Stonemasons before his father's death, inherited both his alchemical talents and his burning resentment.\",Portrait=M..\"dungeons\\\\deadmines\\\\jared-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\jared-frame\",MapCoordinateX=28.5,MapCoordinateY=30.8,L=\"55377:50,55375:25,55376:25\"},\n{Id=\"644\",Name=\"Rhahk'Zor\",Story=\"As the Defias Brotherhood's head foreman of the Deadmines, Rhahk'Zor supervises and \\\"motivates\\\" the laborers. His methods, though unconventional, are quite effective.\",Portrait=M..\"dungeons\\\\deadmines\\\\rhahk-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\rhahk-frame\",MapCoordinateX=17.6,MapCoordinateY=53.4,Abilities={{Effect=\"Rhahk'Zor slams an enemy, dealing 64 to 86 physical damage and stunning them for 3 seconds.\",Icon=\"INV_Gauntlets_05\",Id=\"6304\",Name=\"Rhahk'Zor Slam\"}},L=\"9496:100,872:33,5187:33,80706:33\"},\n{Id=\"3586\",Name=\"Miner Johnson\",Story=\"An elusive miner, rarely seen among the general population of the Deadmines. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\deadmines\\\\miner-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\miner-frame\",MapCoordinateX=31,MapCoordinateY=43.8,IsRare=true,Abilities={{Effect=\"Miner Johnson lunges his pickaxe into his enemy, piercing their armor and reducing its armor value by 10% for 10 seconds.\",Icon=\"Spell_Shadow_VampiricAura\",Id=\"6016\",Name=\"Pierce Armor\"}},L=\"5444:65,5443:35\"},\n{Id=\"643\",Name=\"Sneed\",Story=\"Sneed was hired as a lumbermaster for his ruthless efficiency. His goal is simple: construct a juggernaut as cheaply as possible. By using the shredder he built himself to lead production, he achieves terrifyingly fast results.\",Portrait=M..\"dungeons\\\\deadmines\\\\sneed-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\sneed-frame\",MapCoordinateX=29.8,MapCoordinateY=74.5,Abilities={{Effect=\"Sneed disarms his enemy, forcing them to stop wielding their weapon for 5 seconds.\",Flags={F.Tank},Icon=\"Ability_Warrior_Disarm\",Id=\"6713\",Name=\"Disarm\"}},L=\"50256:100,5195:65,80707:60,5194:35\"},\n{Id=\"1763\",Name=\"Gilnid\",Story=\"Glinid is a masterful engineer and head smelter of the Defias Brotherhood's operations. He ensures the juggernaut is loaded with sufficient cannons and ammunition and will tolerate no breaks until the work is complete.\",Portrait=M..\"dungeons\\\\deadmines\\\\gilnid-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\gilnid-frame\",MapCoordinateX=38.8,MapCoordinateY=51.4,Abilities={{Effect=\"Glinid throws molten metal to an enemy, inflicting fire damage every 3 seconds, increasing the time between their attacks by 54%, and reducing their movement by 50% for 15 seconds.\",Icon=\"Spell_Fire_Fireball\",Id=\"5213\",Name=\"Molten Metal\"}},L=\"5199:55,1156:45\"},\n{Id=\"61963\",Name=\"Masterpiece Harvester\",Story=\"The goblin mechanics of the Defias pride themselves on their greatest creation: the Masterpiece Harvester. Built deep within their hidden workshop, it is the finest harvest golem they have ever produced.\",Portrait=M..\"dungeons\\\\deadmines\\\\harvester-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\harvester-frame\",MapCoordinateX=36.8,MapCoordinateY=25.2,L=\"55380:50,55378:25,55379:25\"},\n{Id=\"646\",Name=\"Mr. Smite\",Story=\"As Captain Greenskin's first mate, Smite is tasked with keeping the crew on their toes. Smite is a skilled weaponmaster, trained in all manner of slicing and bashing.\",Portrait=M..\"dungeons\\\\deadmines\\\\smite-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\smite-frame\",MapCoordinateX=71.3,MapCoordinateY=11.6,Abilities={{Effect=\"Mr. Smite's nimble reflexes allows him to increase his chance to parry by 75% for 8 seconds.\",Icon=\"Ability_MeleeDamage\",Id=\"6264\",Name=\"Nimble Reflexes\"},{Effect=\"Mr. Smite slam his enemy, inflicting 50 physical damage and stunning them for 3 seconds.\",Icon=\"INV_Gauntlets_05\",Id=\"6435\",Name=\"Smite Slam\"},{Effect=\"Mr. Smite stomps the ground, stunning all enemies for 10 seconds.\",Flags={F.Important,F.Deadly},Icon=\"Ability_WarStomp\",Id=\"6432\",Name=\"Smite Stomp\"},{Effect=\"Mr. Smite gains a chance to do two additional attacks.\",Icon=\"Ability_GhoulFrenzy\",Id=\"3417\",Name=\"Thrash\"}},L=\"5192:30,5196:30,81007:20,7230:20\"},\n{Id=\"647\",Name=\"Captain Greenskin\",Story=\"Captain of the juggernaut-in-progress, Greenskin hails from Booty Bay where he formerly led a fleet of pirate vessels.\",Portrait=M..\"dungeons\\\\deadmines\\\\captain-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\captain-frame\",MapCoordinateX=75.6,MapCoordinateY=22.4,Abilities={{Effect=\"Captain Greenskin stabs his enemy with his poisoned harpoon, inflicting physical damage plus 30, then an additional 45 nature damage every 10 seconds for 1 minute.\",Flags={F.Poison},Icon=\"Ability_Poisons\",Id=\"5208\",Name=\"Poisoned Harpoon\"},{Effect=\"Captain Greenskin cleaves all enemies in front of him.\",Icon=\"Ability_Warrior_Cleave\",Id=\"845\",Name=\"Cleave\"}},L=\"5201:40,5200:30,10403:30\"},\n{Id=\"639\",Name=\"Edwin VanCleef\",Story=\"Formerly the leader of the Stonemasons Guild, disputes with the House of Nobles led VanCleef to leave Stormwind City and create the Defias Brotherhood. VanCleef then claimed the Deadmines as a base of operations to construct the juggernaut that would begin his retribution.\",Portrait=M..\"dungeons\\\\deadmines\\\\vancleef-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\vancleef-frame\",MapCoordinateX=75.7,MapCoordinateY=28.1,Abilities={{Effect=\"Edwin VanCleef gains a chance to do two additional attacks.\",Icon=\"Ability_GhoulFrenzy\",Id=\"3417\",Name=\"Trash\"},{Effect=\"Edwin VanCleef call upon his allies, summoning a pair of Defias Blackguards to assist him during the battle.\",Flags={F.Important,F.Tank},Icon=\"Ability_Warrior_BattleShout\",Id=\"5200\",Name=\"VanCleef's Allies\"}},L=\"29980:100,5193:30,5202:30,5191:20,10399:20,81005:8\"},\n{Id=\"645\",Name=\"Cookie\",Story=\"No one except Edwin VanCleef knows how or why Cookie was promoted to be the ship's cook. For pirates, though, a meal is a meal.\",Portrait=M..\"dungeons\\\\deadmines\\\\cookie-portrait\",Frame=M..\"dungeons\\\\deadmines\\\\cookie-frame\",MapCoordinateX=81,MapCoordinateY=24.5,Abilities={{Effect=\"Cookie throws some acidic goop onto his enemies, cause everyone nearby to receive nature damage every 5 seconds for 30 seconds.\",Flags={F.Poison},Icon=\"INV_Drink_06\",Id=\"6306\",Name=\"Acid Splash\"},{Effect=\"Cookie eats some of his food, healing him for 111 to 129 health.\",Flags={F.Interruptible},Icon=\"Spell_Holy_Heal\",Id=\"5174\",Name=\"Cookie's Cooking\"}},L=\"9338:100,5197:65,80708:60,5198:35,8490:15\"},\n}}\nZLDB.DG[\"DME\"]={\nName=\"Dire Maul East\",\nStory=\"The Warpwood Quarter is located east in Dire Maul. It has been taken over by the nefarious Alzzin the Wildshaper, a satyr who has corrupted the Fruit of Fertility so that it produces vile Felvine Shards. Alzzin has attracted all manner of corrupted plant life, satyrs, mages and demons to his cause. The entire district is overgrown with crazed plant life.\",\nBackground=M..\"dungeons\\\\dme\\\\background\",\nGridBackground=M..\"dungeons\\\\dme\\\\grid-background\",\nMapId=13,\nIconScale=0.7,\nMinLevel=55,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=81.5,MapCoordinateY=40.7,MapZoneId=8},{MapContinentId=1,MapCoordinateX=94.3,MapCoordinateY=66.4,MapZoneId=8}},\nType=T.Dungeon,\nKey=\"DME\",\nBosses={\n{Id=\"14354\",Name=\"Pusillin\",Story=\"A cowardly little imp, tricking adventurers into following him, only to turn on them, killing them and stealing all the belongings from their bodies.\",Portrait=M..\"dungeons\\\\dme\\\\pusillin-portrait\",Frame=M..\"dungeons\\\\dme\\\\pusillin-frame\",MapCoordinateX=89.7,MapCoordinateY=75.3,L=\"18267:100,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10\"},\n{Id=\"13280\",Name=\"Hydrospawn\",Story=\"When the satyr Zevrim Thornhoof sought to control the elementals in Dire Maul, he focused on Hydrospawn, who calmly resided in the pool beneath his altar. As he performed his profane sacrificial rituals, the elemental grew agitated and restless, striking out at Thornhoof's demonic minions. As the years passed, Thornhoof used his victims' energies to whip Hydrospawn into unbridled fury, little by little binding its will to the satyr's commands.\",Portrait=M..\"dungeons\\\\dme\\\\hydrospawn-portrait\",Frame=M..\"dungeons\\\\dme\\\\hydrospawn-frame\",MapCoordinateX=76.4,MapCoordinateY=75,MapIsBelow=true,L=\"18305:20,18307:20,18317:20,18322:20,18324:20,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,51217:5,70226:2\"},\n{Id=\"11490\",Name=\"Zevrim Thornhoof\",Story=\"Desperate to show his worth to the Burning Legion, Zevrim Thornhoof told his masters he could enslave the formidable ancients who still roamed Dire Maul. When his own power proved insufficient, Thornhoof turned to other living creatures for additional energy, butchering them atop his sacrificial altar and harvesting their essence in their final, agonizing moments.\",Portrait=M..\"dungeons\\\\dme\\\\zevrim-portrait\",Frame=M..\"dungeons\\\\dme\\\\zevrim-frame\",MapCoordinateX=76.4,MapCoordinateY=79.4,MapIsBelow=true,L=\"18306:20,18308:20,18313:20,18319:20,18323:20,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,70226:2,51217:5\"},\n{Id=\"14327\",Name=\"Lethtendris\",Story=\"Dire Maul's warped energy drew Lethtendris from afar, giving her hope of satisfying her unbearable craving for arcane magic. Using the sinews and ligaments of sacrificial victims, she constructed a web to siphon the corrupt power out of the east wing. To her delight, she discovered that the device has the capacity to gather vast reserves of overwhelming strength, enough to destroy all of her enemies.\",Portrait=M..\"dungeons\\\\dme\\\\lethtendris-portrait\",Frame=M..\"dungeons\\\\dme\\\\lethtendris-frame\",MapCoordinateX=74.3,MapCoordinateY=76.9,L=\"18301:25,18302:25,18311:25,18325:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11492\",Name=\"Alzzin the Wildshaper\",Story=\"Alzzin the Wildshaper was not always the creature that now festers within Dire Maul. Once a druid of Hyjal and a bearer of the very title he still claims, he has become a twisted mockery of the ideals he once upheld. Now counted among the satyrs, Alzzin seeks nothing less than the total corruption of Feralas. Within the Shrine of Eldretharr, he has bound ancient spirits to his will, drawing upon the vitality of the forest to shape and control it as he pleases. Where he once nurtured life, he now perverts it, turning the wilds into an extension of his own corruption.\",Portrait=M..\"dungeons\\\\dme\\\\alzzin-portrait\",Frame=M..\"dungeons\\\\dme\\\\alzzin-frame\",MapCoordinateX=75.8,MapCoordinateY=55.3,L=\"51217:100,18309:10,18310:10,18312:10,18314:10,18315:10,18318:10,18321:10,18326:10,18327:10,18328:10,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,47413:10,47415:10,83574:10,70226:3\"},\n}}\nZLDB.DG[\"DMN\"]={\nName=\"Dire Maul North\",\nStory=\"The Gordok Commons are located north in Dire Maul. This area of the city has been taken over by the Gordok, the elite members of the Gordunni ogre clan, and are now the seat of power for King Gordok himself. By tradition, however, whoever slays the king will become the new King Gordok.\",\nBackground=M..\"dungeons\\\\dmn\\\\background\",\nGridBackground=M..\"dungeons\\\\dmn\\\\grid-background\",\nMapId=13,\nIconScale=0.7,\nMinLevel=57,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=70.2,MapCoordinateY=13.5,MapZoneId=8}},\nType=T.Dungeon,\nKey=\"DMN\",\nBosses={\n{Id=\"14326\",Name=\"Guard Mol'dar\",Story=\"Mol'dar is a zealously loyal guard from the Gordok ogres. He is convinced King Gordok gifted him with a pair of enchanted gauntlets that have enabled him to become his people's arm wrestling champion for six years running. In truth, King Gordok threw the powerful armor away; Mol'dar simply found it first.\",Portrait=M..\"dungeons\\\\dmn\\\\moldar-portrait\",Frame=M..\"dungeons\\\\dmn\\\\moldar-frame\",MapCoordinateX=52.4,MapCoordinateY=44.5,L=\"18450:8,18451:8,18458:8,18459:8,18460:8,18462:8,18463:8,18464:8,18493:8,18494:8,18496:8,18497:8,18498:8,51217:5,70226:2\"},\n{Id=\"14322\",Name=\"Stomper Kreeg\",Story=\"On more than one occasion, skulking assassins have met their doom after accidentally disturbing Kreeg's ale mug. Though he's often passed out drunk on duty, nothing rouses the ogre into a berserker fury faster than the sound of his precious drink splattering on the stone floor.\",Portrait=M..\"dungeons\\\\dmn\\\\kreeg-portrait\",Frame=M..\"dungeons\\\\dmn\\\\kreeg-frame\",MapCoordinateX=46.3,MapCoordinateY=38.5,L=\"18425:40,70226:2\"},\n{Id=\"14321\",Name=\"Guard Fengus\",Story=\"Ever since Cho'Rush the Observer told him he was destined to meet a mate while on duty, Fengus has spent almost every waking moment patrolling Gordok territory.\",Portrait=M..\"dungeons\\\\dmn\\\\fengus-portrait\",Frame=M..\"dungeons\\\\dmn\\\\fengus-frame\",MapCoordinateX=39.2,MapCoordinateY=45.4,L=\"18450:13,18451:13,18458:13,18459:13,18460:13,18462:13,18463:13,18464:13,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"14323\",Name=\"Guard Slip'kik\",Story=\"Some might think Slip'kik is merely cautious, but he's also lazy. Rather than challenge King Gordok directly, Slip'kik tinkers with traps and old, broken magical devices, hoping to eventually deliver a coup de grace without an ounce of risk or a drop of sweat.\",Portrait=M..\"dungeons\\\\dmn\\\\slipkik-portrait\",Frame=M..\"dungeons\\\\dmn\\\\slipkik-frame\",MapCoordinateX=21.8,MapCoordinateY=37.5,L=\"18450:8,18451:8,18458:8,18459:8,18460:8,18462:8,18463:8,18464:8,18493:8,18494:8,18496:8,18497:8,18498:8,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18362:1,18361:1,18363:1,18364:1,18401:1\"},\n{Id=\"14325\",Name=\"Captain Kromcrush\",Story=\"Even among ogres, Captain Kromcrush is infamous for his hair-trigger rage toward anyone who dares to insult him or King Gordok. He crushes dissent ruthlessly, but he has still less patience for those who continue to spread the rumor of his torrid affair with a gnoll long ago.\",Portrait=M..\"dungeons\\\\dmn\\\\kromcrush-portrait\",Frame=M..\"dungeons\\\\dmn\\\\kromcrush-frame\",MapCoordinateX=27.5,MapCoordinateY=28.4,L=\"18502:25,18503:25,18505:25,18507:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11501\",Name=\"King Gordok\",Story=\"To rule the Gordok ogres, one must simply proclaim oneself king... and then destroy all who might disagree. King Gordok--then merely known as Ulrok--solidified his power by convincing a dozen of his people's strongest warriors to challenge the king at the same time. The wild melee left most of the contestants dead or wounded, and Ulrok's blade easily cut down the survivors and the battle-weary king. To this day, Gordok ogres speak in hushed tones about the \\\"Day of Da Blood.\\\"\",Portrait=M..\"dungeons\\\\dmn\\\\gordok-portrait\",Frame=M..\"dungeons\\\\dmn\\\\gordok-frame\",MapCoordinateX=27.8,MapCoordinateY=11.8,L=\"51217:100,18520:13,18522:13,18521:13,18523:13,18524:13,18525:13,18526:13,18527:13,47413:10,47415:10,18780:9,70226:3,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1,18538:1:n2,18655:11:n2,18482:11:n2,18481:11:n2,18480:11:n2,18479:11:n2,18478:11:n2,18477:11:n2,18476:11:n2,18475:11:n2,18532:23:n2,18531:23:n2,18530:23:n2,18499:23:n2,18537:25:n2,18534:25:n2,18533:25:n2,18495:25:n2,18529:33:n2,18528:33:n2,18500:33:n2\"},\n}}\nZLDB.DG[\"DMR\"]={\nName=\"Dragonmaw Retreat\",\nStory=\"Hidden within the decrepit mining facilities far to the east of the Wetlands, the Dragonmaw Retreat serves as the final bastion for the seasoned veterans of the Second War. Following their defeat at Grim Batol, these orcs have gathered beneath the mountain to rebuild their strength, kidnapping citizens from Menethil Harbor and conducting heinous rituals to bolster their ranks. Under the fanatical leadership of Zuluhed the Whacked, who has returned bearing a shard of the legendary Demon Soul, the clan has once again begun the brutal subjugation of the Red Dragonflight. Adventurers must navigate the unstable shafts and ancient dwarven halls to extinguish the Dragonmaw's influence before their 'Dark Horde' can rise again.\",\nBackground=M..\"dungeons\\\\dmr\\\\background\",\nGridBackground=M..\"dungeons\\\\dmr\\\\grid-background\",\nMapId=41,\nIconScale=0.9,\nMinLevel=26,\nMaxLevel=35,\nEntrances={{MapContinentId=2,MapCoordinateX=67.3,MapCoordinateY=63.3,MapZoneId=39}},\nType=T.Dungeon,\nKey=\"DMR\",\nBosses={\n{Id=\"62057\",Name=\"Gowlfang\",Story=\"Gowlfang was once the leader of the Mosshide gnolls before he abandoned his people to side with the Dragonmaw orcs. Driven by a slobbering, unbridled rage, this 'big betrayer' now leads a splinter group of Mosshides in service to the green-skinned warriors. He guards the entrance to the mountain caves with savage ferocity, eager to prove his worth to the masters of the fire-breathing lizards.\",Portrait=M..\"dungeons\\\\dmr\\\\gowlfang-portrait\",Frame=M..\"dungeons\\\\dmr\\\\gowlfang-frame\",MapCoordinateX=12.1,MapCoordinateY=36.6,L=\"41571:20,41572:20,41573:20,41574:20,41575:20\"},\n{Id=\"62066\",Name=\"Cavernweb Broodmother\",Story=\"The Dragonmaw orcs have used their dark arts to enslave and magically enhance the arachnids living within the mining shafts of Grim Batol. The Cavernweb Broodmother is the terrifying result of these rituals, possessing an unparalleled poison that causes agonizing pain. She and her enhanced brood act as a lethal defense mechanism, protecting the deeper reaches of the retreat from any who would disrupt the clan's operations.\",Portrait=M..\"dungeons\\\\dmr\\\\broodmother-portrait\",Frame=M..\"dungeons\\\\dmr\\\\broodmother-frame\",MapCoordinateX=33.1,MapCoordinateY=46.3,L=\"58039:20,58040:20,58041:20,58042:20,58043:20,37009:10\"},\n{Id=\"62067\",Name=\"Web Master Torkon\",Story=\"Little information is available regarding Web Master Torkon, though his presence has been noted as a significant inhabitant of the Dragonmaw Retreat.\",Portrait=M..\"dungeons\\\\dmr\\\\torkon-portrait\",Frame=M..\"dungeons\\\\dmr\\\\torkon-frame\",MapCoordinateX=37.5,MapCoordinateY=63.7,L=\"41874:100,41566:20,41567:20,41568:20,41569:20,41570:20\"},\n{Id=\"62071\",Name=\"Garlok Flamekeeper\",Story=\"Garlok is a powerful pyremaster who nurtures the 'Eternal Flame,' a source of potent energy kept hidden by the orcs' primitive sorcery. He protects this ancient magic with a fanatical devotion, using the flame to power the Dragonmaw's machinations. For those seeking to undermine the clan or claim the relic for the Dark Lady, Garlok stands as a wall of incinerating heat.\",Portrait=M..\"dungeons\\\\dmr\\\\garlok-portrait\",Frame=M..\"dungeons\\\\dmr\\\\garlok-frame\",MapCoordinateX=42,MapCoordinateY=64.7,L=\"41578:25,41579:25,41580:25,41581:25\"},\n{Id=\"62069\",Name=\"Halgan Redbrand\",Story=\"A spectral reminder of the mine's dwarven past, Halgan Redbrand haunts the halls where his family once worked. He guards the Redbrand Tablet, an ancient piece of dwarven typography that holds a shocking secret: the lineage of the Redbrand family, long thought to be Bronzebeard, actually lies deep within the Wildhammer clan. Halgan's lingering ghost is all that remains of this forgotten chapter of Khaz Modan's history.\",Portrait=M..\"dungeons\\\\dmr\\\\halgan-portrait\",Frame=M..\"dungeons\\\\dmr\\\\halgan-frame\",MapCoordinateX=34.8,MapCoordinateY=92.5,L=\"58044:25,58045:25,58046:25,58047:25,76:6,77:6\"},\n{Id=\"62068\",Name=\"Slagfist Destroyer\",Story=\"An ancient stone golem still following protocols from the mine's original dwarven builders, Slagfist Destroyer roams the unstable tunnels of the retreat. Powered by a glowing runestone, this crumbling construct views the orcish occupiers and intruding adventurers alike as threats to be dismantled. It is a mindless relic of industry, serving as a dangerous obstacle in the dark.\",Portrait=M..\"dungeons\\\\dmr\\\\slagfist-portrait\",Frame=M..\"dungeons\\\\dmr\\\\slagfist-frame\",MapCoordinateX=45,MapCoordinateY=90.1,L=\"41558:25,41559:25,41560:25,41719:25\"},\n{Id=\"62070\",Name=\"Overlord Blackheart\",Story=\"A true monster through and through, Overlord Blackheart is the architect of the vicious raiding parties that plague the Wetlands. Responsible for the abduction and death of many citizens of Menethil Harbor, he is the iron fist of the Dragonmaw veterans. As the primary military leader within the retreat, his demise is essential to ensuring the safety of the southern lands.\",Portrait=M..\"dungeons\\\\dmr\\\\blackheart-portrait\",Frame=M..\"dungeons\\\\dmr\\\\blackheart-frame\",MapCoordinateX=53.3,MapCoordinateY=65.5,L=\"41724:25,41725:25,41726:25,41727:25,74:6\"},\n{Id=\"62038\",Name=\"Elder Hollowblood\",Story=\"Records regarding Elder Hollowblood are remarkably scarce, aside from the fact that he is a confirmed denizen of the Dragonmaw Retreat.\",Portrait=M..\"dungeons\\\\dmr\\\\hollowblood-portrait\",Frame=M..\"dungeons\\\\dmr\\\\hollowblood-frame\",MapCoordinateX=56.9,MapCoordinateY=55.8,L=\"41720:25,41721:25,41722:25,41723:25,31:6\"},\n{Id=\"62072\",Name=\"Searistrasz\",Story=\"The brother of Nydiszanz, Searistrasz is a noble red dragon currently suffering the 'plight of submission.' Enslaved by the Dragonmaw using the power of the Demon Soul, he is forced to follow their heinous bidding within the ancient mines. His painful cries echo through the caverns, a tragic testament to the orcs' continued subjugation of the Red Dragonflight.\",Portrait=M..\"dungeons\\\\dmr\\\\searistrasz-portrait\",Frame=M..\"dungeons\\\\dmr\\\\searistrasz-frame\",MapCoordinateX=52.9,MapCoordinateY=36.2,L=\"41561:20,41562:20,41563:20,41564:20,41565:20\"},\n{Id=\"62037\",Name=\"Zuluhed the Whacked\",Story=\"The mad Chieftain of the Dragonmaw Clan, Zuluhed has returned to Azeroth bearing a glimmering shard of the original Demon Soul. While some within his clan, like Korlag Doomsong, view him as a coward who abandoned them for his own glory, Zuluhed continues to plot in the underbelly of Grim Batol. He remains determined to unite the chieftains under his banner, using the shard's tainted power to once again enslave the flight of the Dragon Queen.\",Portrait=M..\"dungeons\\\\dmr\\\\zuluhed-portrait\",Frame=M..\"dungeons\\\\dmr\\\\zuluhed-frame\",MapCoordinateX=41.9,MapCoordinateY=47.1,L=\"41845:20,41846:20,41847:20,41848:20,58099:20,69:5,71:5,41895:2\"},\n}}\nZLDB.DG[\"DMW\"]={\nName=\"Dire Maul West\",\nStory=\"The Capital Gardens are located west in Dire Maul. The area might once have been a pristine city park district, but now the trees stand gray and withered, and the broken streets are full of dangerous ancients.\",\nBackground=M..\"dungeons\\\\dmw\\\\background\",\nGridBackground=M..\"dungeons\\\\dmw\\\\grid-background\",\nMapId=13,\nIconScale=0.7,\nMinLevel=57,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=57.4,MapCoordinateY=39.2,MapZoneId=8},{MapContinentId=1,MapCoordinateX=57.4,MapCoordinateY=49.9,MapZoneId=8}},\nType=T.Dungeon,\nKey=\"DMW\",\nBosses={\n{Id=\"11489\",Name=\"Tendris Warpwood\",Story=\"Tendris Warpwood was a staunch defender of Eldre'Thalas, his heart inexorably entwined with the fate of the city. When the Sundering shattered the land, his resolve never wavered, but as corruption seeped into the ruins over the next 10,000 years, so too did it infect the ancient's spirit.\",Portrait=M..\"dungeons\\\\dmw\\\\tendris-portrait\",Frame=M..\"dungeons\\\\dmw\\\\tendris-frame\",MapCoordinateX=28.1,MapCoordinateY=75,L=\"18352:25,18353:25,18390:25,18393:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11488\",Name=\"Illyanna Ravenoak\",Story=\"Illyanna Ravenoak, along with her faithful companion Ferra, was once Prince Tortheldrin's most valued hunter, until she refused to carry out her leader's order to execute her friends. As punishment, he killed Illyanna and her bear, but he used his demonic power to bind their spirits to their bodies, condemning them to remain in Dire Maul as undead protectors.\",Portrait=M..\"dungeons\\\\dmw\\\\ravenoak-portrait\",Frame=M..\"dungeons\\\\dmw\\\\ravenoak-frame\",MapCoordinateX=24.4,MapCoordinateY=81.5,L=\"18347:25,18349:25,18383:25,18386:25,55580:17,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11487\",Name=\"Magister Kalendris\",Story=\"When Prince Tortheldrin demanded the slaughter of the majority of his subjects, his most loyal lieutenants were tasked with executing his will. Magister Kalendris murdered many unsuspecting Shen'dralar without hesitation, but one of the doomed elves mortally wounded him during a destructive battle. Despite his demise, Kalendris's spirit still roams Dire Maul as a defender of Tortheldrin's rule.\",Portrait=M..\"dungeons\\\\dmw\\\\kalendris-portrait\",Frame=M..\"dungeons\\\\dmw\\\\kalendris-frame\",MapCoordinateX=24.4,MapCoordinateY=68.7,L=\"18350:20,18351:20,18371:20,18374:20,18397:20,22309:15,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11467\",Name=\"Tsu'zee\",Story=\"An elusive ghost of a night elf, rarely seen among the denizens of the Capital Gardens. She is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter her in the first place...\",Portrait=M..\"dungeons\\\\dmw\\\\tsuzee-portrait\",Frame=M..\"dungeons\\\\dmw\\\\tsuzee-frame\",MapCoordinateX=29.1,MapCoordinateY=66.5,L=\"18345:33,18346:33,18387:33\"},\n{Id=\"11496\",Name=\"Immol'thar\",Story=\"In a desperate bid to restore the power and immortality they lost when the Well of Eternity was destroyed, the Shen'dralar summoned a demon into the western wing of Dire Maul and captured him within a force field, allowing them to use the void terror's energy for their own spells. Unable to fight back or even move for nearly 10,000 years, Immol'thar could only watch and wait for the day he might break free and rend the flesh of his captors.\",Portrait=M..\"dungeons\\\\dmw\\\\immolthar-portrait\",Frame=M..\"dungeons\\\\dmw\\\\immolthar-frame\",MapCoordinateX=10.2,MapCoordinateY=78.8,L=\"18370:10,18372:10,18377:10,18379:10,18381:10,18384:10,18385:10,18389:10,18391:10,18394:10,47413:10,47415:10,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1\"},\n{Id=\"11486\",Name=\"Prince Tortheldrin\",Story=\"After the Well of Eternity's destruction, Prince Tortheldrin maintained control over the surviving Shen'dralar by imprisoning a demon in the ruins of Eldre'Thalas and letting his subjects siphon its strength. The exposure to demonic power twisted Tortheldrin's mind, and when the creature faltered, the prince ordered the deaths of many of his vassals so only he and his most fanatical followers would be left to enjoy the corrupt energy.\",Portrait=M..\"dungeons\\\\dmw\\\\prince-portrait\",Frame=M..\"dungeons\\\\dmw\\\\prince-frame\",MapCoordinateX=20.9,MapCoordinateY=65.7,L=\"51217:100,18373:10,18375:10,18376:10,18378:10,18380:10,18382:10,18388:10,18392:10,18395:10,18396:10,70226:3\"},\n}}\nZLDB.DG[\"FH\"]={\nName=\"Frostmane Hollow\",\nStory=\"Nestled deep within the frozen peaks of Dun Morogh, Frostmane Hollow has been the stronghold of the Frostmane tribe since long before the dwarves carved their great halls into the mountain. Once a proud and expansive people, the Frostmane have been pushed further and further into the cold by Ironforge's relentless expansion; their hunting grounds seized, their shrines defiled. What remains of the tribe has grown feral with fury, conducting raids on dwarven settlements with a ferocity born not of savagery, but of desperation. To the Frostmane, this is not war. It is survival.\",\nBackground=M..\"dungeons\\\\fh\\\\background\",\nGridBackground=M..\"dungeons\\\\fh\\\\grid-background\",\nMapId=46,\nIconScale=1,\nMinLevel=13,\nMaxLevel=20,\nEntrances={{MapContinentId=2,MapCoordinateX=66.9,MapCoordinateY=40.3,MapZoneId=10}},\nType=T.Dungeon,\nKey=\"FH\",\nBosses={\n{Id=\"tansha\",Name=\"Tan'sha the Sleek\",Story=\"Frostmane Hollow keeps its secrets well - Tan'sha the Sleek among them.\",Portrait=M..\"dungeons\\\\fh\\\\tansha-portrait\",Frame=M..\"dungeons\\\\fh\\\\tansha-frame\",MapCoordinateX=16.2,MapCoordinateY=14.5,Abilities={{Icon=\"ability_mount_whitetiger\",Id=\"tansha\",Name=\"Tan'sha the Sleek\",SubAbilities={{Effect=\"Tan'sha shouts at nearby enemies, causing them to flee in fear for 8 seconds.\",Flags={F.Important},Icon=\"ability_golemthunderclap\",Id=\"tanshaintimidatingshout\",Name=\"Intimidating Shout\"}}},{Icon=\"inv_ammo_arrow_02\",Id=\"oboka\",Name=\"Handler Oboka\",SubAbilities={{Effect=\"Oboka stops fighting to heal Tan'sha.\",Icon=\"ability_hunter_mendpet\",Id=\"obokamendpet\",Name=\"Mend Pet\"}}}},L=\"162:33,184:33,197:33\"},\n{Id=\"ubukaz\",Name=\"Battlemaster Ubukaz\",Story=\"No chronicle, no record, no account - Battlemaster Ubukaz exists beyond the reach of history entirely.\",Portrait=M..\"dungeons\\\\fh\\\\ubukaz-portrait\",Frame=M..\"dungeons\\\\fh\\\\ubukaz-frame\",MapCoordinateX=52.4,MapCoordinateY=39.4,Abilities={{Effect=\"At 20% remaining health, Ubukaz becomes enraged, increasing the damage he deals to his enemies significantly.\",Flags={F.Enrage},Icon=\"spell_shadow_unholyfrenzy\",Id=\"enrage\",Name=\"Enrage\"}},L=\"150:33,134:33,157:33\"},\n{Id=\"kanza\",Name=\"Kan'za the Seer\",Story=\"Those who have entered Frostmane Hollow and lived to speak of Kan'za the Seer are, if they exist at all, silent on the matter.\",Portrait=M..\"dungeons\\\\fh\\\\kanza-portrait\",Frame=M..\"dungeons\\\\fh\\\\kanza-frame\",MapCoordinateX=32.4,MapCoordinateY=45.8,Abilities={{Effect=\"Kan'za starts the fight with two Frostmane Snowcaller that will assist him.\\\n\\\nThese adds should be prioritized by the damage dealers over the boss\",Flags={F.DPS},Icon=\"inv_misc_head_troll_01\",Id=\"kanzaadds\",Name=\"Kan'za's Adds\",SubAbilities={{Effect=\"The Frostmane Snowcaller casts a frostbolt at his target, dealing frost damage and slowing them.\",Flags={F.Interruptible},Icon=\"spell_frost_frostbolt02\",Id=\"kanzaaddsfrostbolt\",Name=\"Frostbolt\"}}},{Effect=\"Kan'za casts a chilling blizzard, dealing frost damage in an area of effect.\",Flags={F.Interruptible},Icon=\"spell_frost_icestorm\",Id=\"kanzablizzard\",Name=\"Blizzard\"},{Effect=\"Kan'za casts a frostbolt at his target, dealing frost damage and slowing them.\",Flags={F.Interruptible},Icon=\"spell_frost_frostbolt02\",Id=\"kanzafrostbolt\",Name=\"Frostbolt\"}},L=\"205:33,241:33,213:33\"},\n{Id=\"hailar\",Name=\"Hailar the Frigid\",Story=\"The frozen depths of Frostmane Hollow have claimed many lives; whether any of them ever learned who Hailar the Frigid truly was remains unknown.\",Portrait=M..\"dungeons\\\\fh\\\\hailar-portrait\",Frame=M..\"dungeons\\\\fh\\\\hailar-frame\",MapCoordinateX=30.5,MapCoordinateY=86.1,Abilities={{Effect=\"Hailar starts the fight with five Frostmane Ritualists that will keep on healing him as long as they are alive.\\\n\\\nThe group needs to kill these adds before being able to kill Hailar.\",Flags={F.DPS,F.Important},Icon=\"inv_misc_head_troll_01\",Id=\"hailaradds\",Name=\"Frostmane Ritualists\"},{Effect=\"Hailar casts a flash freeze, blasting all enemies within 10 yards for 56 frost damage and freezing them in place for up to 5 seconds.\",Flags={F.Deadly},Icon=\"spell_frost_frostnova\",Id=\"16803\",Name=\"Flash Freeze\"},{Effect=\"Hailar casts a frostbolt at his target, dealing frost damage and slowing them.\",Flags={F.Interruptible},Icon=\"spell_frost_frostbolt02\",Id=\"hailarfrostbolt\",Name=\"Frostbolt\"}},L=\"110:33,126:33,116:33\"},\n}}\nZLDB.DG[\"GC\"]={\nName=\"Gilneas City\",\nStory=\"Once the proud jewel of the peninsula, Gilneas City has become a fractured battlefield of civil war, draconic shadow, and feral madness. While the Greymane Wall has fallen, the city remains an impenetrable fortress held by royalist forces and their mysterious benefactors. Beneath the surface of the rebellion led by Lord Darius Ravenwood, a darker rot persists-the Harlow family, secret agents of the Black Dragonflight, have manipulated the kingdom's pride to fuel years of decay. Adventurers must navigate the blood-stained streets to recover lost family deeds, stolen masterpieces, and ancient manuscripts of hydromancy, all while deciding the ultimate fate of King Genn Greymane himself.\",\nBackground=M..\"dungeons\\\\gc\\\\background\",\nGridBackground=M..\"dungeons\\\\gc\\\\grid-background\",\nMapId=32,\nIconScale=0.9,\nMinLevel=43,\nMaxLevel=52,\nEntrances={{MapContinentId=2,MapCoordinateX=27.4,MapCoordinateY=30.1,MapZoneId=15}},\nType=T.Dungeon,\nKey=\"GC\",\nBosses={\n{Id=\"61419\",Name=\"Matthias Holtz\",Story=\"WhiIn the wake of the worgen outbreak, Holtz and his detachment enforced a strict lockdown over the city’s entrance district after it was overrun, sealing it off in a desperate attempt to contain the chaos. Though little is known of the man himself, his role in those frantic hours endures as a testament to the grim measures taken to preserve what remained of Gilneas.\",Portrait=M..\"dungeons\\\\gc\\\\holtz-portrait\",Frame=M..\"dungeons\\\\gc\\\\holtz-frame\",MapCoordinateX=75.8,MapCoordinateY=40.5,L=\"61305:33,61304:33,61306:33,61307:2\"},\n{Id=\"61420\",Name=\"Packmaster Ragetooth\",Story=\"As leader of the Darkpelt pack, he spearheaded the worgen assault that overran the city’s entrance, turning once-guarded streets into hunting grounds. His ferocity forced the crown’s soldiers to seal the district under strict lockdown, dispatching royalist detachments to contain the spread and cull the beasts within.\",Portrait=M..\"dungeons\\\\gc\\\\ragetooth-portrait\",Frame=M..\"dungeons\\\\gc\\\\ragetooth-frame\",MapCoordinateX=84.6,MapCoordinateY=63.5,L=\"61300:33,61301:33,61302:33,61303:2\"},\n{Id=\"61421\",Name=\"Judge Sutherland\",Story=\"A man of immense cruelty, Judge Sutherland presided over the meritless conspiracy trials that saw the prominent Glaymore family butchered one by one. He continues to pass his brutal judgments with each swing of his gavel, acting as a cold reminder of the corruption that turned the kingdom's justice into a weapon of fear.\",Portrait=M..\"dungeons\\\\gc\\\\sutherland-portrait\",Frame=M..\"dungeons\\\\gc\\\\sutherland-frame\",MapCoordinateX=77.2,MapCoordinateY=84.1,L=\"61308:25,61309:25,61310:25,61311:25,61312:2\"},\n{Id=\"61422\",Name=\"Dustivan Blackcowl\",Story=\"A swindling rogue and a self-serving lackey, Dustivan Blackcowl serves King Greymane like an obedient dog. He was recently employed to steal the deed of Ebonmere Farm, hiding deep within the bowels of the city to protect his ill-gotten gains from those seeking to reclaim their family birthright.\",Portrait=M..\"dungeons\\\\gc\\\\dustivan-portrait\",Frame=M..\"dungeons\\\\gc\\\\dustivan-frame\",MapCoordinateX=57.6,MapCoordinateY=83.2,L=\"61330:25,61331:25,61332:25,61333:25,61334:5\"},\n{Id=\"61423\",Name=\"Marshal Magnus Greystone\",Story=\"The history of Marshal Magnus Greystone remains largely unwritten, yet what little is known speaks of a life spent in constant war. A veteran of the Second War, he served as Marshal throughout the orcish incursions, standing as a steadfast defender of Gilneas in its darkest hours. Years later, as civil war consumed the kingdom, Greystone commanded the defenses of Gilneas City, holding the line not only against invaders, but against the very people he once fought to protect. Even so, his deeds were never fully recorded, leaving behind only the memory of a soldier who never abandoned his post.\",Portrait=M..\"dungeons\\\\gc\\\\magnus-portrait\",Frame=M..\"dungeons\\\\gc\\\\magnus-frame\",MapCoordinateX=46.3,MapCoordinateY=44.7,L=\"61313:24,61314:24,61315:24,61316:24,61368:5,61317:5,113:5\"},\n{Id=\"61605\",Name=\"Horsemaster Levvin\",Story=\"Information on Horsemaster Levvin is currently limited, though he is recognized as a confirmed dweller of the heavily fortified Gilneas City.\",Portrait=M..\"dungeons\\\\gc\\\\levvin-portrait\",Frame=M..\"dungeons\\\\gc\\\\levvin-frame\",MapCoordinateX=29,MapCoordinateY=19.2,L=\"83157:1,61737:25,61736:25,61735:25,61734:25\"},\n{Id=\"61263\",Name=\"Harlow Family\",Story=\"Regent-Lady Celia and Regent-Lord Mortimer Harlow are the secret architects of the kingdom's decay. In truth, they are Dragonkin of the Black Dragonflight who have long manipulated the pride of Gilneas to stoke civil war and conflict. Their evil machinations are the root of the draconic influence that must be undone to save the land.\",Portrait=M..\"dungeons\\\\gc\\\\family-portrait\",Frame=M..\"dungeons\\\\gc\\\\family-frame\",MapCoordinateX=28.1,MapCoordinateY=23.8,L=\"61318:24,61319:24,61320:24,61321:24,61322:5\"},\n{Id=\"61418\",Name=\"Genn Greymane\",Story=\"The stubborn and proud King of Gilneas was once a legendary force within the Alliance, but he now presides over a crumbling kingdom. Within the Greymane Tower, he guards the Shard of Midnight-a corrupting artifact bestowed upon him by Lord Prestor. Though his grip on the nation has slipped, his power and pride make him a dangerous quarry for any who seek to end his reign.\",Portrait=M..\"dungeons\\\\gc\\\\genn-portrait\",Frame=M..\"dungeons\\\\gc\\\\genn-frame\",MapCoordinateX=26.1,MapCoordinateY=20.9,L=\"61323:14,61324:14,61325:14,61326:14,61327:14,61328:14,61329:14,69000:2,61406:1,61738:6\"},\n}}\nZLDB.DG[\"GNOMEREGAN\"]={\nName=\"Gnomeregan\",\nStory=\"Located in Dun Morogh, the technological wonder known as Gnomeregan has been the gnomes' capital city for generations. Recently, a hostile race of mutant troggs infested several regions of Dun Morogh - including the great gnome city. In a desperate attempt to destroy the invading troggs, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Several gnomes sought shelter from the airborne pollutants as they waited for the troggs to die or flee. Unfortunately, though the troggs became irradiated from the toxic assault - their siege continued, unabated. Those gnomes who were not killed by noxious seepage were forced to flee, seeking refuge in the nearby dwarven city of Ironforge. There, High Tinker Mekkatorque set out to enlist brave souls to help his people reclaim their beloved city. It is rumored that Mekkatorque's once-trusted advisor, Mekgineer Thermaplugg, betrayed his people by allowing the invasion to happen. Now, his sanity shattered, Thermaplugg remains in Gnomeregan - furthering his dark schemes and acting as the city's new techno-overlord.\",\nBackground=M..\"dungeons\\\\gnomeregan\\\\background\",\nGridBackground=M..\"dungeons\\\\gnomeregan\\\\grid-background\",\nMapId=9,\nIconScale=0.9,\nMinLevel=28,\nMaxLevel=37,\nEntrances={{MapContinentId=2,MapCoordinateX=29.5,MapCoordinateY=74.8,MapZoneId=16},{MapContinentId=2,MapCoordinateX=42.5,MapCoordinateY=12.7,MapZoneId=16}},\nType=T.Dungeon,\nKey=\"GNOMEREGAN\",\nBosses={\n{Id=\"7361\",Name=\"Grubbis\",Story=\"The radioactive gas that flooded the city was meant to anger the troggs and kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, however, reacted oddly to the substance: Grubbis grew. And grew. It was a side effect that Sicco had not anticipated, but he's never been one to waste valuable (and dangerous) resources. This giant trogg now patrols the tunnels of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas leaks, tasty fungi, and even tastier intruders.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\grubbis-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\grubbis-frame\",MapCoordinateX=87,MapCoordinateY=38.2,L=\"9445:25,80737:25,80738:25,80739:25\"},\n{Id=\"7079\",Name=\"Viscous Fallout\",Story=\"The formerly robust and elegantly complex waterways of Gnomeregan are now an irradiated mess filled with toxic slime. A lone water elemental who had dwelt in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form. It currently wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\fallout-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\fallout-frame\",MapCoordinateX=65.6,MapCoordinateY=29.9,L=\"9452:33,9453:33,9454:33\"},\n{Id=\"6235\",Name=\"Electrocutioner 6000\",Story=\"Mekgineer Thermaplugg is not a patient gnome. Rather than putting his inventions through a battery of tests to determine their safety and effectiveness, he rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt at harnessing electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom \\\"Sizzlepants\\\" Crankle, the only soldier to survive piloting the Electrocutioner, is now something of a hero among the leper gnomes.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\electrocutioner-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\electrocutioner-frame\",MapCoordinateX=32.6,MapCoordinateY=41.4,L=\"9446:33,9447:33,9448:33\"},\n{Id=\"6229\",Name=\"Crowd Pummeler 9-60\",Story=\"In Gnomeregan's heyday, inventors would compete for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot, and this earned his respect in the high tinker's court. Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version of the machine. He set his forgery loose, and the horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite (stolen) inventions.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\pummeler-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\pummeler-frame\",MapCoordinateX=44.7,MapCoordinateY=88.5,L=\"9449:33,9450:33,80740:33\"},\n{Id=\"6228\",Name=\"Dark Iron Ambassador\",Story=\"Nobody knows why an ambassador of the Dark Iron dwarves was sent to the fallen capital city of Gnomeregan. Some rumors spread that the Dark Irons had a deal with Thermaplugg to direct the troggs to Gnomeregan from their operations in Uldaman where the troggs originated.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\ambassador-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\ambassador-frame\",MapCoordinateX=19.5,MapCoordinateY=67.3,IsRare=true,L=\"9455:33,9456:33,9457:33\"},\n{Id=\"7800\",Name=\"Mekgineer Thermaplugg\",Story=\"Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a malfunctioning iron fist. His subjects are numerous, vicious, and insane enough to defend their crazed king against any intrusion from the upper world. It is Thermaplugg's madness that makes him so dangerous; he possesses the cunning to destroy everything around him, with no thought for his own life. There is a reason that even the monsters of Gnomeregan fear him.\",Portrait=M..\"dungeons\\\\gnomeregan\\\\thermaplugg-portrait\",Frame=M..\"dungeons\\\\gnomeregan\\\\thermaplugg-frame\",MapCoordinateX=17.3,MapCoordinateY=38.5,L=\"9458:25,9459:25,9461:25,9492:25,40084:4,4411:2,4413:2,4415:2,7742:2,51217:1\"},\n}}\nZLDB.DG[\"HQ\"]={\nName=\"Hateforge Quarry\",\nStory=\"Excavated deep within the Burning Steppes, the Hateforge Quarry was originally the brainchild of Orvak Sternrock, designed to expand the reach of the Dark Iron Miners Union. However, underhanded deceit led to Orvak's removal as High Foreman, replaced by the fraudulent Bargul Blackhammer. Since then, the quarry has become a hive of illicit activity; rumors swirl of a volatile 'Hateforge Brew' being concocted in secret, while acid-born elementals manifest in the potent runoff pools. Most concerning to King Magni Bronzebeard and the Horde alike is the arrival of the Twilight's Hammer, who have moved into the depths to exploit the Dark Iron's labor for their own apocalyptic ends.\",\nBackground=M..\"dungeons\\\\hq\\\\background\",\nGridBackground=M..\"dungeons\\\\hq\\\\grid-background\",\nMapId=35,\nIconScale=0.9,\nMinLevel=51,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=97.5,MapCoordinateY=59.1,MapZoneId=8}},\nType=T.Dungeon,\nKey=\"HQ\",\nBosses={\n{Id=\"60735\",Name=\"High Foreman Bargul Blackhammer\",Story=\"Bargul Blackhammer spent years utilizing violence and underhanded tactics to usurp the position of High Foreman. After convincing the Senate to back his vision for the Hateforge Quarry, he successfully ousted his predecessor through fraud. Now ensconced in his stolen office, he holds the Senate's Orders tight, ruling the Miners Union with an iron fist and ensuring that the quarry's true, dark purpose remains shielded from those he betrayed.\",Portrait=M..\"dungeons\\\\hq\\\\bargul-portrait\",Frame=M..\"dungeons\\\\hq\\\\bargul-frame\",MapCoordinateX=56.5,MapCoordinateY=82.8,L=\"60565:20,60566:20,60567:20,60568:20,60569:20,60570:15,51217:5,70226:2\"},\n{Id=\"60736\",Name=\"Engineer Figgles\",Story=\"With an ego that rivals the masters of Blackrock Spire, Engineer Figgles is an arrogant mastermind who insists on branding every mechanical creation with his own name. He oversees the quarry's complex machinery and the mysterious plans involving dragon whelpings. His technical genius is matched only by his narcissism, making him a primary target for the Blackrock Clan who seek to halt the Dark Iron's technological expansion.\",Portrait=M..\"dungeons\\\\hq\\\\figgles-portrait\",Frame=M..\"dungeons\\\\hq\\\\figgles-frame\",MapCoordinateX=57.7,MapCoordinateY=44.6,L=\"60540:20,60541:20,60542:20,60543:20,60545:20,60539:15,51217:5,70226:2,13325:1\"},\n{Id=\"60829\",Name=\"Corrosis\",Story=\"The acid pools within the Hateforge Quarry are so incredibly potent that they eventually gave birth to a malevolent entity of pure dissolution. Manifested from the chemical runoff of the Dark Iron's secret brewing process, Corrosis is a being of shifting, corrosive liquid. Its very essence is sought by master smiths like Frig Thunderforge, who believe the elemental's core holds the key to tempering weapons of unimaginable power.\",Portrait=M..\"dungeons\\\\hq\\\\corrosis-portrait\",Frame=M..\"dungeons\\\\hq\\\\corrosis-frame\",MapCoordinateX=72.7,MapCoordinateY=73.3,L=\"80670:20,80671:20,80674:20,80673:20,80672:20\"},\n{Id=\"60734\",Name=\"Hatereaver Annihilator\",Story=\"While confirmed to be a resident of the Hateforge Quarry, little else is known about the Hatereaver Annihilator or the role it plays within the excavation.\",Portrait=M..\"dungeons\\\\hq\\\\hatereaver-portrait\",Frame=M..\"dungeons\\\\hq\\\\hatereaver-frame\",MapCoordinateX=75.1,MapCoordinateY=18.4,L=\"60559:20,60561:20,60562:20,60563:20,60564:20,60560:15,51217:5,70226:2\"},\n{Id=\"60737\",Name=\"Har'gesh Doomcaller\",Story=\"Har'gesh Doomcaller is the shadow behind the Dark Iron's toil, overseeing the Twilight's Hammer's operations from the deepest reaches of the quarry. His presence is a direct threat to the safety of the kingdom, prompting both the Alliance and the Horde to demand his removal to prevent the cult's influence from spreading further.\",Portrait=M..\"dungeons\\\\hq\\\\hargesh-portrait\",Frame=M..\"dungeons\\\\hq\\\\hargesh-frame\",MapCoordinateX=94.6,MapCoordinateY=79,L=\"51217:100,51045:25,51046:25,60551:2,70226:3,60550:20,60549:20,60548:20,60547:20,60546:20,51048:25,51047:25\"},\n}}\nZLDB.DG[\"KC\"]={\nName=\"Karazhan Crypts\",\nStory=\"Beneath the shadow of Karazhan lies a subterranean ossuary that the Kirin Tor has long kept sealed. It is a place where time has stagnated, housing a 'great evil' that both the Alliance and Horde now race to extinguish. From the missing pages of goblin recipe books to the 'foul blackness' of its deepest reaches, the crypts serve as a grim reminder of the tower's corruptive influence on the very earth it stands upon.\",\nBackground=M..\"dungeons\\\\kc\\\\background\",\nGridBackground=M..\"dungeons\\\\kc\\\\grid-background\",\nMapId=36,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=39.6,MapCoordinateY=73.1,MapZoneId=9}},\nType=T.Dungeon,\nKey=\"KC\",\nBosses={\n{Id=\"91920\",Name=\"Marrowspike\",Story=\"Not much has been chronicled regarding Marrowspike, leaving the creature as a mystery to those exploring the Karazhan Crypts.\",Portrait=M..\"dungeons\\\\kc\\\\marrowspike-portrait\",Frame=M..\"dungeons\\\\kc\\\\marrowspike-frame\",MapCoordinateX=89.2,MapCoordinateY=77.8,MapIsBelow=true,L=\"83441:18,83442:18,83443:18,83444:18,83445:18,83440:10,51217:5,70226:2\"},\n{Id=\"91929\",Name=\"Hivaxxis\",Story=\"Beyond its reputation as a lethal dweller of the lightless ossuary, Hivaxxis remains an enigma within the Karazhan Crypts.\",Portrait=M..\"dungeons\\\\kc\\\\hivaxxis-portrait\",Frame=M..\"dungeons\\\\kc\\\\hivaxxis-frame\",MapCoordinateX=81.8,MapCoordinateY=86.8,L=\"83447:18,83448:18,83449:18,83450:18,83451:18,83446:10,51217:5,70226:2\"},\n{Id=\"91917\",Name=\"Corpsemuncher\",Story=\"Documentation on the scavenger known as Corpsemuncher is non-existent, marking it only as a verified resident of the Karazhan Crypts.\",Portrait=M..\"dungeons\\\\kc\\\\corpsemuncher-portrait\",Frame=M..\"dungeons\\\\kc\\\\corpsemuncher-frame\",MapCoordinateX=21,MapCoordinateY=78.1,L=\"70057:15,83459:15,83460:15,83461:15,83462:15,83463:15,83458:10,51217:5,70226:2\"},\n{Id=\"92935\",Name=\"Guard Captain Gort\",Story=\"Historical texts provide no details on the life or death of Guard Captain Gort, confirming only his station inside the Karazhan Crypts.\",Portrait=M..\"dungeons\\\\kc\\\\gort-portrait\",Frame=M..\"dungeons\\\\kc\\\\gort-frame\",MapCoordinateX=55.6,MapCoordinateY=78.4,L=\"60792:17,60793:17,60794:17,60795:17,60790:17,60791:17,51217:5,70226:2\"},\n{Id=\"91916\",Name=\"Archlich Enkhraz\",Story=\"The legacy of Archlich Enkhraz is entirely unknown, establishing him merely as a powerful undead force occupying the Karazhan Crypts.\",Portrait=M..\"dungeons\\\\kc\\\\enkhraz-portrait\",Frame=M..\"dungeons\\\\kc\\\\enkhraz-frame\",MapCoordinateX=90,MapCoordinateY=72.1,L=\"83453:18,83454:18,83455:18,83456:18,83457:18,83452:10,51217:5,80010:5,70226:2\"},\n{Id=\"91919\",Name=\"Commander Andreon\",Story=\"Commander Andreon once counted among the tower’s guard alongside his twin brother, Captain Rothynn, he was entrusted with a Mark of Karazhan, a symbol of his station and duty. While Rothynn’s fate is known, his spirit bound to the cellars below, Andreon’s disappearance was never explained. Now he lingers within the crypts as a restless presence, a fallen guardian whose purpose endures even in death.\",Portrait=M..\"dungeons\\\\kc\\\\andreon-portrait\",Frame=M..\"dungeons\\\\kc\\\\andreon-frame\",MapCoordinateX=46.5,MapCoordinateY=36.1,L=\"50188:17,50189:17,50190:17,50191:17,50192:17,50193:17,51217:5,70226:2\"},\n{Id=\"91928\",Name=\"Alarus\",Story=\"Known as the Watcher of the Crypts, Alarus is the primary sentinel of the foul magic festering beneath the tower. The Kirin Tor views his destruction as vital to the safety of Azeroth, while the Horde seeks to strike him down as an act of glory, knowing that only by vanquishing this 'great evil' can the suffocating fog and madness of the depths be lifted.\",Portrait=M..\"dungeons\\\\kc\\\\alarus-portrait\",Frame=M..\"dungeons\\\\kc\\\\alarus-frame\",MapCoordinateX=85.4,MapCoordinateY=43.9,L=\"51217:100,83465:25,83466:25,83467:25,83468:25,83469:21,83470:21,83471:21,83472:21,83571:15,70226:3,83464:1\"},\n}}\nZLDB.DG[\"LBRS\"]={\nName=\"Lower Blackrock Spire\",\nStory=\"This imposing fortress, carved into the fiery core of Blackrock Mountain, represented the might of the Dark Iron clan for centuries. More recently, the black dragon Nefarian and his spawn seized the keep's upper spire and ignited a brutal war against the dwarves. The draconic armies have since allied with Warchief Rend Blackhand and his false Horde. This combined force lords over the spire, conducting horrific experiments to bolster its ranks while plotting the meddlesome Dark Irons' downfall.\",\nBackground=M..\"dungeons\\\\lbrs\\\\background\",\nGridBackground=M..\"dungeons\\\\lbrs\\\\grid-background\",\nMapId=17,\nIconScale=0.9,\nMinLevel=55,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=81.7,MapCoordinateY=43.4,MapZoneId=6}},\nType=T.Dungeon,\nKey=\"LBRS\",\nBosses={\n{Id=\"9219\",Name=\"Spirestone Butcher\",Story=\"An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\butcher-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\butcher-frame\",IsRare=true,L=\"12608:50,13286:50\"},\n{Id=\"9196\",Name=\"Highlord Omokk\",Story=\"Omokk rules over the spire's ogres with an iron fist. Many underlings have challenged him to single combat in the hopes of seizing the highlord's title, but all have fallen without landing a solitary blow. This mysterious phenomenon has led to rumors that dark magic is protecting Omokk.\",Portrait=M..\"dungeons\\\\lbrs\\\\omokk-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\omokk-frame\",L=\"13166:17,13167:17,13168:17,13169:17,13170:17,16670:17,12336:25,51217:5,70226:2\"},\n{Id=\"9218\",Name=\"Spirestone Battle Lord\",Story=\"An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\battlelord-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\battlelord-frame\",IsRare=true,L=\"13285:60,13284:40\"},\n{Id=\"9217\",Name=\"Spirestone Lord Magus\",Story=\"An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\magus-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\magus-frame\",IsRare=true,L=\"13261:33,13282:33,13283:33\"},\n{Id=\"9236\",Name=\"Shadow Hunter Vosh'gajin\",Story=\"Vosh'gajin is renowned for her beauty--and psychotic tendencies--among the trolls. A master of the shadow hunter arts, she wields formidable hexes, curses, and healing magics.\",Portrait=M..\"dungeons\\\\lbrs\\\\voshgajin-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\voshgajin-frame\",L=\"12626:17,12651:17,12653:17,13255:17,13257:17,16712:17,51217:5,70226:2\"},\n{Id=\"9237\",Name=\"War Master Voone\",Story=\"During the Second War, Voone led small strike teams on daring missions into the heart of high elven territory. The cunning troll joined the false Horde because he wanted to be its chief strategist, not because he believed in Blackhand's ideology. Voone sees the splinter faction as an underdog, and he enjoys the satisfaction of overcoming insurmountable odds.\",Portrait=M..\"dungeons\\\\lbrs\\\\voone-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\voone-frame\",MapCoordinateX=52.4,MapCoordinateY=54.8,L=\"13173:100,12335:20,12582:20,13177:20,13179:20,16676:20,22231:20,51217:5,70226:2,13175:1\"},\n{Id=\"9596\",Name=\"Bannok Grimaxe\",Story=\"An elusive orc, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\bannok-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\bannok-frame\",MapCoordinateX=47.9,MapCoordinateY=60,IsRare=true,L=\"12621:33,12634:33,12637:33,12838:7\"},\n{Id=\"10596\",Name=\"Mother Smolderweb\",Story=\"Centuries ago, the Dark Iron dwarves dug into the lair of Mother Smolderweb, releasing the massive arachnid into the spire's halls. Her brood has continued to swell in number since that time, so much so that even Blackhand's forces fear traveling through Smolderweb's domain.\",Portrait=M..\"dungeons\\\\lbrs\\\\mother-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\mother-frame\",L=\"13183:20,70226:2,13244:20,16715:20,51217:5,13213:20,80758:20\"},\n{Id=\"10376\",Name=\"Crystal Fang\",Story=\"An elusive spider, rarely seen among the general population of Lower Blackrock Spire. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\fang-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\fang-frame\",IsRare=true,L=\"13184:33,13185:33,13218:33\"},\n{Id=\"10584\",Name=\"Urok Doomhowl\",Story=\"Doomhowl is the true leader of the spire's ogres. This sinister figure has charmed his trusted aid, Highlord Omokk, with insidious magic to control Doomhowl's minions in his stead. He has gone to great lengths to keep up this charade, ruthlessly killing any ogres who challenge the highlord's rule.\",Portrait=M..\"dungeons\\\\lbrs\\\\urok-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\urok-frame\",L=\"13178:25,13258:25,13259:25,22232:25,18784:16,51217:5,70226:2\"},\n{Id=\"9736\",Name=\"Quartermaster Zigris\",Story=\"After the First War, the orc hunter Zigris became infamous for tracking down Stormwind refugees and slaughtering them like game. He loathes Blackrock Spire's claustrophobic halls, but he is certain a day will come when he'll hunt in the open air again.\",Portrait=M..\"dungeons\\\\lbrs\\\\zigris-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\zigris-frame\",L=\"56101:30,12835:10,13252:10,13253:10,80759:10,51217:5,16673:2,16703:2,16713:2,16716:2,16735:2,70221:2,70226:2\"},\n{Id=\"10220\",Name=\"Halycon\",Story=\"Halycon comes from a long line of great worgs bred for their ferocity and loyalty. Over the years, the den mother has produced an astonishing number of savage offspring. Rumors have spread that she is a demonic hound gifted to Rend Blackhand by a pit lord of the Burning Legion.\",Portrait=M..\"dungeons\\\\lbrs\\\\halycon-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\halycon-frame\",L=\"13210:25,13211:25,13212:25,22313:25,51217:5,70226:2\"},\n{Id=\"10268\",Name=\"Gizrul the Slavener\",Story=\"Very few of the Dark Horde have seen the reclusive and unpredictable Gizrul. The beast emerges from his shadowy den only when his mate, Halycon, calls to him. The two monstrous creatures have produced some of the largest--and most ferocious--worgs ever bred in orcish history.\",Portrait=M..\"dungeons\\\\lbrs\\\\gizrul-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\gizrul-frame\",L=\"13205:25,13206:25,13208:25,16718:25,83573:15,51217:5,70226:2\"},\n{Id=\"9718\",Name=\"Ghok Bashguud\",Story=\"An elusive orc, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\lbrs\\\\ghok-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\ghok-frame\",IsRare=true,L=\"13198:33,13203:33,13204:33\"},\n{Id=\"9568\",Name=\"Overlord Wyrmthalak\",Story=\"The black dragonspawn Wyrmthalak oversees the lower spire's forces as they prepare for their assault against the dwarves. He has no love for the false Horde or its brutish members, and he will sacrifice any number of Blackhand's minions to protect his master, Nefarian.\",Portrait=M..\"dungeons\\\\lbrs\\\\wyrmthalak-portrait\",Frame=M..\"dungeons\\\\lbrs\\\\wyrmthalak-frame\",L=\"51217:100,12337:30,13148:13,13161:13,13162:13,13163:13,13164:13,16679:13,22321:13,80760:13,47413:10,47415:10,56097:6,70226:3,13143:2\"},\n}}\nZLDB.DG[\"MARA\"]={\nName=\"Maraudon\",\nStory=\"According to legend, Zaetar, son of Cenarius, and the earth elemental princess Theradras begot the barbaric centaur race. Shortly after the centaur's creation, the ruthless creatures murdered their father. The grief-stricken Theradras is said to have trapped her lover's spirit within Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted elemental minions roam every corner of the sprawling caves.\",\nBackground=M..\"dungeons\\\\mara\\\\background\",\nGridBackground=M..\"dungeons\\\\mara\\\\grid-background\",\nMapId=19,\nIconScale=0.6,\nMinLevel=43,\nMaxLevel=54,\nEntrances={{MapContinentId=1,MapCoordinateX=72,MapCoordinateY=73.6,MapZoneId=17},{MapContinentId=1,MapCoordinateX=45.3,MapCoordinateY=20.8,MapZoneId=17}},\nType=T.Dungeon,\nKey=\"MARA\",\nBosses={\n{Id=\"13282\",Name=\"Noxxion\",Story=\"Noxxion is a living embodiment of corruption. Theradras ordered her ally Lord Vyletongue to create this putrid elemental to be a powerful servant and a loyal pet to ease the princess's loneliness. Noxxion spreads its toxic essence into areas of Maraudon that have not yet withered under Theradras's malign influence.\",Portrait=M..\"dungeons\\\\mara\\\\noxxion-portrait\",Frame=M..\"dungeons\\\\mara\\\\noxxion-frame\",MapCoordinateX=32.3,MapCoordinateY=4.7,L=\"17746:33,17745:33,17744:33\"},\n{Id=\"12258\",Name=\"Razorlash\",Story=\"Razorlash was made to accompany Noxxion through Maraudon. In time, this new creation became one of the princess's most cherished servants. Razorlash constantly wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.\",Portrait=M..\"dungeons\\\\mara\\\\razorlash-portrait\",Frame=M..\"dungeons\\\\mara\\\\razorlash-frame\",MapCoordinateX=23.1,MapCoordinateY=15.5,L=\"17748:25,17749:25,51802:8,17751:25,17750:25,60780:3\"},\n{Id=\"12237\",Name=\"Meshlok the Harvester\",Story=\"An elusive bog beast, rarely seen among the denizens of Maraudon. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\mara\\\\meshlok-portrait\",Frame=M..\"dungeons\\\\mara\\\\meshlok-frame\",MapCoordinateX=26.2,MapCoordinateY=30.6,IsRare=true,L=\"60780:10,17767:33,17742:33,17741:33\"},\n{Id=\"12236\",Name=\"Lord Vyletongue\",Story=\"The satyr lord Vyletongue journeyed into Maraudon's depths after hearing of its corruption. Theradras was wary of the conniving demon at first, but Vyletongue proved his worth by creating an array of wretched minions, such as Noxxion and Razorlash, for the princess.\",Portrait=M..\"dungeons\\\\mara\\\\vyletongue-portrait\",Frame=M..\"dungeons\\\\mara\\\\vyletongue-frame\",MapCoordinateX=33,MapCoordinateY=32.8,L=\"17752:33,17754:33,17755:33,51217:1\"},\n{Id=\"12225\",Name=\"Celebras the Cursed\",Story=\"Upon learning of his uncle's tragic fate, the noble Celebras swore to free Zaetar's spirit. Yet the keeper of the grove was not prepared for the horrors that awaited him in Maraudon's shadowy corridors. The dark energies permeating the area quickly overcame Celebras, filling his heart with uncontrollable rage.\",Portrait=M..\"dungeons\\\\mara\\\\celebras-portrait\",Frame=M..\"dungeons\\\\mara\\\\celebras-frame\",MapCoordinateX=19.1,MapCoordinateY=32.9,L=\"17738:33,17739:33,17740:33,60780:3,51217:1\"},\n{Id=\"13601\",Name=\"Tinkerer Gizlock\",Story=\"Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. Their plan went horribly wrong when satyrs slaughtered everyone in the party save for Gizlock. The goblin, trapped within the caves and driven to the brink of madness, sees himself as the subterranean region's new ruler.\",Portrait=M..\"dungeons\\\\mara\\\\gizlock-portrait\",Frame=M..\"dungeons\\\\mara\\\\gizlock-frame\",MapCoordinateX=37.7,MapCoordinateY=75.1,L=\"17717:33,17718:33,17719:33,40083:8,51809:8\"},\n{Id=\"12203\",Name=\"Landslide\",Story=\"For years, the ancient mountain giant known as Landslide cultivated brilliant crystal gardens in Maraudon, but Theradras enthralled the behemoth when she took up residence there. This once-stoic giant now lives only to serve his tyrannical new master.\",Portrait=M..\"dungeons\\\\mara\\\\landslide-portrait\",Frame=M..\"dungeons\\\\mara\\\\landslide-frame\",MapCoordinateX=32.2,MapCoordinateY=60.3,L=\"17734:25,17736:25,17737:25,17943:25\"},\n{Id=\"13596\",Name=\"Rotgrip\",Story=\"Rumor has it that Rotgrip has dwelled in Maraudon's subterranean waters for millennia. The famed dwarven hunter Hemet Nesingwary once proclaimed that the beast could not be found, and a number of amateur trackers accepted the challenge of seeking out the legendary creature. None of them ever returned.\",Portrait=M..\"dungeons\\\\mara\\\\rotgrip-portrait\",Frame=M..\"dungeons\\\\mara\\\\rotgrip-frame\",MapCoordinateX=32.1,MapCoordinateY=86.1,L=\"17728:33,17730:33,17732:33\"},\n{Id=\"12201\",Name=\"Princess Theradras\",Story=\"The earth elemental Theradras, Therazane the Stonemother's sole daughter, resides in Maraudon's inner sanctum. Influenced by the Old Gods, the princess transformed her home into a den of corruption and suffering. Some believe that her foul powers are tied to the spirit of her dead lover, Zaetar. If so, liberating the fallen keeper of the grove might be the only hope of cleansing Maraudon.\",Portrait=M..\"dungeons\\\\mara\\\\princess-portrait\",Frame=M..\"dungeons\\\\mara\\\\princess-frame\",MapCoordinateX=20.2,MapCoordinateY=83.1,L=\"17707:14,17710:14,17711:14,17713:14,17714:14,17715:14,17766:14,17780:1,51217:5\"},\n}}\nZLDB.DG[\"RFC\"]={\nName=\"Ragefire Chasm\",\nStory=\"Ragefire Chasm consists of a network of volcanic caverns that lie below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief, Thrall, is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council. Either way, the dark powers emanating from Ragefire Chasm could undo all that the orcs have fought to attain.\",\nBackground=M..\"dungeons\\\\rfc\\\\background\",\nGridBackground=M..\"dungeons\\\\rfc\\\\grid-background\",\nMapId=4,\nIconScale=0.8,\nMinLevel=13,\nMaxLevel=19,\nEntrances={{MapContinentId=1,MapCoordinateX=53,MapCoordinateY=48.6,MapZoneId=21}},\nType=T.Dungeon,\nKey=\"RFC\",\nBosses={\n{Id=\"11517\",Name=\"Oggleflint\",Story=\"Oggleflint and the other troggs retreated to the upper levels of Ragefire Chasm once the Searing Blade cultists moved in.\",Portrait=M..\"dungeons\\\\rfc\\\\oggleflint-portrait\",Frame=M..\"dungeons\\\\rfc\\\\oggleflint-frame\",MapCoordinateX=56.3,MapCoordinateY=38.1,Abilities={{Effect=\"Oggleflint cleaves all enemies in front of him.\",Icon=\"Ability_Warrior_Cleave\",Id=\"845\",Name=\"Cleave\"}},L=\"80700:35,80701:35,80702:30,17041:30\"},\n{Id=\"11520\",Name=\"Taragaman the Hungerer\",Story=\"Thought to be the leader of the Searing Blade, Taragaman can be found hiding in the fiery depths of Ragefire Chasm and using his demonic influence to corrupt the citizens of Orgrimmar.\",Portrait=M..\"dungeons\\\\rfc\\\\taragaman-portrait\",Frame=M..\"dungeons\\\\rfc\\\\taragaman-frame\",MapCoordinateX=40.9,MapCoordinateY=57.9,Abilities={{Effect=\"Taragaman the Hungerer inflicts fire damage to nearby enemies.\",Icon=\"Spell_Fire_SealOfFire\",Id=\"11970\",Name=\"Fire Nova\"},{Effect=\"Taragaman the Hungerer punches an enemy, knocking them back.\",Icon=\"INV_Gauntlets_05\",Id=\"18072\",Name=\"Uppercut\"}},L=\"14145:33,14148:33,14149:33,64:25\"},\n{Id=\"11518\",Name=\"Jergosh the Invoker\",Story=\"Jergosh the Invoker has rejected the ideals of the orcs and practices the dark and demonic arts of the warlock. A leader of the Searing Blade cultists, Jergosh dwells within Ragefire Chasm, concocting a scheme dangerous enough to draw the attention of Thrall himself.\",Portrait=M..\"dungeons\\\\rfc\\\\jergosh-portrait\",Frame=M..\"dungeons\\\\rfc\\\\jergosh-frame\",MapCoordinateX=34.1,MapCoordinateY=81.5,Abilities={{Effect=\"Jergosh the Invoker burns an enemy, inflicting fire damage over time.\",Icon=\"Spell_Fire_Immolation\",Id=\"348\",Name=\"Immolate\"},{Effect=\"Jergosh the Invoker curses an enemy, reducing their physical damage dealt for 30 seconds.\",Flags={F.Curse},Icon=\"Spell_Shadow_CurseOfMannoroth\",Id=\"702\",Name=\"Curse of Weakness\"}},L=\"14147:33,14150:33,14151:33,80111:25,55004:25\"},\n{Id=\"11519\",Name=\"Bazzalan\",Story=\"Bazzalan leads the Searing Blade cultists along with Jergosh the Invoker. His motives are unclear, but like all satyr, he is a swift and cunning foe.\",Portrait=M..\"dungeons\\\\rfc\\\\bazzalan-portrait\",Frame=M..\"dungeons\\\\rfc\\\\bazzalan-frame\",MapCoordinateX=41.6,MapCoordinateY=87.2,Abilities={{Effect=\"Bazzalan poisons an enemy, dealing nature damage over time.\",Flags={F.Poison},Icon=\"Spell_Nature_CorrosiveBreath\",Id=\"744\",Name=\"Poison\"},{Effect=\"Bazzalan strikes an enemy, dealing physical damage.\",Icon=\"Spell_Shadow_RitualOfSacrifice\",Id=\"14873\",Name=\"Sinister Strike\"}},L=\"80703:30,80704:30,80705:30,5235:100\"},\n}}\nZLDB.DG[\"RFD\"]={\nName=\"Razorfen Downs\",\nStory=\"Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Many quilboar have taken up residence in the largest cluster of giant thorns, the Razorfen, which they revere as Agamaggan's resting place. Recently, scouts have reported seeing undead milling about the region, engendering fears that the dreaded Scourge may be moving to conquer Kalimdor.\",\nBackground=M..\"dungeons\\\\rfd\\\\background\",\nGridBackground=M..\"dungeons\\\\rfd\\\\grid-background\",\nMapId=22,\nIconScale=0.9,\nMinLevel=35,\nMaxLevel=44,\nEntrances={{MapContinentId=1,MapCoordinateX=49.6,MapCoordinateY=94.5,MapZoneId=27}},\nType=T.Dungeon,\nKey=\"RFD\",\nBosses={\n{Id=\"7356\",Name=\"Plaguemaw the Rotting\",Story=\"A rotting abomination sent to kill any adventurers that dares enter Razorfen Downs.\",Portrait=M..\"dungeons\\\\rfd\\\\plaguemaw-portrait\",Frame=M..\"dungeons\\\\rfd\\\\plaguemaw-frame\",MapCoordinateX=36.3,MapCoordinateY=17.8,L=\"10760:33,10766:33,80744:33,51217:1\"},\n{Id=\"7355\",Name=\"Tuten'kash\",Story=\"Though blinded during the War of the Spider before his conversion to undeath, Tuten'kash still serves the Scourge as one of its deadliest crypt fiend commanders. Tutaen'kash compensates for his blindness by decorating his lair with fine, almost invisible webs that allow him to sense every footstep and the lightest touch, alerting him to send out minions to ambush his hapless prey. Strong vibrations can send him into a disoriented rage, drawing him from his hiding spot deep within Razorfen Downs' recesses.\",Portrait=M..\"dungeons\\\\rfd\\\\tutenkash-portrait\",Frame=M..\"dungeons\\\\rfd\\\\tutenkash-frame\",MapCoordinateX=46.1,MapCoordinateY=26.9,L=\"51217:1,10777:33,10776:33,10775:33\"},\n{Id=\"7357\",Name=\"Mordresh Fire Eye\",Story=\"Through necromantic magic Death Speaker Blackthorn was able to rekindle the flames of Mordresh Fire Eye's soul, returning him to undeath. As a former shaman, Mordresh has exerted his twisted control over the elements. He burns and scorches all those who threaten the Death Speaker's work.\",Portrait=M..\"dungeons\\\\rfd\\\\mordresh-portrait\",Frame=M..\"dungeons\\\\rfd\\\\mordresh-frame\",MapCoordinateX=66.4,MapCoordinateY=37.1,L=\"10769:33,10770:33,10771:33,51217:1\"},\n{Id=\"8567\",Name=\"Glutton\",Story=\"Living up to his name, this massive abomination has spent much of his time in Razorfen Downs gorging himself on the spoiled corpses of boars and their quilboar masters. The mass of rancid meat within his gut emanates a cloud of noxious fumes and crippling diseases, choking unfortunate adventurers who stray too close.\",Portrait=M..\"dungeons\\\\rfd\\\\glutton-portrait\",Frame=M..\"dungeons\\\\rfd\\\\glutton-frame\",MapCoordinateX=27.6,MapCoordinateY=55.6,L=\"80745:33,10774:33,10772:33,51217:1\"},\n{Id=\"62679\",Name=\"Death Prophet Rakameg\",Story=\"As Amnennar the Coldbringer's influence expands, he has appointed Death Prophet Rakameg to oversee the collection of dark obsidian required for the Lich's most nefarious sorceries. Rakameg acts as a conduit for the malevolent essence surging through the Downs, preaching a gospel of undeath to the displaced quilboar. He is fiercely protective of the obsidian artifacts within the bastion of darkness, viewing them as the key to ensuring his master's immortal essence remains unassailable by those who seek to mend the world's fractures.\",Portrait=M..\"dungeons\\\\rfd\\\\rakameg-portrait\",Frame=M..\"dungeons\\\\rfd\\\\rakameg-frame\",MapCoordinateX=44.6,MapCoordinateY=81.1,L=\"58172:25,58173:25,58174:25,58175:25\"},\n{Id=\"7354\",Name=\"Ragglesnout\",Story=\"An elusive quillboar, rarely seen among the denizens of Razorfen Downs. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\rfd\\\\ragglesnout-portrait\",Frame=M..\"dungeons\\\\rfd\\\\ragglesnout-frame\",MapCoordinateX=27.9,MapCoordinateY=47.3,IsRare=true,L=\"10758:33,10767:33,10768:33\"},\n{Id=\"7358\",Name=\"Amnennar the Coldbringer\",Story=\"The lich Amnennar began plans to create a base from which to strike at Orgrimmar and Theramore. To that end, Amnennar has set his sights on recruiting the recently displaced and desperate quilboar people, promising them power over death so they can repel invaders in their lands.\",Portrait=M..\"dungeons\\\\rfd\\\\amnennar-portrait\",Frame=M..\"dungeons\\\\rfd\\\\amnennar-frame\",MapCoordinateX=34.1,MapCoordinateY=49.1,L=\"10761:20,10762:20,10763:20,10764:20,10765:20,51217:5\"},\n}}\nZLDB.DG[\"RFK\"]={\nName=\"Razorfen Kraul\",\nStory=\"Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Many quilboar have taken up residence in the largest cluster of giant thorns, the Razorfen, which they revere as Agamaggan's resting place.\",\nBackground=M..\"dungeons\\\\rfk\\\\background\",\nGridBackground=M..\"dungeons\\\\rfk\\\\grid-background\",\nMapId=23,\nIconScale=0.9,\nMinLevel=29,\nMaxLevel=36,\nEntrances={{MapContinentId=1,MapCoordinateX=40.8,MapCoordinateY=89.4,MapZoneId=27}},\nType=T.Dungeon,\nKey=\"RFK\",\nBosses={\n{Id=\"4428\",Name=\"Death Speaker Jargba\",Story=\"The Death Speakers of the Death's Head tribe serve two functions: to disseminate propaganda and to discipline those who refuse to obey Charlga Razorflank and, by extension, her mysterious new allies. Jargba has made a name for himself among the Death Speakers by dominating the very minds of dissidents, forcing them to accept the will of their leaders.\",Portrait=M..\"dungeons\\\\rfk\\\\jargba-portrait\",Frame=M..\"dungeons\\\\rfk\\\\jargba-frame\",MapCoordinateX=87.7,MapCoordinateY=41.9,L=\"2816:33,6682:33,6685:33\"},\n{Id=\"4424\",Name=\"Aggem Thorncurse\",Story=\"The commander of the Razorfen military forces, Warlord Ramtusk is a massive aging Quilboar whose thick hide bears the scars of many battles with centaur, harpies, orcs, and even tauren. In his later years, Ramtusk has embraced the company of Quilboar spirit leaders; Aggem Thorncurse and Death Speaker Jargba guide his thoughts from the spirit realm.\",Portrait=M..\"dungeons\\\\rfk\\\\aggem-portrait\",Frame=M..\"dungeons\\\\rfk\\\\aggem-frame\",MapCoordinateX=80.7,MapCoordinateY=52,L=\"80732:35,80733:35\"},\n{Id=\"4420\",Name=\"Overlord Ramtusk\",Story=\"The commander of the Death's Head military forces, Overlord Ramtusk is a massive aging quilboar whose thick hide bears the scars of many battles with centaur, harpies, orcs, and even tauren. Rather than being slowed by his advanced years, Ramtusk directs his troops with the swift and confident authority of a battle-forged veteran. Striking him down would surely deal a crippling blow to the Death's Head.\",Portrait=M..\"dungeons\\\\rfk\\\\ramtusk-portrait\",Frame=M..\"dungeons\\\\rfk\\\\ramtusk-frame\",MapCoordinateX=56.8,MapCoordinateY=30.1,L=\"6686:33,6687:33,80734:33\"},\n{Id=\"4842\",Name=\"Earthcaller Halmgar\",Story=\"An elusive quillboar, rarely seen among the denizens of Razorfen Kraul. She is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter her in the first place...\",Portrait=M..\"dungeons\\\\rfk\\\\halmgar-portrait\",Frame=M..\"dungeons\\\\rfk\\\\halmgar-frame\",MapCoordinateX=48.5,MapCoordinateY=45.1,IsRare=true,L=\"6688:50,6689:50\"},\n{Id=\"62503\",Name=\"Rotthorn\",Story=\"Rotthorn is the living embodiment of the gnarled natural magic that has twisted the order of Razorfen Kraul into a mess of bramble and thorn. Originally thought to be a product of primitive quilboar magic, this Bramblehide elemental was actually driven to madness by a much darker, sinister presence lurking within the lair. It now manifests in a state of perpetual anger, its very heart-the Tainted Brambleheart-pulsating with a foreign energy that even the most experienced druids find inscrutable and deeply unsettling.\",Portrait=M..\"dungeons\\\\rfk\\\\rotthorn-portrait\",Frame=M..\"dungeons\\\\rfk\\\\rotthorn-frame\",MapCoordinateX=31,MapCoordinateY=75.7,L=\"50800:25,58089:25,58090:25,58091:25\"},\n{Id=\"4422\",Name=\"Agathelos the Raging\",Story=\"Boars are revered within quilboar culture, and particularly large and tenacious ones are seen as a favor from Agamaggan. Already a powerful creature, Agathelos has been fed Kraul bat guano, which produces a maddening effect, resulting in increased stamina and strength. The Death's Head plan to utilize Agathelos as a powerful weapon to crush all who oppose them.\",Portrait=M..\"dungeons\\\\rfk\\\\agathelos-portrait\",Frame=M..\"dungeons\\\\rfk\\\\agathelos-frame\",MapCoordinateX=8.2,MapCoordinateY=68.4,L=\"6690:25,6691:25,80735:25,80736:25,69170:1\"},\n{Id=\"4425\",Name=\"Blind Hunter\",Story=\"An elusive bat, rarely seen among the denizens of Razorfen Kraul. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\rfk\\\\hunter-portrait\",Frame=M..\"dungeons\\\\rfk\\\\hunter-frame\",MapCoordinateX=12.3,MapCoordinateY=32.5,IsRare=true,L=\"6695:33,6696:33,6697:33\"},\n{Id=\"4421\",Name=\"Charlga Razorflank\",Story=\"The leader (or \\\"crone\\\") of the Razorfen tribes is Charlga Razorflank, a quilboar whose experimental and powerful Geomancy practices are second to none. Her meteoric rise to power and the rapidly increasing violence between quilboar tribesmen can only lead to one thing: war.\",Portrait=M..\"dungeons\\\\rfk\\\\charlga-portrait\",Frame=M..\"dungeons\\\\rfk\\\\charlga-frame\",MapCoordinateX=21.8,MapCoordinateY=30.9,L=\"6692:33,6693:33,6694:33,51217:1\"},\n}}\nZLDB.DG[\"SCHOLO\"]={\nName=\"Scholomance\",\nStory=\"Individuals seeking to master the powers of undeath know well of Scholomance, the infamous school of necromancy located in the dark and foreboding crypts beneath Caer Darrow. In recent years, several of the instructors have changed, but the institution remains under the control of Darkmaster Gandling, a particularly sadistic and insidious practitioner of necromantic magic.\",\nBackground=M..\"dungeons\\\\scholo\\\\background\",\nGridBackground=M..\"dungeons\\\\scholo\\\\grid-background\",\nMapId=25,\nIconScale=0.9,\nMinLevel=58,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=69,MapCoordinateY=74.9,MapZoneId=37}},\nType=T.Dungeon,\nKey=\"SCHOLO\",\nBosses={\n{Id=\"10506\",Name=\"Kirtonos the Herald\",Story=\"Long ago, he became the master of Scholomance's Doctor Theolen Krastinov. Responsible for many of the atrocities during Krastinov's rule over Scholomance, Kirtonos fed on the blood of his innocent victims. To appease his master, Doctor Krastinov had to provide the gargoyle with more and more blood.\",Portrait=M..\"dungeons\\\\scholo\\\\kirtonos-portrait\",Frame=M..\"dungeons\\\\scholo\\\\kirtonos-frame\",L=\"13955:11,13956:11,13957:11,13960:11,13967:11,13969:11,13983:11,14024:11,16734:11,51217:5\"},\n{Id=\"10503\",Name=\"Jandice Barov\",Story=\"Jandice Barov was once an archmage of Dalaran and a powerful illusionist. In life, she developed a spell that \\\"displayed several images of her body that were nearly indistinguishable from her real form. These images duplicated her actions from different locations, making it nearly impossible for her enemies to find her. It was almost infallible.\\\" After House Barov pledged their allegiance to the Cult of the Damned, Jandice was turned into an undead ghost within Scholomance.\",Portrait=M..\"dungeons\\\\scholo\\\\jandice-portrait\",Frame=M..\"dungeons\\\\scholo\\\\jandice-frame\",L=\"14541:14,14545:14,14548:14,16701:14,18689:14,18690:14,22394:14,51217:5,70226:2\"},\n{Id=\"11622\",Name=\"Rattlegore\",Story=\"Rattlegore is made from the remains of his defeated enemies. He guard Scholomance against intruders to this day.\",Portrait=M..\"dungeons\\\\scholo\\\\rattlegore-portrait\",Frame=M..\"dungeons\\\\scholo\\\\rattlegore-frame\",L=\"18782:40,14528:14,14531:14,14537:14,14538:14,14539:14,16711:14,18686:14,51217:5,70226:2\"},\n{Id=\"14516\",Name=\"Death Knight Darkreaver\",Story=\"Once a celebrated paladin, the man who would come to be known as Darkreaver was seduced by the call of the Lich King, and became an insidious death knight. His corruption spread to his steed, who was transformed into an undead horse. Darkreaver was sent to the Scholomance. In the dungeon below the Great Ossuary, he attempted to bend the spirit realm to his whim, summoning and corrupting spirits to do his bidding.\",Portrait=M..\"dungeons\\\\scholo\\\\darkreaver-portrait\",Frame=M..\"dungeons\\\\scholo\\\\darkreaver-frame\",L=\"18758:25,18759:25,18760:25,18761:25\"},\n{Id=\"10433\",Name=\"Marduk Blackpool\",Story=\"Marduk Blackpool, also known as Marduk the Black, is an infamous death knight of the Scourge. He is a tutor at Scholomance, sharing his dark secrets to the students of necromancy.\",Portrait=M..\"dungeons\\\\scholo\\\\marduk-portrait\",Frame=M..\"dungeons\\\\scholo\\\\marduk-frame\",L=\"14576:7,18692:7,51217:5,70226:2\"},\n{Id=\"10432\",Name=\"Vectus\",Story=\"Vectus developed the plagued dragons found inside Scholomance, which he got by paying Tinkee Steamboil in the Burning Steppes to deliver dragon eggs from Blackrock Spire.\",Portrait=M..\"dungeons\\\\scholo\\\\vectus-portrait\",Frame=M..\"dungeons\\\\scholo\\\\vectus-frame\",L=\"14577:7,18691:7,51217:5,70226:2\"},\n{Id=\"10508\",Name=\"Ras Frostwhisper\",Story=\"Ras Frostwhisper was once a human mage from Stromgarde. He was a hedge mage, a rogue wizard that never received his formal training from Dalaran. He was among the first to join the Cult of the Damned and quickly advanced through its ranks. He is now an overseer of Scholomance.\",Portrait=M..\"dungeons\\\\scholo\\\\ras-portrait\",Frame=M..\"dungeons\\\\scholo\\\\ras-frame\",L=\"13952:8,14340:8,14487:8,14502:8,14503:8,14522:8,14525:8,16689:8,18693:8,18694:8,18695:8,18696:8,13314:2,13521:3,51217:5,70226:2\"},\n{Id=\"16118\",Name=\"Kormok\",Story=\"Kormok is an ogre necromancer boss found in Scholomance. One of his heads was always cheerful if not a little foolish, while the other was sly, calculating and had an almost dead look to its eyes. While initially a mere mage and not being that bad as a member of the Veiled Blade, he became exposed to the necromantic side of magic and ended up delighting in summoning forth the souls of the banished dead of Purgation Isle. After quitting his mercenary company he enrolled at the Scholomance.\",Portrait=M..\"dungeons\\\\scholo\\\\kormok-portrait\",Frame=M..\"dungeons\\\\scholo\\\\kormok-frame\",L=\"22303:20,22326:20,22331:20,22332:20,22333:20\"},\n{Id=\"10505\",Name=\"Instructor Malicia\",Story=\"A former high elf of Quel'Thalas, Malicia was one of the few of her kind to willingly join the Cult of the Damned before the fall of Silvermoon. Now an unliving tutor of the dark arts, she oversees the physical and tactical training of the school's acolytes. Malicia is notorious for her cruelty, often using her students as living targets for her devastating shadow magic to ensure that only the most ruthless and resilient survive to serve the Lich King.\",Portrait=M..\"dungeons\\\\scholo\\\\malicia-portrait\",Frame=M..\"dungeons\\\\scholo\\\\malicia-frame\",L=\"12753:17,51217:5,14611:4,14612:4,14614:4,70226:2,16710:4,23201:4,23200:4,18683:4,18684:4,18682:4,18681:4,18680:4,14641:4,14640:4,14638:4,14637:4,14636:4,14633:4,14632:4,14631:4,14629:4,14626:4,14624:4,14623:4,14622:4,14621:4,14620:4,14616:4,14615:4\"},\n{Id=\"11261\",Name=\"Doctor Theolen Krastinov\",Story=\"Known as \\\"The Butcher\\\", Krastinov is the servant of Kirtonos the Herald and the main torturer and provider of bodies and bodily parts for the Scholomance's necromancy experiments. His first victims were recruited from among the household of Caer Darrow. Among them were servants of the Barov family, Eva and Lucien Sarkhoff. Trapped, tortured and maimed for months, they vowed vengeance on Krastinov even beyond the grave.\",Portrait=M..\"dungeons\\\\scholo\\\\krastinov-portrait\",Frame=M..\"dungeons\\\\scholo\\\\krastinov-frame\",L=\"16684:14,51217:5,14612:4,14614:4,14611:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14626:4,14624:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,70226:2,14617:2,23201:4,23200:4,18684:4,18683:4,18681:4,18682:4,18680:4,14641:4\"},\n{Id=\"10901\",Name=\"Lorekeeper Polkelt\",Story=\"Lorekeeper Polkelt was once the keeper of knowledge, knowledge that has sadly been lost, however, as he is now a shambling, unintelligent monster.\",Portrait=M..\"dungeons\\\\scholo\\\\polkelt-portrait\",Frame=M..\"dungeons\\\\scholo\\\\polkelt-frame\",L=\"12753:17,16705:17,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,70226:2,23201:4,23200:4,18684:4,18683:4,18682:4,18681:4,18680:4\"},\n{Id=\"10507\",Name=\"The Ravenian\",Story=\"The Ravenian is a monstrous abomination of unparalleled hunger, serving as the school's ultimate 'disciplinary' measure. Stitched together from the strongest remains available to the cult, he resides in the lower pits of the academy where he is fed the failures and the weak. Unlike the more intelligent faculty, the Ravenian is a creature of pure, gluttonous instinct, acting as a massive wall of rotting flesh between intruders and the school's most guarded secrets.\",Portrait=M..\"dungeons\\\\scholo\\\\ravenian-portrait\",Frame=M..\"dungeons\\\\scholo\\\\ravenian-frame\",L=\"12753:17,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,18680:4,18681:4,18682:4,18683:4,23200:4,18684:4,23201:4,16716:4,70226:2\"},\n{Id=\"10504\",Name=\"Lord Alexei Barov\",Story=\"Lord Alexei Barov was the lord of Caer Darrow, Brill, Tarren Mill and Southshore. He was the father of Alexi, Weldon, and Jandice Barov and husband of Lady Illucia Barov. Like Jandice and Illucia, he is now an agent of the Scourge found in Scholomance.\",Portrait=M..\"dungeons\\\\scholo\\\\alexei-portrait\",Frame=M..\"dungeons\\\\scholo\\\\alexei-frame\",L=\"16722:5,51217:5,14611:4,14612:4,14615:4,14614:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14638:4,14640:4,14637:4,14641:4,18680:4,18681:4,18682:4,18683:4,18684:4,23200:4,23201:4,70226:2\"},\n{Id=\"10502\",Name=\"Lady Illucia Barov\",Story=\"As the wife of Lord Alexei Barov, Illucia shared in the family's dark pact with Kel'Thuzad, trading the ancestral lands of Caer Darrow for the hollow promise of eternal life. Now a spectral shadow of her former noble self, she haunts the academy's study halls. Illucia retains the aristocratic arrogance she held in life, using her mastery of mind control and psychic agony to break the wills of those who dare trespass in her family's desecrated home.\",Portrait=M..\"dungeons\\\\scholo\\\\illucia-portrait\",Frame=M..\"dungeons\\\\scholo\\\\illucia-frame\",L=\"12753:19,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,18680:4,18681:4,18682:4,18683:4,18684:4,23200:4,23201:4,70226:2\"},\n{Id=\"1853\",Name=\"Darkmaster Gandling\",Story=\"Darkmaster Gandling is the headmaster of the School of Necromancy at Caer Darrow, appointed personally by Kel'Thuzad.\",Portrait=M..\"dungeons\\\\scholo\\\\gandling-portrait\",Frame=M..\"dungeons\\\\scholo\\\\gandling-frame\",L=\"56107:30,51217:100,13398:14,13938:14,13944:14,13951:14,13953:14,13964:14,22433:14,16667:11,16677:11,16686:11,16693:11,16698:11,16707:11,16720:11,16727:11,16731:11,13501:10,47413:10,47415:10,14514:7,70226:3,13937:1\"},\n}}\nZLDB.DG[\"SFK\"]={\nName=\"Shadowfang Keep\",\nStory=\"During the Third War, the wizards of the Kirin Tor battled against the undead armies of the Scourge. When the wizards of Dalaran died in battle, they would rise soon after - adding their former might to the growing Scourge. Frustrated by their lack of progress (and against the advice of his peers) the Archmage, Arugal elected to summon extra-dimensional entities to bolster Dalaran's diminishing ranks. Arugal's summoning brought the ravenous worgen into the world of Azeroth. The feral wolf-men slaughtered not only the Scourge, but quickly turned on the wizards themselves. The worgen sieged the keep of the noble, Baron Silverlaine. Situated above the tiny hamlet of Pyrewood, the keep quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'. It's said he still resides there, protected by his massive pet, Fenrus - and haunted by the vengeful ghost of Baron Silverlaine.\",\nBackground=M..\"dungeons\\\\sfk\\\\background\",\nGridBackground=M..\"dungeons\\\\sfk\\\\grid-background\",\nMapId=26,\nIconScale=1,\nMinLevel=20,\nMaxLevel=28,\nEntrances={{MapContinentId=2,MapCoordinateX=42.8,MapCoordinateY=67.5,MapZoneId=27}},\nType=T.Dungeon,\nKey=\"SFK\",\nBosses={\n{Id=\"3914\",Name=\"Rethilgore\",Story=\"Rethilgore is one of the most vicious worgen, entrusted by Archmage Arugal to guard the prisoners who have been caught breaking into Shadowfang Keep. These include Deathstalker Adamant, Sorcerer Ashcrombe and Landen Stilwell.\",Portrait=M..\"dungeons\\\\sfk\\\\rethilgore-portrait\",Frame=M..\"dungeons\\\\sfk\\\\rethilgore-frame\",MapCoordinateX=82.7,MapCoordinateY=77,MapIsBelow=true,L=\"80713:35,80714:35\"},\n{Id=\"3886\",Name=\"Razorclaw the Butcher\",Story=\"Razorclaw inhabits the former kitchen of Shadowfang Keep. He slaughtered many innocent humans in Shadowfang Keep when brought in by his master Arugal, hence his nickname.\",Portrait=M..\"dungeons\\\\sfk\\\\razorclaw-portrait\",Frame=M..\"dungeons\\\\sfk\\\\razorclaw-frame\",MapCoordinateX=45.7,MapCoordinateY=58,L=\"1292:33,6226:33,6633:33\"},\n{Id=\"3887\",Name=\"Baron Silverlaine\",Story=\"Silverlaine was the former lord of Shadowfang Keep, but was killed when Archmage Arugal and his worgen took over the keep for their own sinister plans. He now haunts the dining room with some of his servants.\",Portrait=M..\"dungeons\\\\sfk\\\\silverlaine-portrait\",Frame=M..\"dungeons\\\\sfk\\\\silverlaine-frame\",MapCoordinateX=37.2,MapCoordinateY=81.6,L=\"6321:50,6323:50,80715:35\"},\n{Id=\"61969\",Name=\"Prelate Ironmane\",Story=\"Once a man of peerless faith, Prelate Ironmane was renowned for sermons so moving they stirred the hearts of even the most devout holy men. While his friend Father Brightcopf managed to regain his free will after the Lich King's influence waned, Ironmane was not so fortunate. Consumed by the darkness of Shadowfang Keep and the blood magic of Arugal, he remains a loyal servant to the madness within the walls. He stands as a tragic monument to fallen grace, wielding the Light he once preached as a weapon of terror against any who seek to end the Keep's curse.\",Portrait=M..\"dungeons\\\\sfk\\\\ironmane-portrait\",Frame=M..\"dungeons\\\\sfk\\\\ironmane-frame\",MapCoordinateX=12.1,MapCoordinateY=64.7,L=\"55382:25,55383:25,55384:25,55385:25\"},\n{Id=\"4278\",Name=\"Commander Springvale\",Story=\"A loyal soldier, the ghost of Commander Springvale haunts the council room, using unholy strikes to avenge his lord, Baron Silverlaine.\",Portrait=M..\"dungeons\\\\sfk\\\\springvale-portrait\",Frame=M..\"dungeons\\\\sfk\\\\springvale-frame\",MapCoordinateX=47,MapCoordinateY=66.1,L=\"3191:50,6320:50,80717:35\"},\n{Id=\"4279\",Name=\"Odo the Blindwatcher\",Story=\"Odo lives in the dilapidated wooden structure hanging precariously off the side of the keep with two pet bats, a Blood Seeker and a Vile Bat. Although he lost his eyesight long ago (hence his nickname), he has adapted to using his other senses, much like his pets.\",Portrait=M..\"dungeons\\\\sfk\\\\odo-portrait\",Frame=M..\"dungeons\\\\sfk\\\\odo-frame\",MapCoordinateX=76.6,MapCoordinateY=70.9,L=\"6318:50,6319:50\"},\n{Id=\"3872\",Name=\"Deathsworn Captain\",Story=\"An elusive human ghost, rarely seen among the general population of Shadowfang Keep. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\sfk\\\\deathsworn-portrait\",Frame=M..\"dungeons\\\\sfk\\\\deathsworn-frame\",MapCoordinateX=78,MapCoordinateY=51,IsRare=true,L=\"6641:50,6642:50\"},\n{Id=\"4274\",Name=\"Fenrus the Devourer\",Story=\"Fenrus is the pet of Arugal, Archmage of Shadowfang Keep. Fenrus prowls the main study of Arugal's chambers. He is unbelievably large, and it is possible the worg was subject to dark magic at the hands of Arugal or the worgen.\",Portrait=M..\"dungeons\\\\sfk\\\\fenrus-portrait\",Frame=M..\"dungeons\\\\sfk\\\\fenrus-frame\",MapCoordinateX=68.9,MapCoordinateY=34.3,MapIsBelow=true,L=\"3230:50,6340:50\"},\n{Id=\"3927\",Name=\"Wolf Master Nandos\",Story=\"He is the worgen master of the lesser worgs, and has his own pack which will fight heroes before they engage him. He is the last henchman of Arugal to obstruct the path.\",Portrait=M..\"dungeons\\\\sfk\\\\nandos-portrait\",Frame=M..\"dungeons\\\\sfk\\\\nandos-frame\",MapCoordinateX=70.5,MapCoordinateY=28.9,L=\"80716:25,6314:25,3748:50\"},\n{Id=\"4275\",Name=\"Archmage Arugal\",Story=\"Archmage Arugal is a former mage of Dalaran who lived within the ruins of Shadowfang Keep and was later raised from the dead in the service of the Scourge. He is most notorious for having unleashed the worgen once more unto the world by freeing them from the Emerald Dream.\",Portrait=M..\"dungeons\\\\sfk\\\\arugal-portrait\",Frame=M..\"dungeons\\\\sfk\\\\arugal-frame\",MapCoordinateX=73.8,MapCoordinateY=6.9,L=\"6220:33,6324:33,6392:33,51217:1\"},\n}}\nZLDB.DG[\"SMARM\"]={\nName=\"Scarlet Monastery (Armory)\",\nStory=\"The monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful monastery was converted into a stronghold of the fanatical Scarlet Crusade. The crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.\",\nBackground=M..\"dungeons\\\\smarm\\\\background\",\nGridBackground=M..\"dungeons\\\\smarm\\\\grid-background\",\nMapId=24,\nZoneId=1,\nIconScale=1,\nMinLevel=34,\nMaxLevel=42,\nEntrances={{MapContinentId=2,MapCoordinateX=84.1,MapCoordinateY=44.2,MapDestinationZoneId=1,MapZoneId=25}},\nType=T.Dungeon,\nKey=\"SMARM\",\nBosses={\n{Id=\"61982\",Name=\"Armory Quartermaster Daghelm\",Story=\"Once a promising apprentice to the master blacksmith Basil Frye, Daghelm chose to stay at the Monastery when the Scourge hit, while his mentor fled to the muck of the Undercity. The years of isolation and fanaticism have turned him into a psychotic zealot, obsessed with forging armor within the 'blessings' of the Light. He still carries his mentor's journal on Lightforge ingots, refusing to relinquish the precious notes even as the Crusade he serves crumbles into corruption around him.\",Portrait=M..\"dungeons\\\\smarm\\\\daghelm-portrait\",Frame=M..\"dungeons\\\\smarm\\\\daghelm-frame\",MapCoordinateX=57.4,MapCoordinateY=38.5,MapId=1,L=\"55474:25,55475:25,55476:25,55477:25\"},\n{Id=\"3975\",Name=\"Herod\",Story=\"Herod is one of the four Scarlet Crusade leaders in the Scarlet Monastery. A champion of the Scarlet Crusade, he is known for his brutish reputation.\",Portrait=M..\"dungeons\\\\smarm\\\\herod-portrait\",Frame=M..\"dungeons\\\\smarm\\\\herod-frame\",MapCoordinateX=78.7,MapCoordinateY=1,MapId=\"1\",L=\"7717:25,7718:25,7719:25,10330:25,51217:1\"},\n}}\nZLDB.DG[\"SMCATH\"]={\nName=\"Scarlet Monastery (Cathedral)\",\nStory=\"The monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful monastery was converted into a stronghold of the fanatical Scarlet Crusade. The crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.\",\nBackground=M..\"dungeons\\\\smcath\\\\background\",\nGridBackground=M..\"dungeons\\\\smcath\\\\grid-background\",\nMapId=24,\nZoneId=2,\nIconScale=0.8,\nMinLevel=35,\nMaxLevel=45,\nEntrances={{MapContinentId=2,MapCoordinateX=78.9,MapCoordinateY=28.2,MapDestinationZoneId=2,MapZoneId=25}},\nType=T.Dungeon,\nKey=\"SMCATH\",\nBosses={\n{Id=\"4542\",Name=\"High Inquisitor Fairbanks\",Story=\"Once a priest and member of the Knights of the Silver Hand, as the closest advisor to Highlord Mograine, he was also the former High Inquisitor of the Scarlet Crusade. Executed by the crusaders for his blasphemous accusations against Saidan Dathrohan and Renault Mograine, he eventually became an undead.\",Portrait=M..\"dungeons\\\\smcath\\\\fairbanks-portrait\",Frame=M..\"dungeons\\\\smcath\\\\fairbanks-frame\",MapCoordinateX=55.5,MapCoordinateY=25.2,MapId=2,L=\"19507:33,19508:33,19509:33\"},\n{Id=\"3976\",Name=\"Scarlet Commander Mograine\",Story=\"In his youth, Renault was a member of the Knights of the Silver Hand and the son of their leader, Highlord Alexandros Mograine. Manipulated by Balnazzar through the possessed corpse of Saidan Dathrohan, and jealous of the attention given to his brother Darion Mograine, Renault accepted the offer of the Grand Crusader and led his father into an ambush before murdering him with the Ashbringer. As promised, Renault became the Scarlet Commander of the Scarlet Monastery.\",Portrait=M..\"dungeons\\\\smcath\\\\mograine-portrait\",Frame=M..\"dungeons\\\\smcath\\\\mograine-frame\",MapCoordinateX=49.1,MapCoordinateY=27.7,MapId=2,L=\"7723:25,7724:25,7726:25,10330:25,51804:8,51217:1\"},\n{Id=\"3977\",Name=\"High Inquisitor Whitemane\",Story=\"Sally Whitemane is a priestess of the Light and the High Inquisitor of the Scarlet Crusade. She directs their activities from within the Scarlet Monastery's Cathedral.\",Portrait=M..\"dungeons\\\\smcath\\\\whitemane-portrait\",Frame=M..\"dungeons\\\\smcath\\\\whitemane-frame\",MapCoordinateX=49.1,MapCoordinateY=16.8,MapId=2,L=\"7720:33,7721:33,7722:33,51217:1\"},\n}}\nZLDB.DG[\"SMGY\"]={\nName=\"Scarlet Monastery (Graveyard)\",\nStory=\"The monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful monastery was converted into a stronghold of the fanatical Scarlet Crusade. The crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.\",\nBackground=M..\"dungeons\\\\smgy\\\\background\",\nGridBackground=M..\"dungeons\\\\smgy\\\\grid-background\",\nMapId=24,\nZoneId=3,\nIconScale=0.9,\nMinLevel=30,\nMaxLevel=37,\nEntrances={{MapContinentId=2,MapCoordinateX=68.3,MapCoordinateY=21.1,MapDestinationZoneId=3,MapZoneId=25}},\nType=T.Dungeon,\nKey=\"SMGY\",\nBosses={\n{Id=\"3983\",Name=\"Interrogator Vishas\",Story=\"James Vishas is the Scarlet Crusade's lead interrogator at the Scarlet Monastery. He enjoys torturing any captured undead and takes great pride in his work. Vishas is known for his unrelenting sadism, cruel expertise, and high pitched voice.\",Portrait=M..\"dungeons\\\\smgy\\\\vishas-portrait\",Frame=M..\"dungeons\\\\smgy\\\\vishas-frame\",MapCoordinateX=72.1,MapCoordinateY=59.8,MapId=3,L=\"7682:25,7683:25,80741:25,80742:25,51217:1\"},\n{Id=\"61972\",Name=\"Duke Dreadmoore\",Story=\"Not much is known about Duke Dreadmoore, a death knight believed to be a harbinger of Naxxramas. Recently captured by the Scarlet Crusade, he lies imprisoned within the monastery’s underground cells beneath the torture chambers, where he is subjected to relentless experimentation. Though bound and studied, Dreadmoore remains far from broken, biding his time and awaiting the moment to unleash the full extent of his dark power upon his captors.\",Portrait=M..\"dungeons\\\\smgy\\\\dreadmoore-portrait\",Frame=M..\"dungeons\\\\smgy\\\\dreadmoore-frame\",MapCoordinateX=77.6,MapCoordinateY=38.2,MapId=3,L=\"55386:25,55388:25,55387:25,55389:25\"},\n{Id=\"6489\",Name=\"Ironspine\",Story=\"An elusive undead, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\smgy\\\\ironspine-portrait\",Frame=M..\"dungeons\\\\smgy\\\\ironspine-frame\",MapCoordinateX=48.9,MapCoordinateY=66.2,MapId=3,IsRare=true,L=\"7688:33,7687:33,7686:33\"},\n{Id=\"6490\",Name=\"Azshir the Sleepless\",Story=\"An elusive human ghost, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\smgy\\\\azshir-portrait\",Frame=M..\"dungeons\\\\smgy\\\\azshir-frame\",MapCoordinateX=41.1,MapCoordinateY=46.6,MapId=3,IsRare=true,L=\"7708:33,7709:33,7731:33\"},\n{Id=\"6488\",Name=\"Fallen Champion\",Story=\"An elusive undead, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\smgy\\\\champion-portrait\",Frame=M..\"dungeons\\\\smgy\\\\champion-frame\",MapCoordinateX=26.3,MapCoordinateY=45.7,MapId=3,IsRare=true,L=\"7689:33,7690:33,7691:33\"},\n{Id=\"4543\",Name=\"Bloodmage Thalnos\",Story=\"Thalnos earned repute in the Scarlet Crusade for the brutal torture methods he used to \\\"purify\\\" new recruits. Ultimately the sadistic mage contracted the plague of undeath and arose as a fearsome skeletal being. The vengeful Thalnos prowled the monastery's graveyard commanding apparitions and zombified creatures to attack anyone who trespasses on his unholy domain.\",Portrait=M..\"dungeons\\\\smgy\\\\thalnos-portrait\",Frame=M..\"dungeons\\\\smgy\\\\thalnos-frame\",MapCoordinateX=24.3,MapCoordinateY=56.2,MapId=3,MapIsBelow=true,L=\"7685:50,7684:35,80743:15,51217:1\"},\n}}\nZLDB.DG[\"SMLIB\"]={\nName=\"Scarlet Monastery (Library)\",\nStory=\"The monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful monastery was converted into a stronghold of the fanatical Scarlet Crusade. The crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.\",\nBackground=M..\"dungeons\\\\smlib\\\\background\",\nGridBackground=M..\"dungeons\\\\smlib\\\\grid-background\",\nMapId=24,\nZoneId=4,\nIconScale=1,\nMinLevel=32,\nMaxLevel=40,\nEntrances={{MapContinentId=2,MapCoordinateX=79.2,MapCoordinateY=60.2,MapDestinationZoneId=4,MapZoneId=25}},\nType=T.Dungeon,\nKey=\"SMLIB\",\nBosses={\n{Id=\"3974\",Name=\"Houndmaster Loksey\",Story=\"Houndmaster Loksey is one of the four leaders of the Scarlet Monastery, and the captain in charge of training the hounds that the Scarlet Crusade uses to track down their enemies. Loksey commands the loyalty of fearsome dogs that can tear their victims apart limb by limb within minutes.\",Portrait=M..\"dungeons\\\\smlib\\\\loksey-portrait\",Frame=M..\"dungeons\\\\smlib\\\\loksey-frame\",MapCoordinateX=29.4,MapCoordinateY=84.4,MapId=4,L=\"7710:33,3456:33,7756:33,51217:1\"},\n{Id=\"61983\",Name=\"Brother Wystan\",Story=\"Brother Wystan serves as a gatekeeper of the Monastery's archives, fanatically protecting the 'heretical' objects the Crusade has seized from the outside world. Among his collection is a Thorium Tuned Servo, a complex piece of engineering he considers an affront to the Light. While many mages like Elias have fled the order after witnessing the elite's descent into madness and necromancy, Wystan remains a stalwart shield, ensuring no 'unnatural' influence leaves the Library's walls.\",Portrait=M..\"dungeons\\\\smlib\\\\wystan-portrait\",Frame=M..\"dungeons\\\\smlib\\\\wystan-frame\",MapCoordinateX=71.8,MapCoordinateY=40.8,MapId=4,L=\"55470:25,55471:25,55472:25,55473:25\"},\n{Id=\"6487\",Name=\"Arcanist Doan\",Story=\"Doan acts as the keeper of the Scarlet Monastery's library; a guardian of the arcane that the Scarlet Crusade is rumored to distrust. Yet he is indeed a trusted official of the Crusade, keeping a vital key that granted access to Scarlet operations across the Plaguelands. Arcanist Doan believes that arcane magic is the only way to rid Lordaeron of the Scourge.\",Portrait=M..\"dungeons\\\\smlib\\\\doan-portrait\",Frame=M..\"dungeons\\\\smlib\\\\doan-frame\",MapCoordinateX=83.4,MapCoordinateY=74.6,MapId=4,L=\"7711:25,7712:25,7713:25,7714:25,51217:1\"},\n}}\nZLDB.DG[\"ST\"]={\nName=\"The Temple of Atal'Hakkar\",\nStory=\"Thousands of years ago, the Gurubashi empire was plunged into a civil war by a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people exiled the Atal'ai to the Swamp of Sorrows, where the priests built the Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the temple beneath the swamp and assigned wardens to ensure that the summoning rituals never be performed again.\",\nBackground=M..\"dungeons\\\\st\\\\background\",\nGridBackground=M..\"dungeons\\\\st\\\\grid-background\",\nMapId=6,\nIconScale=0.9,\nMinLevel=46,\nMaxLevel=54,\nEntrances={{MapContinentId=2,MapCoordinateX=70.1,MapCoordinateY=54.6,MapZoneId=30}},\nType=T.Dungeon,\nKey=\"ST\",\nBosses={\n{Id=\"8580\",Name=\"Atal'alarion\",Story=\"Atal'alarion is the sworn protector of the idol found on the lowest level of the temple.\",Portrait=M..\"dungeons\\\\st\\\\atalalarion-portrait\",Frame=M..\"dungeons\\\\st\\\\atalalarion-frame\",MapCoordinateX=50,MapCoordinateY=45.5,MapIsBelow=true,L=\"10798:33,10799:33,10800:33,51217:5,70226:2\"},\n{Id=\"5708\",Name=\"Spawn of Hakkar\",Story=\"One of the many spawns of Hakkar, wandering through the halls of the sunken temple...\",Portrait=M..\"dungeons\\\\st\\\\spawn-portrait\",Frame=M..\"dungeons\\\\st\\\\spawn-frame\",MapCoordinateX=50,MapCoordinateY=66.3,MapIsBelow=true,L=\"10801:47,10802:26\"},\n{Id=\"5713\",Name=\"Gasher\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\gasher-portrait\",Frame=M..\"dungeons\\\\st\\\\gasher-frame\",MapCoordinateX=55.1,MapCoordinateY=32.6,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5717\",Name=\"Mijan\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\mijan-portrait\",Frame=M..\"dungeons\\\\st\\\\mijan-frame\",MapCoordinateX=60.4,MapCoordinateY=45.9,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5712\",Name=\"Zolo\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\zolo-portrait\",Frame=M..\"dungeons\\\\st\\\\zolo-frame\",MapCoordinateX=55.3,MapCoordinateY=59.2,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5716\",Name=\"Zul'Lor\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\zullor-portrait\",Frame=M..\"dungeons\\\\st\\\\zullor-frame\",MapCoordinateX=45,MapCoordinateY=59.4,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5715\",Name=\"Hukku\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\hukku-portrait\",Frame=M..\"dungeons\\\\st\\\\hukku-frame\",MapCoordinateX=39.6,MapCoordinateY=45.8,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5714\",Name=\"Loro\",Story=\"One of the six trolls protectors, keeping the dreamer asleep...\",Portrait=M..\"dungeons\\\\st\\\\loro-portrait\",Frame=M..\"dungeons\\\\st\\\\loro-frame\",MapCoordinateX=45,MapCoordinateY=32.2,L=\"10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2\"},\n{Id=\"5710\",Name=\"Jammal'an the Prophet\",Story=\"Jammal'an is the current leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar. While in deep meditation, Jammal'an received instructions on how to resurrect Hakkar by using the blood of his draconic foes, the green dragonflight. Jammal'an and his undead bodyguard Ogom the Wretched stand ready to oppose any who would prevent Hakkar's return, though the prophet's actions may unleash upon Azeroth an even more terrible force: the Emerald Nightmare.\",Portrait=M..\"dungeons\\\\st\\\\jammalan-portrait\",Frame=M..\"dungeons\\\\st\\\\jammalan-frame\",MapCoordinateX=76,MapCoordinateY=45.5,L=\"10806:33,10807:33,10808:33,51217:5,70226:2,10803:33,10804:33,10805:33\"},\n{Id=\"5721\",Name=\"Dreamscythe\",Story=\"One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.\",Portrait=M..\"dungeons\\\\st\\\\dreamscythe-portrait\",Frame=M..\"dungeons\\\\st\\\\dreamscythe-frame\",MapCoordinateX=43.2,MapCoordinateY=39.7,L=\"10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2\"},\n{Id=\"5720\",Name=\"Weaver\",Story=\"One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.\",Portrait=M..\"dungeons\\\\st\\\\weaver-portrait\",Frame=M..\"dungeons\\\\st\\\\weaver-frame\",MapCoordinateX=56,MapCoordinateY=51.4,L=\"10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2\"},\n{Id=\"5719\",Name=\"Morphaz\",Story=\"One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.\",Portrait=M..\"dungeons\\\\st\\\\morphaz-portrait\",Frame=M..\"dungeons\\\\st\\\\morphaz-frame\",MapCoordinateX=49.9,MapCoordinateY=86.8,L=\"10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2\"},\n{Id=\"5722\",Name=\"Hazzas\",Story=\"One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.\",Portrait=M..\"dungeons\\\\st\\\\hazzas-portrait\",Frame=M..\"dungeons\\\\st\\\\hazzas-frame\",MapCoordinateX=44,MapCoordinateY=86.8,L=\"10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2\"},\n{Id=\"5709\",Name=\"Shade of Eranikus\",Story=\"Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.\",Portrait=M..\"dungeons\\\\st\\\\eranikus-portrait\",Frame=M..\"dungeons\\\\st\\\\eranikus-frame\",MapCoordinateX=66.5,MapCoordinateY=87.7,L=\"10454:100,10828:17,10829:17,10833:17,10835:17,10836:17,10837:17,10847:1,70226:3\"},\n{Id=\"8443\",Name=\"Avatar of Hakkar\",Story=\"Hakkar was notorious for demanding sacrifices from his followers. Many millennia ago, he instructed the Atal'ai to bring for this avatar, using blood ritually drained from living victims to feed him. The Atal'ai priests now seek to raise Hakkar's avatar with a modified version of this ritual, one that involves sacrificing green dragons. If the Atal'ai succeed, the re-emergence of Hakkar's avatar could spell doom for Azeroth.\",Portrait=M..\"dungeons\\\\st\\\\avatar-portrait\",Frame=M..\"dungeons\\\\st\\\\avatar-frame\",MapCoordinateX=24.2,MapCoordinateY=45.5,L=\"10838:17,10842:17,10843:17,10844:17,10845:17,10846:17,51217:5,12462:2,70226:2\"},\n}}\nZLDB.DG[\"STOCKADES\"]={\nName=\"The Stockade\",\nStory=\"The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free. Warden Thelwater has managed to escape the holding area and is currently enlisting brave thrill-seekers to venture into the prison and kill the uprising's mastermind - the cunning felon, Bazil Thredd.\",\nBackground=M..\"dungeons\\\\stockades\\\\background\",\nGridBackground=M..\"dungeons\\\\stockades\\\\grid-background\",\nMapId=8,\nIconScale=1,\nMinLevel=23,\nMaxLevel=32,\nEntrances={{MapContinentId=2,MapCoordinateX=50.8,MapCoordinateY=67.6,MapZoneId=28}},\nType=T.Dungeon,\nKey=\"STOCKADES\",\nBosses={\n{Id=\"1696\",Name=\"Targorr the Dread\",Story=\"Targorr the Dread served the Blackrock orcs under Gath'Ilzogg as supreme executioner. His methods were ruthless, even by orcish standards. Men who fought bravely to defend Stormwind were tortured on his whim. Targorr was captured and sent to the Stockade, however due to the corrupt and inefficient legal system he was not executed as his actions so richly deserved. During the uprising in the Stockade, the ruthless orc fell in line with the Defias rioters.\",Portrait=M..\"dungeons\\\\stockades\\\\targorr-portrait\",Frame=M..\"dungeons\\\\stockades\\\\targorr-frame\",MapCoordinateX=50,MapCoordinateY=21.2,Abilities={{Effect=\"Targorr the Dread becomes enraged, increasing his physical damage and attack speed for 2 minutes.\",Flags={F.Heal},Icon=\"Spell_Shadow_UnholyFrenzy\",Id=\"8599\",Name=\"Enrage\"},{Effect=\"Targorr the Dread gains a chance to do two additional attacks.\",Icon=\"Ability_GhoulFrenzy\",Id=\"3417\",Name=\"Thrash\"}},L=\"80721:50,80722:50\"},\n{Id=\"1666\",Name=\"Kam Deepfury\",Story=\"Kam Deepfury, according to Alliance intelligence in Dun Modr, has been determined as the organizer of the explosion that destroyed one of the bridges in the Thandol Span, as well as the death of one of Longbraid the Grim's kin. Unlike most other prisoners in the Stockade, he is not a member of the Defias Brotherhood.\",Portrait=M..\"dungeons\\\\stockades\\\\kam-portrait\",Frame=M..\"dungeons\\\\stockades\\\\kam-frame\",MapCoordinateX=69,MapCoordinateY=30.2,Abilities={{Effect=\"Kam Deepfury assumes a defensive stance, reducing incoming damage.\",Icon=\"Ability_Warrior_DefensiveStance\",Id=\"7164\",Name=\"Defensive Stance\"},{Effect=\"Kam Deepfury slams his shield against an enemy, dealing damage and stunning them for 2 seconds.\",Icon=\"Ability_Warrior_ShieldBash\",Id=\"8242\",Name=\"Shield Slam\"},{Effect=\"Kam Deepfury raises his shield, reducing all incoming damage by 60% for 12 seconds.\",Icon=\"Ability_Warrior_ShieldWall\",Id=\"871\",Name=\"Shield Wall\"}},L=\"80723:90,2280:1\"},\n{Id=\"1717\",Name=\"Hamhock\",Story=\"Some rumors spread throughout Stormwind that Hamhock was a captured ogre from Duskwood, possibly making him a Splinter Fist Ogre. If this were true, he would fall under the possible command of Zzarc'Vul, leader of the clan at Vul'Gol Ogre Mound. Alternatively, he could be a captured member of the Defias Brotherhood.\",Portrait=M..\"dungeons\\\\stockades\\\\hamhock-portrait\",Frame=M..\"dungeons\\\\stockades\\\\hamhock-frame\",MapCoordinateX=78.2,MapCoordinateY=45.8,Abilities={{Effect=\"Hamhock is taken by bloodlust, increasing him and his allies' attack speed by 30% for 30 seconds.\",Flags={F.Heal},Icon=\"Spell_Nature_BloodLust\",Id=\"6742\",Name=\"Bloodlust\"},{Effect=\"Hamhock casts a lightning bolt at an enemy, jumping to two other targets and dealing 190 to 220 nature damage to each.\",Flags={F.Heal,F.Interruptible,F.Important},Icon=\"Spell_Nature_ChainLightning\",Id=\"421\",Name=\"Chain Lightning\"}},L=\"80724:50,80725:50\"},\n{Id=\"1716\",Name=\"Bazil Thredd\",Story=\"Bazil Thredd is the lieutenant and most trusted assistant of Edwin VanCleef. He was caught during the riots leading to the death of Queen Tiffin and imprisoned, later taking lead over the bandits of the Defias Brotherhood in the Stockade.\",Portrait=M..\"dungeons\\\\stockades\\\\bazil-portrait\",Frame=M..\"dungeons\\\\stockades\\\\bazil-frame\",MapCoordinateX=85.8,MapCoordinateY=51.6,Abilities={{Effect=\"Bazil Thredd shouts, empowering him and other allies granting them extra melee attack power for 2 minutes.\",Icon=\"Ability_Warrior_BattleShout\",Id=\"9128\",Name=\"Battle Shout\"},{Effect=\"Bazil Thredd throws a smoke bomb, stunning all nearby enemies for 4 seconds.\",Flags={F.Important},Icon=\"Ability_Hibernation\",Id=\"7964\",Name=\"Smoke Bomb\"}},L=\"80729:35,80730:35,80731:30\"},\n{Id=\"1720\",Name=\"Bruegal Ironknuckle\",Story=\"An elusive dwarf, rarely seen among the general incarcerated population of Stormwind's Stockades. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\stockades\\\\bruegal-portrait\",Frame=M..\"dungeons\\\\stockades\\\\bruegal-frame\",MapCoordinateX=31.1,MapCoordinateY=41.9,IsRare=true,L=\"2941:33,2942:33,3228:33\"},\n{Id=\"1663\",Name=\"Dextren Ward\",Story=\"Ward had been caught stealing bodies from Raven Hill Cemetery and selling them to Morbent Fel, a crime that ultimately led to his capture and grim notoriety.\",Portrait=M..\"dungeons\\\\stockades\\\\dextren-portrait\",Frame=M..\"dungeons\\\\stockades\\\\dextren-frame\",MapCoordinateX=14.4,MapCoordinateY=20.9,Abilities={{Effect=\"Dextren Ward shouts at nearby enemies, causing them to flee in fear for 6 seconds.\\\n\\\nMake sure to clear the rooms around the encounter or you might accidentally overpull while feared!\",Flags={F.Important},Icon=\"Ability_GolemThunderClap\",Id=\"5246\",Name=\"Frightening Shout\"},{Effect=\"Dextren Ward strikes his target for additional physical damage.\",Icon=\"Ability_Rogue_Ambush\",Id=\"11976\",Name=\"Strike\"}},L=\"80726:35,80727:35,80728:30\"},\n}}\nZLDB.DG[\"STRAT\"]={\nName=\"Stratholme\",\nStory=\"Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the dreaded plague of undeath. Arthas' downward spiral and ultimate surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge -- led by the powerful lich, Kel'Thuzad. A contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan, also holds a portion of the ravaged city. The two sides are locked in constant, violent combat. Those adventurers brave (or foolish) enough to enter Stratholme will be forced to contend with both factions before long. It is said that the city is guarded by three massive watchtowers, as well as powerful necromancers, banshees and abominations. There have also been reports of a malefic Death Knight riding atop an unholy steed, dispensing indiscriminate wrath on all those who venture within the realm of the Scourge.\",\nBackground=M..\"dungeons\\\\strat\\\\background\",\nGridBackground=M..\"dungeons\\\\strat\\\\grid-background\",\nMapId=27,\nIconScale=0.7,\nMinLevel=58,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=30.8,MapCoordinateY=14.8,MapZoneId=12},{MapContinentId=2,MapCoordinateX=47.7,MapCoordinateY=23.4,MapZoneId=12}},\nType=T.Dungeon,\nKey=\"STRAT\",\nBosses={\n{Id=\"10393\",Name=\"Skul\",Story=\"An elusive skeletal mage, rarely seen among the general population of Stratholme. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\strat\\\\skul-portrait\",Frame=M..\"dungeons\\\\strat\\\\skul-frame\",MapCoordinateX=56.4,MapCoordinateY=84.9,IsRare=true,L=\"13395:33,13394:33,13396:33,70226:2\"},\n{Id=\"10558\",Name=\"Hearthsinger Forresten\",Story=\"The Culling of Stratholme claimed the lives of innumerable people whose only crime was being in the doomed city. A traveling singer and piccolo player named Forresten was one such victim. He continues to wander the city in death, unable to accept his tragic fate.\",Portrait=M..\"dungeons\\\\strat\\\\hearthsinger-portrait\",Frame=M..\"dungeons\\\\strat\\\\hearthsinger-frame\",MapCoordinateX=72.5,MapCoordinateY=66,IsRare=true,L=\"13378:20,13379:20,13383:20,13384:20,16682:20,70226:2\"},\n{Id=\"10516\",Name=\"The Unforgiven\",Story=\"Lylia was a blade of righteousness among her people. After Arthas commanded his forces to purge the city, her sanity was ripped apart from seeing countless innocents die by her hand. She fell on her sword to escape the madness around her, and she now exists as a spectral being forever denied absolution for her heinous acts.\",Portrait=M..\"dungeons\\\\strat\\\\unforgiven-portrait\",Frame=M..\"dungeons\\\\strat\\\\unforgiven-frame\",MapCoordinateX=66.6,MapCoordinateY=57,L=\"13404:20,13405:20,13408:20,13409:20,16717:20,51217:5,70226:2\"},\n{Id=\"10808\",Name=\"Timmy the Cruel\",Story=\"Timmison was infamous for his savagery on the field of battle. Some speculate his sadism stemmed from the ceaseless bullying he endured as a child. Now reborn as a Scourge monstrosity, his mind shattered, he is tormented by those memories, causing him to answer to the name he once loathed: Timmy.\",Portrait=M..\"dungeons\\\\strat\\\\timmy-portrait\",Frame=M..\"dungeons\\\\strat\\\\timmy-frame\",MapCoordinateX=46,MapCoordinateY=67.5,L=\"13400:20,13401:20,13402:20,13403:20,16724:20,51217:5,70226:2\"},\n{Id=\"11032\",Name=\"Malor the Zealous\",Story=\"A crazed member of the Scarlet Crusade, he guards his own strongbox and won't let anyone near it.\",Portrait=M..\"dungeons\\\\strat\\\\malor-portrait\",Frame=M..\"dungeons\\\\strat\\\\malor-frame\",MapCoordinateX=40.9,MapCoordinateY=69.2,L=\"81016:11,81017:11,81018:11,81019:11,81122:11,81123:11,81124:11,81125:11,81131:11,83575:10,51217:5,70226:2\"},\n{Id=\"11120\",Name=\"Crimson Hammersmith\",Story=\"A hammersmith from the Crimson Legion. Not much is known about him, other than he is very protective of his blacksmithing plans.\",Portrait=M..\"dungeons\\\\strat\\\\hammersmith-portrait\",Frame=M..\"dungeons\\\\strat\\\\hammersmith-frame\",MapCoordinateX=29.8,MapCoordinateY=73.5,L=\"18781:40,124:6\"},\n{Id=\"10997\",Name=\"Cannon Master Willey\",Story=\"The chief cannoneer of the Scarlet Crusade, Willey will use his cannons no matter the circumstance.\",Portrait=M..\"dungeons\\\\strat\\\\willey-portrait\",Frame=M..\"dungeons\\\\strat\\\\willey-frame\",MapCoordinateX=25.4,MapCoordinateY=75.6,L=\"13380:10,13381:10,13382:10,16708:10,18721:10,22403:10,22404:10,22405:10,22406:10,22407:10,12839:6,51217:5,70226:2\"},\n{Id=\"10811\",Name=\"Archivist Galford\",Story=\"Archivist Galford guards the archives of the Scarlet Bastion in Stratholme.\",Portrait=M..\"dungeons\\\\strat\\\\galford-portrait\",Frame=M..\"dungeons\\\\strat\\\\galford-frame\",MapCoordinateX=38.2,MapCoordinateY=89.2,L=\"13385:20,13386:20,13387:20,16692:20,18716:20,22897:14,70226:2,51217:5\"},\n{Id=\"10812\",Name=\"Grand Crusader Dathrohan\",Story=\"The Grand Crusader of the Scarlet Crusade, Saidan Dathrohan give orders from the Scarlet Bastion in Stratholme. Rumors spread about him, putting into question his true intents and even his identity...\",Portrait=M..\"dungeons\\\\strat\\\\dathrohan-portrait\",Frame=M..\"dungeons\\\\strat\\\\dathrohan-frame\",MapCoordinateX=35.1,MapCoordinateY=93.4,L=\"51217:100,83501:17,83502:17,83504:17,83505:17,83503:17,83506:17,12103:10,13348:10,13358:10,13359:10,13360:10,13369:10,16725:10,18717:10,18718:10,18720:10,47413:10,47415:10,14512:6,83500:5,13520:3,70226:3,13353:2\"},\n{Id=\"10435\",Name=\"Magistrate Barthilas\",Story=\"Barthilas was among those innocents purged by Arthas and his forces during the Culling of Stratholme. The Lich King eventually raised the former magistrate from the grave and commanded the hulking undead monstrosity to guard his ruined home.\",Portrait=M..\"dungeons\\\\strat\\\\barthilas-portrait\",Frame=M..\"dungeons\\\\strat\\\\barthilas-frame\",MapCoordinateX=81.6,MapCoordinateY=62.5,L=\"12382:100,13376:17,18722:17,18725:17,18726:17,18727:17,23198:17,51217:5,70226:2\"},\n{Id=\"10809\",Name=\"Stonespine\",Story=\"An elusive gargoyle, rarely seen among the general population of Stratholme. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\strat\\\\stonespine-portrait\",Frame=M..\"dungeons\\\\strat\\\\stonespine-frame\",MapCoordinateX=83.5,MapCoordinateY=43,IsRare=true,L=\"13397:33,13399:33,13954:33,70226:2\"},\n{Id=\"10437\",Name=\"Nerub'enkan\",Story=\"Nerub'enkan was a fearsome warrior during the War of the Spider. Ultimately, she succumbed to her wounds and was raised into undeath as an obedient minion of the Scourge. Now the nerubian guards a ziggurat in Stratholme as fiercely as she defended her home in life.\",Portrait=M..\"dungeons\\\\strat\\\\nerubenkan-portrait\",Frame=M..\"dungeons\\\\strat\\\\nerubenkan-frame\",MapCoordinateX=75.7,MapCoordinateY=38.2,L=\"51217:5,13530:20,13531:20,13532:20,13533:20,13529:20,16675:20,18738:20,18739:20,18740:20,70226:2\"},\n{Id=\"10436\",Name=\"Baroness Anastari\",Story=\"While she lived, Anastari took what she wanted, no matter the cost. Death has done little to change that. Her soul ripped from her body, Anastari became a banshee, and she has abandoned her love of material trinkets in favor of possessions of a far more sinister kind.\",Portrait=M..\"dungeons\\\\strat\\\\anastari-portrait\",Frame=M..\"dungeons\\\\strat\\\\anastari-frame\",MapCoordinateX=90.2,MapCoordinateY=39,L=\"70226:2,13535:20,13537:20,13538:20,13539:20,13534:20,16704:20,18728:20,18729:20,18730:20,51217:5\"},\n{Id=\"10438\",Name=\"Maleki the Pallid\",Story=\"Maleki was among the first to join the Cult of the Damned, showing tremendous aptitude in harnessing the chill of the grave. Driven by an insatiable desire for power, the mage fervently hones his skills in dark magic to prepare for when he will be remade as a lich.\",Portrait=M..\"dungeons\\\\strat\\\\maleki-portrait\",Frame=M..\"dungeons\\\\strat\\\\maleki-frame\",MapCoordinateX=84.4,MapCoordinateY=17.4,L=\"13525:20,13526:20,13527:20,13528:20,13524:20,16691:20,18734:20,18735:20,18737:20,12833:6,51217:5,70226:2\"},\n{Id=\"10439\",Name=\"Ramstein the Gorger\",Story=\"Ramstein is one of the Scourge's most infamous abominations, a horror stitched together from numerous corpses and empowered by a ceaseless hunger. This monster committed unspeakable atrocities on countless innocent souls when Scourge forces overran Stratholme.\",Portrait=M..\"dungeons\\\\strat\\\\ramstein-portrait\",Frame=M..\"dungeons\\\\strat\\\\ramstein-frame\",MapCoordinateX=65.5,MapCoordinateY=16.2,L=\"13372:14,13373:14,13374:14,13375:14,13515:14,16737:14,18723:14,51217:5,70226:2\"},\n{Id=\"10440\",Name=\"Baron Rivendare\",Story=\"Baron Rivendare is a powerful death knight in the service of the Lich King, coordinating the efforts of the Scourge in the Plaguelands. Ruling over the city of Stratholme, he currently battles with agents of the Argent Dawn sent to Stratholme to kill him.\",Portrait=M..\"dungeons\\\\strat\\\\rivendare-portrait\",Frame=M..\"dungeons\\\\strat\\\\rivendare-frame\",MapCoordinateX=60.2,MapCoordinateY=16.6,L=\"51217:100,22408:20,22409:20,22410:20,22411:20,22412:20,13340:14,13344:14,13345:14,13346:14,13349:14,13361:14,13368:14,16668:11,16678:11,16687:11,16694:11,16699:11,16709:11,16719:11,16732:11,16728:11,47413:10,47415:10,70226:3,13505:1,13335:1\"},\n}}\nZLDB.DG[\"SV\"]={\nName=\"Stormwind Vault\",\nStory=\"The Stormwind Vault was built to hold the kingdom's most dangerous criminals and magical threats. At its heart lies Arc'Tiras, a powerful crystal that has driven the guards mad and corrupted the Runic Constructs meant to patrol its halls. Now, the Vault is a maze of chaos...\",\nBackground=M..\"dungeons\\\\sv\\\\background\",\nGridBackground=M..\"dungeons\\\\sv\\\\grid-background\",\nMapId=37,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=62.8,MapCoordinateY=58.6,MapZoneId=28},{MapContinentId=2,MapCoordinateX=29.4,MapCoordinateY=61.8,MapZoneId=13}},\nType=T.Dungeon,\nKey=\"SV\",\nBosses={\n{Id=\"80853\",Name=\"Aszosh Grimflame\",Story=\"Aszosh Grimflame was once a necrolyte of the Shadow Council, raised as a death knight by Gul'dan. Now he commands the bones of the fallen and drains the strength of all who oppose him. His dark presence has twisted the Vault's halls, and only the brave can hope to stop his relentless hunger for power.\",Portrait=M..\"dungeons\\\\sv\\\\aszosh-portrait\",Frame=M..\"dungeons\\\\sv\\\\aszosh-frame\",MapCoordinateX=37.7,MapCoordinateY=38.5,Abilities={{Effect=\"Aszosh Grimflame launches arcane missiles at the enemy, causing 192 arcane damage every 1 second for 5 seconds.\",Icon=\"Spell_Nature_StarFall\",Id=\"10212\",Name=\"Arcane Missiles\"},{Effect=\"Aszosh Grimflame curses his enemy, reducing their strength and stamina by 50 for 60 seconds.\",Flags={F.Curse},Icon=\"Spell_Shadow_AntiShadow\",Id=\"18702\",Name=\"Curse of the Darkmaster\"}},L=\"60504:17,60418:17,60419:17,60425:17,60431:17,60434:17,51217:5,70226:1\"},\n{Id=\"80852\",Name=\"Tham'Grarr\",Story=\"Not much is known about Tham'Grarr, other than he is a fearsome ogre, known for his brutal strength and violent temper.\",Portrait=M..\"dungeons\\\\sv\\\\tham-portrait\",Frame=M..\"dungeons\\\\sv\\\\tham-frame\",MapCoordinateX=68.6,MapCoordinateY=90.1,Abilities={{Effect=\"Tham'Grarr shouts at nearby enemies, causing them to flee in fear for 8 seconds.\",Flags={F.Important},Icon=\"Ability_GolemThunderClap\",Id=\"5246\",Name=\"Intimidating Shout\"},{Effect=\"Tham'Grarr inflicts heavy damage on his target and leaves them wounded, reducing the effectiveness of any healing by 50% for 5 seconds.\",Flags={F.Heal},Icon=\"Ability_Warrior_SavageBlow\",Id=\"22859\",Name=\"Mortal Cleave\"},{Effect=\"Tham'Grarr counterattacks any enemy that strikes him in melee for 15 seconds.\\\n\\\nMelee attacks made from behind cannot be counterattacked.\",Flags={F.DPS,F.Important},Icon=\"Ability_Warrior_Challange\",Id=\"22857\",Name=\"Retaliation\"}},L=\"60502:17,60415:17,60416:17,60417:17,60424:17,60435:17,51217:5,70226:1\"},\n{Id=\"80850\",Name=\"Black Bride\",Story=\"The Black Bride is a tragic figure, bound by obsessive love for Damian. She attacks any who come near, seeing them as defilers of her devotion, and speaks of her love for The Ripper even in death.\",Portrait=M..\"dungeons\\\\sv\\\\bride-portrait\",Frame=M..\"dungeons\\\\sv\\\\bride-frame\",MapCoordinateX=55.9,MapCoordinateY=10.8,Abilities={{Effect=\"The Black Bride curses nearby enemies, reducing their chance to hit by 10% for 12 seconds.\",Flags={F.Curse},Icon=\"Spell_Nature_Drowsy\",Id=\"16867\",Name=\"Banshee Curse\"},{Effect=\"The Black Bride wails with anguish, inflicting shadow damage to an enemy.\",Icon=\"Spell_Shadow_ShadowBolt\",Id=\"16565\",Name=\"Banshee Wail\"},{Effect=\"The Black Bride takes control of one of her enemies, and start attacking their allies!\\\n\\\nDealing enough damage to the possessed player will free them from the bride!\",Flags={F.Important},Icon=\"Spell_Shadow_Charm\",Id=\"17244\",Name=\"Possess\"},{Effect=\"The Black Bride silences all enemies in a 10 yards radius, preventing them from casting spells for 10 seconds.\",Flags={F.Magic},Icon=\"Spell_Holy_Silence\",Id=\"18327\",Name=\"Silence\"}},L=\"60408:20,60409:20,60410:20,60411:20,60436:17,51217:5,70226:1\"},\n{Id=\"80851\",Name=\"Volkan Cruelblade\",Story=\"Volkan Cruelblade is a member of the Burning Blade clan. He fights with deadly skill, seeking freedom and vengeance against all who oppose him.\",Portrait=M..\"dungeons\\\\sv\\\\volkan-portrait\",Frame=M..\"dungeons\\\\sv\\\\volkan-frame\",MapCoordinateX=71.6,MapCoordinateY=43.1,MapIsBelow=true,Abilities={{Effect=\"Volkan puts nearby enemies to sleep for 10 seconds.\\\n\\\nAny damage caused will awaken them.\",Flags={F.Important},Icon=\"Spell_Nature_Sleep\",Id=\"9256\",Name=\"Deep Sleep\"},{Effect=\"Volkan lets out a psychic scream, causing an enemy to be frozen in fear for 8 seconds.\",Flags={F.Important},Icon=\"Spell_Shadow_PsychicScream\",Id=\"15398\",Name=\"Psychic Scream\"},{Effect=\"Volkan hurls missiles of dark magic, inflicting 255 shadow damage to each enemy within 30 yards.\",Flags={F.Heal},Icon=\"Spell_Shadow_ShadowBolt\",Id=\"20741\",Name=\"Shadow Bolt Volley\"},{Effect=\"Volkan lashes enemies in a 20 yards radius with dark magic, inflicting 740 shadow damage to each of them.\",Flags={F.Heal},Icon=\"Spell_Shadow_ShadowBolt\",Id=\"20603\",Name=\"Shadow Shock\"}},L=\"60412:20,60413:20,60414:20,60432:20,60503:20,51217:5,70226:1\"},\n{Id=\"80854\",Name=\"Damian\",Story=\"Damian, also known as The Ripper, is a deadly and elusive killer who strikes from the shadows. He delights in combat, hunting those who cross his path with ruthless precision, and vanishes as easily as he appears.\",Portrait=M..\"dungeons\\\\sv\\\\damian-portrait\",Frame=M..\"dungeons\\\\sv\\\\damian-frame\",MapCoordinateX=46.5,MapCoordinateY=43.4,Abilities={{Effect=\"Damian drains the life from an enemy, transferring 70 health to himself every second for 5 seconds.\",Flags={F.Interruptible},Icon=\"Spell_Shadow_LifeDrain02\",Id=\"11700\",Name=\"Drain Life\"},{Effect=\"Damian immolates an enemy, burning them for 258 fire damage and an additional 485 fire damage over 15 seconds.\",Flags={F.Heal,F.Magic},Icon=\"Spell_Fire_Immolation\",Id=\"11668\",Name=\"Immolate\"},{Effect=\"Damian vanishes, ambushing an enemy when he reappears.\",Icon=\"Ability_Vanish\",Id=\"1856\",Name=\"Vanish\"}},L=\"60421:20,60423:20,60427:20,60433:20,60500:20,60422:1,51217:5,70226:1\"},\n{Id=\"93107\",Name=\"Arc'Tiras\",Story=\"Arc'Tiras is a powerful and sentient crystal of magic, locked deep within the Stormwind Vault. Its unstable energy has driven the guards mad and twisted the Vault into a maze of madness.\",Portrait=M..\"dungeons\\\\sv\\\\arc-portrait\",Frame=M..\"dungeons\\\\sv\\\\arc-frame\",MapCoordinateX=46.4,MapCoordinateY=79.3,L=\"40003:25,60501:25,60505:25,60506:25,60420:25,60426:25,60429:25,60430:25,51217:80,83570:15\"},\n}}\nZLDB.DG[\"SWR\"]={\nName=\"Stormwrought Ruins\",\nStory=\"The island of Balor was once a bustling merchant paradise, governed by the Balor family as a prosperous vessel state of Stormwind. This era of trade and tranquility ended during the Second War when the Stormreaver orcs and the Shadow Council brought depravity to its shores. Today, the once-resplendent castle sits in ruins atop the cliffs, haunted by the spirits of those tethered to their former home by demonic cruelty. While SI:7 and goblin scavengers pick through the rubble for lost antiquities, the Shadow Council conducts vile experiments within the depths, threatening to anchor the isle in eternal darkness.\",\nBackground=M..\"dungeons\\\\swr\\\\background\",\nGridBackground=M..\"dungeons\\\\swr\\\\grid-background\",\nMapId=42,\nIconScale=0.6,\nMinLevel=32,\nMaxLevel=44,\nEntrances={{MapContinentId=2,MapCoordinateX=57.1,MapCoordinateY=60.1,MapZoneId=5},{MapContinentId=2,MapCoordinateX=56.2,MapCoordinateY=84.9,MapZoneId=5}},\nType=T.Dungeon,\nKey=\"SWR\",\nBosses={\n{Id=\"62548\",Name=\"Oronok Torn-Heart\",Story=\"As one of Gul'dan's most capable lieutenants, Oronok was entrusted with the Pendant of Uth'okk, a gemstone of immense power. He currently lurks within the depths of the ruins, overseeing the new uprising of the Shadow Council. His presence is a reminder of the Old Horde's hatred, and he remains a primary target for those seeking to reclaim the power of the pendant for the Horde.\",Portrait=M..\"dungeons\\\\swr\\\\oronok-portrait\",Frame=M..\"dungeons\\\\swr\\\\oronok-frame\",MapCoordinateX=45.1,MapCoordinateY=25.7,L=\"58135:25,58136:25,58137:25,58177:25\"},\n{Id=\"62547\",Name=\"Dagar the Glutton\",Story=\"Dagar is a despicable being whose history of malice stretches back to the formation of the Shadow Council. A fanatical follower of Gul'dan's legacy, his hatred burns like the lava pools of Blackrock Mountain. He stands as a brutal enforcer within the castle, guarding the occupied halls against any who would disrupt the Council's work.\",Portrait=M..\"dungeons\\\\swr\\\\dagar-portrait\",Frame=M..\"dungeons\\\\swr\\\\dagar-frame\",MapCoordinateX=50.5,MapCoordinateY=27,L=\"58130:25,58132:25,58133:25,58176:25\"},\n{Id=\"62552\",Name=\"Librarian Theodorus\",Story=\"The Balor family amassed a sheer unimaginable amount of knowledge in their library over decades of successful trade. Theodorus serves as the current guardian of these dusty tomes, including the hidden practices of trade authored by Sir Walton Balor. He ensures that the secrets of Balorian commerce do not fall into the hands of Stormwind's spies.\",Portrait=M..\"dungeons\\\\swr\\\\theodorus-portrait\",Frame=M..\"dungeons\\\\swr\\\\theodorus-frame\",MapCoordinateX=47.4,MapCoordinateY=35.9,L=\"58138:25,58139:25,58140:25,58141:25\"},\n{Id=\"62549\",Name=\"Duke Balor the IV\",Story=\"The scions of the Balor family reigned over their island with watchful eyes and merciful souls until the castle was cursed. Though the Duke's bones may have turned to ash, his presence remains tied to the throne room. He is a tragic figure of a fallen merchant legacy, his sigil ring and crown serving as the last remaining physical proof of his family's former sovereignty.\",Portrait=M..\"dungeons\\\\swr\\\\balor-portrait\",Frame=M..\"dungeons\\\\swr\\\\balor-frame\",MapCoordinateX=50.4,MapCoordinateY=39.5,L=\"58145:25,58144:25,58143:25,58142:25\"},\n{Id=\"62551\",Name=\"Chieftain Stormsong\",Story=\"Chieftain Stormsong is a critical figurehead in the Stormreaver chain of command, acting as a 'head of the hydra' for the occupation. He oversees the orcish forces within the ruins, coordinating with the Shadow Council to ensure their resurgence remains unchallenged. Liquidating him is essential to breaking the orcish grip on the castle courtyard.\",Portrait=M..\"dungeons\\\\swr\\\\stormsong-portrait\",Frame=M..\"dungeons\\\\swr\\\\stormsong-frame\",MapCoordinateX=39.5,MapCoordinateY=47.9,L=\"75:6,58149:25,58148:25,58147:25,58146:25\"},\n{Id=\"62550\",Name=\"Deathlord Tidebane\",Story=\"Barbaros, captain of the Bilgerats, sailed to the cursed isle of Balor chasing stolen secrets and the promise of buried treasure. His greed proved fatal — ambushed by the Stormreaver orcs, he was dragged to Stormwrought Castle and put to the sword. Yet death was not the end. The dark powers enthroned within those halls seized his corpse and bound the soul of a death knight into his flesh, giving rise to Deathlord Tidebane. The captain who once commanded the seas now serves as a vessel of undying darkness, forever imprisoned within the ruins he sought to plunder.\",Portrait=M..\"dungeons\\\\swr\\\\tidebane-portrait\",Frame=M..\"dungeons\\\\swr\\\\tidebane-frame\",MapCoordinateX=32.7,MapCoordinateY=66.9,L=\"58150:25,58151:25,58152:25,58153:25,24:6,58276:1,70:6,950:1\"},\n{Id=\"62652\",Name=\"Subjugator Halthas Shadecrest\",Story=\"Aside from his established presence within the ruins of Stormwrought Castle, very little is known about the past or the specific motives of Subjugator Halthas Shadecrest.\",Portrait=M..\"dungeons\\\\swr\\\\halthas-portrait\",Frame=M..\"dungeons\\\\swr\\\\halthas-frame\",MapCoordinateX=32.8,MapCoordinateY=91.9,L=\"58183:25,58184:25,58185:25,58186:25,83:6\"},\n{Id=\"62664\",Name=\"Mycellakos\",Story=\"Mycellakos is a massive, living fungus that originated from a source of contamination deep beneath the ruined castle. Its core radiates a dark, twisted magic that has brought the surrounding fungi into a state of unnatural life. As the primary infector of the isle, it must be purged to stop the spread of its necrotic tissue.\",Portrait=M..\"dungeons\\\\swr\\\\mycellakos-portrait\",Frame=M..\"dungeons\\\\swr\\\\mycellakos-frame\",MapCoordinateX=23.9,MapCoordinateY=38.3,L=\"58179:25,58180:25,58181:25,58182:25\"},\n{Id=\"62661\",Name=\"Eldermaw the Primordial\",Story=\"The primordial beast known as Eldermaw remains an enigma to scholars, with no documentation existing to explain its habitation within the Stormwrought Ruins.\",Portrait=M..\"dungeons\\\\swr\\\\eldermaw-portrait\",Frame=M..\"dungeons\\\\swr\\\\eldermaw-frame\",MapCoordinateX=22.5,MapCoordinateY=25.7,L=\"58190:25,58189:25,58188:25,58187:25\"},\n{Id=\"62665\",Name=\"Lady Drazare\",Story=\"Historical accounts are silent regarding Lady Drazare; she is recognized solely as one of the powerful entities dwelling within the ruins of Balor.\",Portrait=M..\"dungeons\\\\swr\\\\drazare-portrait\",Frame=M..\"dungeons\\\\swr\\\\drazare-frame\",MapCoordinateX=30.7,MapCoordinateY=19.3,L=\"58194:25,58193:25,58192:25,58191:25\"},\n{Id=\"62670\",Name=\"Remains of the Innocent\",Story=\"This haunting abomination was born from the cruel intent of the Shadow Council, manifesting as a mass of tormented young souls. O'jin and other sensitive spirits can hear the cries of these poor children, who were used as raw materials for the Council's vile experiments. Only by slaying this abomination can the innocent souls finally be set free.\",Portrait=M..\"dungeons\\\\swr\\\\remains-portrait\",Frame=M..\"dungeons\\\\swr\\\\remains-frame\",MapCoordinateX=26.4,MapCoordinateY=10.2,L=\"58195:25,58196:25,58197:25,58198:25\"},\n{Id=\"62673\",Name=\"Ighal'for\",Story=\"A high-ranking and powerful warlock of the Shadow Council, Ighal'for is a disciple of the deranged Cho'gall. He wields a broken Bloodstone Pendant to channel void energies and summon aberrations from beyond the Nether. His fanatical devotion to his demon overlords makes him the primary architect of the horrors currently unfolding within the castle.\",Portrait=M..\"dungeons\\\\swr\\\\mergothid-portrait\",Frame=M..\"dungeons\\\\swr\\\\mergothid-frame\",MapCoordinateX=30.7,MapCoordinateY=5.9,L=\"58199:1,58204:20,58203:20,58202:20,58201:20,58200:20\"},\n}}\nZLDB.DG[\"UBRS\"]={\nName=\"Upper Blackrock Spire\",\nStory=\"The history of this imposing fortress is long and complex. Carved into the fiery core of Blackrock Mountain by the Dark Iron clan centuries ago, and eventually taken by the black dragon Nefarian and his brood, the upper reaches of Blackrock Spire are now home to the Ironmarch vanguard. As preparations to use the Spire as the staging ground for a full-scale invasion of Azeroth continue, the Iron Horde has set up a terrifying contingency plan: a doomsday weapon within the heart of Blackrock Mountain.\",\nBackground=M..\"dungeons\\\\ubrs\\\\background\",\nGridBackground=M..\"dungeons\\\\ubrs\\\\grid-background\",\nMapId=17,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=79,MapCoordinateY=33,MapZoneId=6}},\nType=T.Dungeon,\nKey=\"UBRS\",\nBosses={\n{Id=\"9816\",Name=\"Pyroguard Emberseer\",Story=\"Long ago, Pyroguard Emberseer, a loyal minion of the mighty Ragnaros the Firelord, incinerated dozens of Blackrock orcs during a climactic battle at the Burning Steppes. Ultimately Emberseer was defeated and imprisoned within Blackrock Mountain, where his potent energy is now siphoned for use in accelerating the incubation of Nefarian's black dragon eggs.\",Portrait=M..\"dungeons\\\\ubrs\\\\pyroguard-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\pyroguard-frame\",L=\"58199:1,58204:20,58203:20,58202:20,58201:20,58200:20,12905:20,12926:20,12927:20,12929:20,16672:20,23320:8,51217:5,70226:2\"},\n{Id=\"10264\",Name=\"Solakar Flamewreath\",Story=\"Gaining favor within the black dragonflight is a mixed blessing. Solakar Flamewreath is entrusted with the care of Nefarian's dragonspawn, but he has been warned he will pay a terrible price for any whelp that dies under his supervision--or simply fails to live up to expectations.\",Portrait=M..\"dungeons\\\\ubrs\\\\solakar-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\solakar-frame\",L=\"12589:20,12603:20,12606:20,12609:20,16695:20,18657:6,51217:5,70226:2\"},\n{Id=\"10509\",Name=\"Jed Runewatcher\",Story=\"An elusive orc, rarely seen among the general population of Upper Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\ubrs\\\\jed-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\jed-frame\",IsRare=true,L=\"12604:33,12605:33,12930:33,70226:2\"},\n{Id=\"10899\",Name=\"Goraluk Anvilcrack\",Story=\"Goraluk Anvilcrack is a renowned blacksmith. Unfortunately, he sold his soul to the satyr Lorax, but broke the deal and ran away to Upper Blackrock Spire with a rune covered breastplate.\",Portrait=M..\"dungeons\\\\ubrs\\\\goraluk-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\goraluk-frame\",L=\"18779:15,12728:14,12834:14,12837:14,13498:14,13502:14,18047:14,18048:14,70226:2\"},\n{Id=\"10429\",Name=\"Warchief Rend Blackhand\",Story=\"After the Horde was defeated in the Second War, Rend Blackhand, son of the first warchief, brought the remnants of his clan to Blackrock Spire and fought the Dark Iron dwarves for possession of the stronghold. Rend allied his orcs with Nefarian and the black dragonflight, who routed the dwarves and expelled them from Blackrock's upper reaches.\",Portrait=M..\"dungeons\\\\ubrs\\\\rend-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\rend-frame\",L=\"12587:23,12935:23,18102:23,18103:23,12588:17,12936:17,16733:17,18104:17,22247:17,12583:8,12940:8,12939:8,51217:5,70226:3,12590:1,12952:20,12953:20,12960:20,16669:20,22225:20,12871:4,13522:3\"},\n{Id=\"10430\",Name=\"The Beast\",Story=\"Nefarian's dragonkin take obscene delight in the barbaric torture of Ragnaros's captured minions. Despite suffering unimaginable agony, one core hound remained lucid enough to be retrained, and his ferocity makes him an ideal guard in the upper levels of Blackrock Spire.\",Portrait=M..\"dungeons\\\\ubrs\\\\beast-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\beast-frame\",L=\"24101:13,12709:10,12963:10,12964:10,12965:10,12966:10,12967:10,12968:10,12969:10,16729:10,22311:10,51217:5,70226:2\"},\n{Id=\"16042\",Name=\"Lord Valthalak\",Story=\"A drakonid noble and a warlock of immense power, Valthalak was the former General of Blackrock Spire before Drakkisath rose to power. He was slain by the Veiled Blade mercenary company for his spellbook, but ended up avenging himself even after his death using his necromantic powers.\",Portrait=M..\"dungeons\\\\ubrs\\\\valthalak-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\valthalak-frame\",L=\"22302:25,22336:25,22339:25,22342:25,22335:25,22337:25,22340:25,22343:25,51217:5\"},\n{Id=\"10363\",Name=\"General Drakkisath\",Story=\"A cunning and ruthless strategist, Drakkisath commands Nefarian's armies in the war with Ragnaros. After securing victories against the Dark Irons, General Drakkisath's forces are positioned to drive the dwarves out of Blackrock Mountain once and for all.\",Portrait=M..\"dungeons\\\\ubrs\\\\drakkisath-portrait\",Frame=M..\"dungeons\\\\ubrs\\\\drakkisath-frame\",L=\"51217:100,22253:25,22267:25,22268:25,22269:25,12602:25,13098:25,13141:25,13142:25,16666:11,16674:11,16688:11,16690:11,16700:11,16706:11,16721:11,16726:11,16730:11,13090:10,47413:10,47415:10,15730:4,70226:3,13519:3,12592:1\"},\n}}\nZLDB.DG[\"ULDA\"]={\nName=\"Uldaman\",\nStory=\"Uldaman is an ancient Titan vault that has laid buried deep within the earth since the world's creation. Dwarven excavations have recently penetrated this forgotten city, releasing the Titans' first failed creations: the Troggs. Legends say that the Titans created troggs from stone. When they deemed the experiment a failure, the Titans locked the troggs away and tried again - resulting in the creation of the dwarven race. The secrets of the dwarves' creation are recorded on the fabled Discs of Norgannon - massive Titan artifacts that lie at the very bottom of the ancient city. Recently, the Dark Iron dwarves have launched a series of incursions into Uldaman, hoping to claim the discs for their fiery master, Ragnaros. However, protecting the buried city are several guardians - giant constructs of living stone that crush any hapless intruders they find. The Discs themselves are guarded by a massive, sapient Stonekeeper called Archaedas. Some rumors even suggest that the dwarves' stone-skinned ancestors, the earthen, still dwell deep within the city's hidden recesses.\",\nBackground=M..\"dungeons\\\\ulda\\\\background\",\nGridBackground=M..\"dungeons\\\\ulda\\\\grid-background\",\nMapId=10,\nIconScale=0.8,\nMinLevel=41,\nMaxLevel=50,\nEntrances={{MapContinentId=2,MapCoordinateX=36.8,MapCoordinateY=28.1,MapZoneId=35},{MapContinentId=2,MapCoordinateX=65.5,MapCoordinateY=43.4,MapZoneId=4}},\nType=T.Dungeon,\nKey=\"ULDA\",\nBosses={\n{Id=\"6906\",Name=\"The Lost Dwarves\",Story=\"Seeking fame and, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \\\"clearing a path\\\" unfortunately entailed \\\"getting hopelessly lost in an ancient labyrinth.\\\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.\",Portrait=M..\"dungeons\\\\ulda\\\\dwarves-portrait\",Frame=M..\"dungeons\\\\ulda\\\\dwarves-frame\",MapCoordinateX=58.7,MapCoordinateY=92.2,L=\"9399:100,9401:50,9400:50,9394:50,9398:50,9403:50,9404:50\"},\n{Id=\"6910\",Name=\"Revelosh\",Story=\"Some luminaries in Ironforge's prestigious Explorers' League have theorized an ancestral link between their people and the troggs, and pointed towards the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices. If that is true, the trogg known as Revelosh can be considered the trogg equivalent of an archaeologist, although any historically minded adventurers who encounter him would be more inclined to call him a thief.\",Portrait=M..\"dungeons\\\\ulda\\\\revelosh-portrait\",Frame=M..\"dungeons\\\\ulda\\\\revelosh-frame\",MapCoordinateX=53.2,MapCoordinateY=72.5,L=\"9387:25,9388:25,9389:25,9390:25\"},\n{Id=\"7228\",Name=\"Ironaya\",Story=\"The titans did not construct the Uldaman complex directly but utilized various servants to create its megalithic halls. The Pantheon entrusted the watcher Ironaya with overseeing the construction and maintenance of Uldaman, but as time passed, the once awe-inspiring vault fell to ruin. Within the map chamber, Ironaya has spent millennia in a form of stasis, analyzing the original master plan drawn up by Khaz'goroth and attempting to find a way to restore the complex to its original functionality.\",Portrait=M..\"dungeons\\\\ulda\\\\ironaya-portrait\",Frame=M..\"dungeons\\\\ulda\\\\ironaya-frame\",MapCoordinateX=37,MapCoordinateY=73.8,L=\"9407:33,9408:33,9409:33,51217:1\"},\n{Id=\"7023\",Name=\"Obsidian Sentinel\",Story=\"The Obsidian Sentinel was responsible for guarding Uldaman's secrets until it was affected by corruption by an unknown force. Originally crafted from the same stone as the halls of Uldaman itself, this keeper has had the majority of its body replaced with dark glass capable of reflecting spells. Whatever was responsible for the Obsidian Sentinel's transformation must be incredibly potent, for it is not easy to alter the enchanted stone of a titan construct.\",Portrait=M..\"dungeons\\\\ulda\\\\sentinel-portrait\",Frame=M..\"dungeons\\\\ulda\\\\sentinel-frame\",MapCoordinateX=29.1,MapCoordinateY=60},\n{Id=\"7206\",Name=\"Ancient Stone Keeper\",Story=\"One of many golems that staffed and operated the great titan vault, the Ancient Stone Keeper was part of a small group that served as an intermediary between the watchers left in control of the facility and their many servants. With the corruption of the Obsidian Sentinel, the Ancient Stone Keeper is the last of its kind, performing its duty by protecting the secrets of the titans as best it can until its inevitable shutdown.\",Portrait=M..\"dungeons\\\\ulda\\\\keeper-portrait\",Frame=M..\"dungeons\\\\ulda\\\\keeper-frame\",MapCoordinateX=47.5,MapCoordinateY=44.3,L=\"9410:50,9411:35,80746:15\"},\n{Id=\"7291\",Name=\"Galgann Firehammer\",Story=\"Reacting to the discovery of Uldaman by Bronzebeard dwarves, the Dark Iron clan mounted an invasion of the vault to stop their ancestral foes from accessing the powerful artifacts within. Galgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation of Uldaman so that the emperor may harness the artifacts' destructive potential against the Dark Irons' enemies.\",Portrait=M..\"dungeons\\\\ulda\\\\galgann-portrait\",Frame=M..\"dungeons\\\\ulda\\\\galgann-frame\",MapCoordinateX=26.6,MapCoordinateY=32.6,L=\"11311:25,11310:25,9419:25,9412:25\"},\n{Id=\"4854\",Name=\"Grimlok\",Story=\"In trogg society, the biggest, strongest, and most vicious trogg often becomes chieftain through displays of power. Grimlok is a comparative genius in that he has maintained control of the Stonevault troggs through intimidation and what might be considered crude psychological warfare. Having trained a deadly basilisk, Grimlok uses the threat of petrification by his beast to keep any would-be usurpers in line.\",Portrait=M..\"dungeons\\\\ulda\\\\grimlok-portrait\",Frame=M..\"dungeons\\\\ulda\\\\grimlok-frame\",MapCoordinateX=22.1,MapCoordinateY=26,L=\"9414:33,9415:33,9416:33,51217:1\"},\n{Id=\"2748\",Name=\"Archaedas\",Story=\"Deep within Uldaman is a chamber containing one of the greatest treasures of the titans, created by Norgannon himself. However, thus far no explorers have managed to gain access to the relic, for any attempt at doing so activates the great watcher Archaedas, an immense guardian who easily dispatches treasure seekers through his powerful attacks and a veritable army of servants. Crafted from some of the oldest, strongest stone taken from Uldaman's depths, Archaedas is a foe as formidable as he is ancient.\",Portrait=M..\"dungeons\\\\ulda\\\\archaedas-portrait\",Frame=M..\"dungeons\\\\ulda\\\\archaedas-frame\",MapCoordinateX=41.6,MapCoordinateY=16.6,MapIsBelow=true,L=\"9413:33,9418:33,11118:33,51217:5\"},\n}}\nZLDB.DG[\"WC\"]={\nName=\"Wailing Caverns\",\nStory=\"Years ago, the famed druid Naralex and his followers descended into the shadowy Wailing Caverns, named for the mournful cry one hears when steam bursts from the cave system's fissures. Naralex planned to use the underground springs to restore lushness to the arid Barrens. But upon entering the Emerald Dream, he saw his vision of regrowth turn into a waking nightmare, one that has plagued the caverns ever since.\",\nBackground=M..\"dungeons\\\\wc\\\\background\",\nGridBackground=M..\"dungeons\\\\wc\\\\grid-background\",\nMapId=18,\nIconScale=0.9,\nMinLevel=16,\nMaxLevel=25,\nEntrances={{MapContinentId=1,MapCoordinateX=54.9,MapCoordinateY=66.7,MapZoneId=33}},\nType=T.Dungeon,\nKey=\"WC\",\nBosses={\n{Id=\"3653\",Name=\"Kresh\",Story=\"An ancient resident of the Wailing Caverns, this giant turtle wanders the underground caves, his resilient mind unaffected by Naralex's relentless nightmares. Don't be fooled by his happy disposition; Kresh has thwarted many adventurers who longed to steal his massive shell\",Portrait=M..\"dungeons\\\\wc\\\\kresh-portrait\",Frame=M..\"dungeons\\\\wc\\\\kresh-frame\",MapCoordinateX=44.3,MapCoordinateY=28.5,L=\"13245:33,80710:33,6447:33\"},\n{Id=\"3669\",Name=\"Lord Cobrahn\",Story=\"Jarlaxla's skill at harnessing animal forms earned him renown among the druids of the Cenarion Circle. However, the Wailing Caverns' corruption twisted his unique abilities. Now, Jarlaxla has perfected a deadly serpentine form, renaming himself Cobrahn to reflect his vicious new found power.\",Portrait=M..\"dungeons\\\\wc\\\\cobrahn-portrait\",Frame=M..\"dungeons\\\\wc\\\\cobrahn-frame\",MapCoordinateX=32.5,MapCoordinateY=45.3,L=\"6460:33,6465:33,10410:33\"},\n{Id=\"5912\",Name=\"Deviate Faerie Dragon\",Story=\"An elusive faerie dragon, rarely seen among the denizens of Wailing Caverns. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...\",Portrait=M..\"dungeons\\\\wc\\\\deviate-portrait\",Frame=M..\"dungeons\\\\wc\\\\deviate-frame\",MapCoordinateX=73.7,MapCoordinateY=29.8,IsRare=true,L=\"5243:50,6632:50\"},\n{Id=\"61968\",Name=\"Zandara Windhoof\",Story=\"As slippery as the shadows themselves, the Kolkar centaur found their way into a hidden branch of the Winding Chasm through the narrowest of cracks. Leading this invasion is the zealous Zandara Windhoof, who has audaciously claimed the Wailing Caverns as her own birthright. Her presence is a direct insult to the Earthmother, bringing nothing but destruction to a place already suffering under the weight of Naralex's failed dream.\",Portrait=M..\"dungeons\\\\wc\\\\zandara-portrait\",Frame=M..\"dungeons\\\\wc\\\\zandara-frame\",MapCoordinateX=67,MapCoordinateY=16.7,L=\"55371:50,55369:25,55370:25\"},\n{Id=\"3670\",Name=\"Lord Pythas\",Story=\"A childhood friend of Naralex, the warrior Aryn was a quick study in druidism. Despite his training, the acolyte was defenseless against the corruption that would strip away his sanity. Aryn has taken on the name Pythas, combining his impressive melee prowess with his druidic arsenal to vanquish intruders.\",Portrait=M..\"dungeons\\\\wc\\\\pythas-portrait\",Frame=M..\"dungeons\\\\wc\\\\pythas-frame\",MapCoordinateX=88.1,MapCoordinateY=23.4,L=\"6472:33,6473:33,80711:33\"},\n{Id=\"3674\",Name=\"Skum\",Story=\"Skum first journeyed to the Wailing Caverns for relief from the Barrens' hostile environment. Like many of the caves' other inhabitants, he quickly succumbed to corruption. His veins now pulse with dark energies that have transformed him into a mighty and ruthless beast beyond redemption.\",Portrait=M..\"dungeons\\\\wc\\\\skum-portrait\",Frame=M..\"dungeons\\\\wc\\\\skum-frame\",MapCoordinateX=93.8,MapCoordinateY=63.1,L=\"6448:33,6449:33,80712:33\"},\n{Id=\"61965\",Name=\"Vangros\",Story=\"Naralex's attempt to restore the Barrens inadvertently birthed a waking nightmare, causing irreparable damage to the balance of Kalimdor. Vangros is a testament to the volatility of these involuntary powers; a manifestation of the rampant, violent overgrowths that have begun to move of their own accord within the stone labyrinth. This creature radiates a corrupted druidic magic, serving as a dangerous countermeasure against any who seek to navigate the cursed maze and free the Dreamer from his eternal slumber.\",Portrait=M..\"dungeons\\\\wc\\\\vangros-portrait\",Frame=M..\"dungeons\\\\wc\\\\vangros-frame\",MapCoordinateX=86.2,MapCoordinateY=80.9,L=\"55374:50,55372:25,55373:25\"},\n{Id=\"3673\",Name=\"Lord Serpentis\",Story=\"The Druids of the Fang's leader was once Naralex's finest student. His tragic downfall stemmed from his desire to become a shan'do, or honored teacher like Naralex. As insanity took root, Serpentis rallied his brethren to his side and formed the Druids of the Fang.\",Portrait=M..\"dungeons\\\\wc\\\\serpentis-portrait\",Frame=M..\"dungeons\\\\wc\\\\serpentis-frame\",MapCoordinateX=69,MapCoordinateY=42.9,L=\"10411:25,6469:25,6459:25,5970:25\"},\n{Id=\"3671\",Name=\"Lady Anacondra\",Story=\"Scarletleaf was the first to volunteer for Naralex's self-appointed mission to the Barrens. After her master's nightmare shattered her mind, the young acolyte cast aside her name, now envisioning a sinister reptilian future for Azeroth.\",Portrait=M..\"dungeons\\\\wc\\\\anacondra-portrait\",Frame=M..\"dungeons\\\\wc\\\\anacondra-frame\",MapCoordinateX=50.5,MapCoordinateY=25,L=\"5404:25,6446:25,10412:25,80709:25,23800:1\"},\n{Id=\"5775\",Name=\"Verdan the Everliving\",Story=\"Little is known about this creature prior to Naralex's arrival at the Wailing Caverns. Thought to be the caves' original guardian, Verdan the Everliving could not escape the corruption that befell its home. Verdan is allied with the insane druids and maintains its vigil against those who trespass into its domain.\",Portrait=M..\"dungeons\\\\wc\\\\verdan-portrait\",Frame=M..\"dungeons\\\\wc\\\\verdan-frame\",MapCoordinateX=64.2,MapCoordinateY=37.5,L=\"6629:33,6630:33,6631:33\"},\n{Id=\"3654\",Name=\"Mutanus the Devourer\",Story=\"From the darkest corners of Naralex's twisted mind, the corruption plaguing the Emerald Dream has manifested in the form of the druid's worst enemy: murlocs. The aberration known as Mutanus has come to the waking world to devour any who seek to liberate Naralex from the Nightmare's clutches.\",Portrait=M..\"dungeons\\\\wc\\\\mutanus-portrait\",Frame=M..\"dungeons\\\\wc\\\\mutanus-frame\",MapCoordinateX=46.7,MapCoordinateY=12.1,L=\"6461:25,6463:25,6627:25,81006:25,51217:1\"},\n}}\nZLDB.DG[\"WHC\"]={\nName=\"Windhorn Canyon\",\nStory=\"This ancient canyon has been home to many tauren tribes who have in years past fought for the dominance of its flowing waters and shelter from the dangers of Kalimdor. The cultures and traditions of many have lived within Windhorn Canyon, which can be seen from the ancient shelters carved into the mountainside, to the relics coveted by the Tauren. As of recently the Windhorn Tauren were expelled and driven away by the Grimtotem who have conquered it, and claimed it for their own.\",\nBackground=M..\"dungeons\\\\whc\\\\background\",\nGridBackground=M..\"dungeons\\\\whc\\\\grid-background\",\nMapId=45,\nIconScale=1,\nMinLevel=26,\nMaxLevel=30,\nEntrances={{MapContinentId=1,MapCoordinateX=68.7,MapCoordinateY=25.7,MapZoneId=34}},\nType=T.Dungeon,\nKey=\"WHC\",\nBosses={\n{Id=\"pathun\",Name=\"Pathun Duskhide\",Story=\"Whatever brought Pathun Duskhide to the canyon, it was not recorded. Whatever kept him there, even less so.\",Portrait=M..\"dungeons\\\\whc\\\\pathun-portrait\",Frame=M..\"dungeons\\\\whc\\\\pathun-frame\",MapCoordinateX=33.1,MapCoordinateY=44.3,L=\"33025:25,33026:25,33028:25,33027:25,70242:6\"},\n{Id=\"ahgktos\",Name=\"Ahgk'tos the Pure\",Story=\"Pure in what regard, and by whose measure - those who might have answered are long gone from Windhorn Canyon.\",Portrait=M..\"dungeons\\\\whc\\\\ahgktos-portrait\",Frame=M..\"dungeons\\\\whc\\\\ahgktos-frame\",MapCoordinateX=26.3,MapCoordinateY=9.7,L=\"33024:25,33022:25,33023:25,33021:25\"},\n{Id=\"vortalus\",Name=\"Ambassador Vortalus\",Story=\"Windhorn Canyon holds no record of Ambassador Vortalus - only the title, and the threat it implies.\",Portrait=M..\"dungeons\\\\whc\\\\vortalus-portrait\",Frame=M..\"dungeons\\\\whc\\\\vortalus-frame\",MapCoordinateX=36.8,MapCoordinateY=62,MapIsBelow=true,Abilities={{Effect=\"Vortalus stuns a random enemy, rendering them unable to move or attack for 4 seconds.\",Flags={F.Interruptible,F.Important},Icon=\"spell_nature_earthbind\",Id=\"6982\",Name=\"Gust of Wind\"},{Effect=\"Vortalus creates a lightning bolt that chains between all enemies.\",Flags={F.Interruptible},Icon=\"spell_nature_chainlightning\",Id=\"vortaluschainlightning\",Name=\"Chain Lightning\"}},L=\"33030:25,33031:25,33029:25,33032:25\"},\n{Id=\"walgan\",Name=\"Walgan Bloodcaller\",Story=\"The name Walgan Bloodcaller has passed through no chronicle, left no mark - nothing but the name itself.\",Portrait=M..\"dungeons\\\\whc\\\\walgan-portrait\",Frame=M..\"dungeons\\\\whc\\\\walgan-frame\",MapCoordinateX=18.2,MapCoordinateY=68.7,L=\"33082:25,33035:25,42275:25,33033:25\"},\n{Id=\"narlgom\",Name=\"Bonespeaker Narlgom\",Story=\"Among the Grimtotem who seized Windhorn Canyon, Bonespeaker Narlgom is counted - and that is, in full, the extent of what is known.\",Portrait=M..\"dungeons\\\\whc\\\\narlgom-portrait\",Frame=M..\"dungeons\\\\whc\\\\narlgom-frame\",MapCoordinateX=36.8,MapCoordinateY=56.8,MapIsBelow=true,L=\"42276:25,33040:25,33038:25,33037:25\"},\n{Id=\"stormhoof\",Name=\"Prophet Stormhoof\",Story=\"Prophets speak of things to come. If Prophet Stormhoof ever did, no one was left to write it down.\",Portrait=M..\"dungeons\\\\whc\\\\stormhoof-portrait\",Frame=M..\"dungeons\\\\whc\\\\stormhoof-frame\",MapCoordinateX=40.5,MapCoordinateY=56,MapIsBelow=true,Abilities={{Effect=\"Stormhoof corrupts a random enemy, dealing shadow damage over time.\",Flags={F.Curse},Icon=\"spell_shadow_abominationexplosion\",Id=\"stormhoofcorruption\",Name=\"Corruption\"}},L=\"33043:25,33042:25,33044:25,33041:25,70244:6\"},\n{Id=\"shalk\",Name=\"Chieftain Shalk Blackwind\",Story=\"He conquered. He rules. Beyond that, the canyon offers nothing of Chieftain Shalk Blackwind.\",Portrait=M..\"dungeons\\\\whc\\\\shalk-portrait\",Frame=M..\"dungeons\\\\whc\\\\shalk-frame\",MapCoordinateX=48.6,MapCoordinateY=44,L=\"33047:33,33046:33,33045:33,42277:1,70243:6,33048:25\"},\n}}\nZLDB.DG[\"ZF\"]={\nName=\"Zul'Farrak\",\nStory=\"Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated group was forced to surrender much of its territory throughout history. Now, it appears that Zul'Farrak's inhabitants are creating a horrific army of undead trolls to conquer the surrounding region. Other disturbing rumors tell of an ancient creature sleeping within the city--one that, if awakened, will rain death and destruction across Tanaris.\",\nBackground=M..\"dungeons\\\\zf\\\\background\",\nGridBackground=M..\"dungeons\\\\zf\\\\grid-background\",\nMapId=5,\nIconScale=0.8,\nMinLevel=42,\nMaxLevel=51,\nEntrances={{MapContinentId=1,MapCoordinateX=39.2,MapCoordinateY=20.1,MapZoneId=24}},\nType=T.Dungeon,\nKey=\"ZF\",\nBosses={\n{Id=\"10082\",Name=\"Zerillis\",Story=\"An elusive troll, rarely seen accross the city of Zul'Farrak. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...\",Portrait=M..\"dungeons\\\\zf\\\\zerillis-portrait\",Frame=M..\"dungeons\\\\zf\\\\zerillis-frame\",MapCoordinateX=52.4,MapCoordinateY=41.6,IsRare=true,L=\"12470:19\"},\n{Id=\"7272\",Name=\"Theka the Martyr\",Story=\"Long ago, the martyr Theka was slain in the brutal war between the qiraji and the trolls. Zul'Farrak still stands because of his brave sacrifice. Even in death he maintains a vigil over his beloved city, and it is said that the dozens of insectoid warriors who killed him were cursed to live as mindless scarabs, scuttling at the martyr's side.\",Portrait=M..\"dungeons\\\\zf\\\\theka-portrait\",Frame=M..\"dungeons\\\\zf\\\\theka-frame\",MapCoordinateX=52.9,MapCoordinateY=26.2},\n{Id=\"8127\",Name=\"Antu'sul\",Story=\"Antu'sul prefers his sul'lithuz basilisks strong and ruthless. He treats these scaled beasts like family, and he is known to strike down anyone--even fellow trolls--who harm his precious children. Rather than give his opponents a proper burial, Antu'sul allows the basilisks to feast on whoever dares cross him.\",Portrait=M..\"dungeons\\\\zf\\\\antusul-portrait\",Frame=M..\"dungeons\\\\zf\\\\antusul-frame\",MapCoordinateX=64.4,MapCoordinateY=27.6,L=\"9379:25,9639:25,9640:25,9641:25,51217:1,9243:2\"},\n{Id=\"7271\",Name=\"Witch Doctor Zum'rah\",Story=\"The powerful loa Bwonsamdi watches over the spirits of the Darkspear trolls, but many of the Sandfury tribe's fallen members are offered no such protection after death. These tortured spirits obey Zum'rah, a cruel witch doctor who uses his dark magic to force the city's dead into unending service.\",Portrait=M..\"dungeons\\\\zf\\\\zumrah-portrait\",Frame=M..\"dungeons\\\\zf\\\\zumrah-frame\",MapCoordinateX=44.2,MapCoordinateY=17.5,L=\"18082:50,18083:50,51803:8,9243:2,51217:1\"},\n{Id=\"7275\",Name=\"Shadowpriest Sezz'ziz\",Story=\"Nekrum Gutchewer has mysteriously lived well past his natural life, but his decaying body remains strong enough to aid Sezz'ziz. Together, these two trolls have gathered sacrifices to the mythic beast Gahz'rilla, who slumbers at the city's heart. Many troll followers eagerly await the terrifying creature's awakening, and they will do anything to see the ritual through.\",Portrait=M..\"dungeons\\\\zf\\\\sezzziz-portrait\",Frame=M..\"dungeons\\\\zf\\\\sezzziz-frame\",MapCoordinateX=29.4,MapCoordinateY=16.8,L=\"9470:25,9473:25,9474:25,9475:25,9243:2,51217:1\"},\n{Id=\"7267\",Name=\"Chief Ukorz Sandscalp\",Story=\"Chief Ukorz Sandscalp is obsessed with restoring his tribe to its former glory. He was raised on stories of a time when trolls lorded over their ancient lands without interference from goblins, gnomes, pirates, ogres, and other foreign interlopers. Sandscalp has called on his trusted comrade Ruuzlu to help him begin a new chapter in Sandfury history in the only way their tribe knows how: with swift and blinding violence.\",Portrait=M..\"dungeons\\\\zf\\\\ukorz-portrait\",Frame=M..\"dungeons\\\\zf\\\\ukorz-frame\",MapCoordinateX=42.3,MapCoordinateY=33.7,L=\"9476:20,9477:20,9478:20,9479:20,11086:20,9243:2,51217:5\"},\n{Id=\"7273\",Name=\"Gahz'rilla\",Story=\"Legend has it that Gahz'rilla was an adored pet of the Old Gods, or even a demigod in her own right. Whatever the truth is, the Sandfury trolls have worshiped this monstrous hydra for thousands of years. Ever wary of the beast's icy wrath, the trolls will only rouse Gahz'rilla when they have plentiful sacrifices to sate the ravenous creature's appetite.\",Portrait=M..\"dungeons\\\\zf\\\\gahzrilla-portrait\",Frame=M..\"dungeons\\\\zf\\\\gahzrilla-frame\",MapCoordinateX=31.5,MapCoordinateY=41.3,L=\"9469:50,9467:30,80747:20,51217:1\"},\n{Id=\"62495\",Name=\"Zel'jeb the Ancient\",Story=\"While Chief Ukorz Sandscalp was once a promising leader whose mind was eventually warped by dark magics, Zel'jeb represents the older, lingering shadows of the Sandfury tribe. This ancient troll serves as a grim reminder of the magic that began the corruption of the city's leadership, helping to fuel the brutal and cold nature that now defines the chief's inner sanctum. As the sands of Zul'Farrak shift, Zel'jeb stands alongside the tribe's most fanatical warriors, ensuring that the legacy of their warped power does not simply drift away like sand on the dunes.\",Portrait=M..\"dungeons\\\\zf\\\\zeljeb-portrait\",Frame=M..\"dungeons\\\\zf\\\\zeljeb-frame\",MapCoordinateX=14.1,MapCoordinateY=32,L=\"58116:25,58117:25,58118:25,58119:25\"},\n{Id=\"62498\",Name=\"Farraki Arena\",Story=\"The Farraki Arena is a reputed battleground where trolls from all accross the city of Zul'Farrak come and compete in bloody death matches.\",Portrait=M..\"dungeons\\\\zf\\\\arena-portrait\",Frame=M..\"dungeons\\\\zf\\\\arena-frame\",MapCoordinateX=43.8,MapCoordinateY=58.3,L=\"58092:25,58093:25,58094:25,58095:25\"},\n}}\nZLDB.R[\"AQ20\"]={\nName=\"Ruins of Ahn'Qiraj\",\nStory=\"During the final hours of the War of the Shifting Sands, the combined forces of the night elves and the four dragonflights drove the battle to the very heart of the qiraji empire, to the fortress city of Ahn'Qiraj. Yet at the city gates, the armies of Kalimdor encountered a concentration of silithid war drones more massive than any they had encountered before. Ultimately the silithid and their qiraji masters were not defeated, but merely imprisoned inside a magical barrier, and the war left the cursed city in ruins. A thousand years have passed since that day, but the qiraji forces have not been idle. A new and terrible army has been spawned from the hives, and the ruins of Ahn'Qiraj are teeming once again with swarming masses of silithid and qiraji. This threat must be eliminated, or else all of Azeroth may fall before the terrifying might of the new qiraji army.\",\nBackground=M..\"raids\\\\aq20\\\\background\",\nGridBackground=M..\"raids\\\\aq20\\\\grid-background\",\nMapId=15,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=58.7,MapCoordinateY=14.1,MapZoneId=14}},\nType=T.Raid,\nKey=\"AQ20\",\nBosses={\n{Id=\"15348\",Name=\"Kurinnaxx\",Story=\"Deep in the marrow of the hive, the Horde led by Varok Saurfang faced Kurinnaxx when they raided the ruins.\",Portrait=M..\"raids\\\\aq20\\\\kurinnaxx-portrait\",Frame=M..\"raids\\\\aq20\\\\kurinnaxx-frame\",MapCoordinateX=56,MapCoordinateY=35.9,Abilities={{Effect=\"Kurinnaxx strike up to three enemies in front of him, dealing weapon damage plus an additional 200 physical damage.\\\n\\\nThis attack applies Mortal Wounds on the target.\",Flags={F.Tank,F.Important},Icon=\"Ability_Warrior_Cleave\",Id=\"26350\",Name=\"Cleave\",SubAbilities={{Effect=\"A stacking debuff that reduces healing received by 10% for 30 seconds.\\\n\\\nThis effect stacks rapidly, requiring tanks to swap at 3 to 4 stacks to avoid being overwhelmed.\",Flags={F.Tank,F.Important},Icon=\"Ability_CriticalStrike\",Id=\"25646\",Name=\"Mortal Wound\"}}},{Effect=\"Kurinnaxx creates sand traps beneath random players that expand over time and detonate after a few seconds.\\\n\\\nAffected players are silenced and have their melee and ranged hit chance reduced by 75% for 20 seconds.\\\n\\\nPlayers should move out of traps immediately. Spreading out reduces the risk of multiple players being affected.\",Icon=\"INV_Misc_Dust_02\",Id=\"25656\",Name=\"Sand Trap\"},{Effect=\"At 30% health. Kurinnaxx becomes enraged, increasing his damage dealt significantly.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Shadow_UnholyFrenzy\",Id=\"kurinnaxxenrage\",Name=\"Enrage\"}},L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20885:25,20888:25,20889:25,21498:17,21499:17,21500:17,21501:17,21502:17,21503:17\"},\n{Id=\"15341\",Name=\"General Rajaxx\",Story=\"During the War of the Shifting Sands, the monstrous, towering Rajaxx commanded the qiraji and silithid in battle, swinging clawed limbs and shouting commands to his soldiers. During the war, he clashed with Fandral and Valstann Staghelm, the leaders of the night elf forces, and later personally executed Valstann by ripping him in two with his claws.\",Portrait=M..\"raids\\\\aq20\\\\rajaxx-portrait\",Frame=M..\"raids\\\\aq20\\\\rajaxx-frame\",MapCoordinateX=58.6,MapCoordinateY=49.3,L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20885:25,20888:25,20889:25,21492:17,21493:17,21494:17,21495:17,21496:17,21497:17,81004:10\"},\n{Id=\"15340\",Name=\"Moam\",Story=\"The Twin Emperors intended to use Moam as a colossal weapon, knowing that its strengths would help it survive in the thick of melee as well as magical combat-but they did not expect for the construct's abilities to advance further without their own assistance.\",Portrait=M..\"raids\\\\aq20\\\\moam-portrait\",Frame=M..\"raids\\\\aq20\\\\moam-frame\",MapCoordinateX=32.9,MapCoordinateY=36.7,L=\"22220:15,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20886:25,20888:25,20890:25,21455:11,21468:11,21469:11,21470:11,21473:11,21474:11,21475:11,21476:11,21477:11,21467:25,21471:25,21472:25,21479:25\"},\n{Id=\"15370\",Name=\"Buru the Gorger\",Story=\"Lurking beneath the ruins, Buru the Gorger is a massive silithid colossus with an insatiable appetite. It feeds on any intruders who stumble into its hatchery, crushing them with immense physical force before consuming them to sustain its massive bulk.\",Portrait=M..\"raids\\\\aq20\\\\buru-portrait\",Frame=M..\"raids\\\\aq20\\\\buru-frame\",MapCoordinateX=70.1,MapCoordinateY=62.4,L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:17,20885:17,20886:17,20888:17,20889:17,20890:17,21485:14,21486:14,21487:14,21488:14,21489:14,21490:14,21491:14\"},\n{Id=\"15369\",Name=\"Ayamiss the Hunter\",Story=\"Ayamiss is the matriarch of the deadly silithid wasp swarm that infests the Ruins of Ahn'Qiraj. From the air, she commands her brood to sacrifice any who enter her domain, using their life force to feed the writhing larvae waiting to hatch below.\",Portrait=M..\"raids\\\\aq20\\\\ayamiss-portrait\",Frame=M..\"raids\\\\aq20\\\\ayamiss-frame\",MapCoordinateX=61.8,MapCoordinateY=90,L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:17,20885:17,20886:17,20888:17,20889:17,20890:17,21466:12,21478:12,21479:12,21480:12,21481:12,21482:12,21483:12,21484:12\"},\n{Id=\"15339\",Name=\"Ossirian the Unscarred\",Story=\"Ossirian serves the twin Emperors to the best of his ability, despite the frustration of being eternally bound to a single location. The bones of Grakkarond have become a sacred site to the Anubisaths; a testimony to their ability to defeat even the most powerful of enemies.\",Portrait=M..\"raids\\\\aq20\\\\ossirian-portrait\",Frame=M..\"raids\\\\aq20\\\\ossirian-frame\",MapCoordinateX=43.3,MapCoordinateY=69.3,L=\"21220:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:11,21279:11,21280:11,21281:11,21282:11,21283:11,21288:11,21291:11,21297:11,21284:11,21285:11,21287:11,21289:11,21292:11,21294:11,21295:11,21296:11,21298:11,21457:15,21459:10,21460:15,21461:15,21462:15,21463:15,21464:15,21452:18,21453:18,21454:18,21456:18,21458:18,21715:10,21290:11,21293:11,21299:11,21300:11,21302:11,21303:11,21304:11,21306:11,21307:11,20886:50,20890:50,132:6\"},\n}}\nZLDB.R[\"AQ40\"]={\nName=\"Temple of Ahn'Qiraj\",\nStory=\"At the heart of Ahn'Qiraj lies an ancient temple complex. Built in the time before recorded history, it is both a monument to unspeakable gods and a massive breeding ground for the qiraji army. Since the War of the Shifting Sands ended a thousand years ago, the Twin Emperors of the qiraji empire have been trapped inside their temple, barely contained behind the magical barrier erected by the bronze dragon Anachronos and the night elves.\",\nBackground=M..\"raids\\\\aq40\\\\background\",\nGridBackground=M..\"raids\\\\aq40\\\\grid-background\",\nMapId=28,\nZoneId=2,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=46.4,MapCoordinateY=7.7,MapDestinationZoneId=2,MapZoneId=14}},\nType=T.Raid,\nKey=\"AQ40\",\nBosses={\n{Id=\"15263\",Name=\"The Prophet Skeram\",Story=\"The Prophet Skeram is an important religious leader in Ahn'Qiraj, and author of The Prophecy of C'Thun.\",Portrait=M..\"raids\\\\aq40\\\\skeram-portrait\",Frame=M..\"raids\\\\aq40\\\\skeram-frame\",MapCoordinateX=46,MapCoordinateY=51.7,MapId=2,L=\"22222:15,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21128:10,21698:18,21699:18,21700:18,21701:18,21702:18,21703:10,21704:15,21705:15,21706:15,21707:15,21708:15,21814:15,21232:4,21237:4\"},\n{Id=\"15544\",Name=\"Silithid Royalty\",Story=\"The Silithid Royalty consists of Lord Kri, Princess Yauj, and Vem. This deadly trio serves the Qiraji empire by coordinating the insectoid swarms. They fight as one cohesive unit, flying into a blood-frenzied rage if one of their own falls in combat.\",Portrait=M..\"raids\\\\aq40\\\\trio-portrait\",Frame=M..\"raids\\\\aq40\\\\trio-frame\",MapCoordinateX=28.5,MapCoordinateY=49.6,MapId=1,L=\"21688:25:n3,21689:25:n3,21690:25:n3,21691:25:n3,21682:20:n4,21683:20:n4,21684:20:n4,21686:20:n4,21687:20:n4,21603:25:n5,21680:25:n5,21681:25:n5,21685:25:n5,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21692:17,21693:17,21694:17,21695:17,21696:17,21697:17\"},\n{Id=\"15516\",Name=\"Battleguard Sartura\",Story=\"Battleguard Sartura is the leader of the Qiraji battleguards.\",Portrait=M..\"raids\\\\aq40\\\\sartura-portrait\",Frame=M..\"raids\\\\aq40\\\\sartura-frame\",MapCoordinateX=44.6,MapCoordinateY=33.6,MapId=1,L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21666:10,21667:15,21668:15,21669:15,21670:15,21671:15,21672:15,21648:18,21673:10,21674:18,21675:18,21676:18,21678:18\"},\n{Id=\"15510\",Name=\"Fankriss the Unyielding\",Story=\"A colossal sand reaver and spawn of the legendary Ouro, Fankriss the Unyielding dwells deep within the tunnels of the Temple of Ahn'Qiraj. He fiercely guards the subterranean pathways of the temple, ambushing interlopers alongside endless waves of silithid hatchlings.\",Portrait=M..\"raids\\\\aq40\\\\fankriss-portrait\",Frame=M..\"raids\\\\aq40\\\\fankriss-frame\",MapCoordinateX=62.2,MapCoordinateY=22.6,MapId=1,L=\"20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21650:10,21651:18,21652:18,21663:18,21664:18,21665:18,21627:15,21635:10,21639:15,21645:15,21647:15,22396:15,22402:15\"},\n{Id=\"15299\",Name=\"Viscidus\",Story=\"Viscidus is a massive, noxious slime lurking within the dark depths of the temple. Believed to be an ancient, gelatinous entity kept by the Qiraji, it is nearly impervious to physical harm and must be frozen solid before it can be shattered into vulnerable pieces.\",Portrait=M..\"raids\\\\aq40\\\\viscidus-portrait\",Frame=M..\"raids\\\\aq40\\\\viscidus-frame\",MapCoordinateX=72.2,MapCoordinateY=17.9,MapId=1,L=\"20928:100,20932:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21622:14,21623:14,21624:14,21625:14,21626:14,21677:14,22399:14\"},\n{Id=\"15509\",Name=\"Princess Huhuran\",Story=\"Princess Huhuran is a massive, highly toxic silithid wasp stationed deep within the Temple of Ahn'Qiraj. She relentlessly defends the hive, unleashing devastating volleys of acidic poison and frenzied attacks to melt through the armor of any who dare threaten the Qiraji brood.\",Portrait=M..\"raids\\\\aq40\\\\huhuran-portrait\",Frame=M..\"raids\\\\aq40\\\\huhuran-frame\",MapCoordinateX=43.5,MapCoordinateY=50.1,MapId=1,L=\"20928:100,20932:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21616:17,21617:17,21618:17,21619:17,21620:17,21621:17\"},\n{Id=\"15276\",Name=\"The Twin Emperors\",Story=\"The clever brothers Vek'lor and Vek'nilash are known as the Twin Emperors. They rule over the qiraji from the sanctuary of their temple.\",Portrait=M..\"raids\\\\aq40\\\\twins-portrait\",Frame=M..\"raids\\\\aq40\\\\twins-frame\",MapCoordinateX=60.7,MapCoordinateY=69.9,MapId=1,L=\"20735:6,20930:100,21232:4,21237:4,21597:17,21598:17,21599:17,21600:17,21601:17,21602:17,20726:6,20926:100,21604:14,21605:14,21606:14,21607:14,21608:14,21609:14,21679:14\"},\n{Id=\"15517\",Name=\"Ouro\",Story=\"The ancient sand worm, Ouro, is a being of legendary power. He is rumored to have been created by the Old God C'Thun himself as a mockery of life. His skin is unnaturally thick, nearly impregnable. It's flexible and allows him to move with the speed and grace of a much smaller creature.\",Portrait=M..\"raids\\\\aq40\\\\ouro-portrait\",Frame=M..\"raids\\\\aq40\\\\ouro-frame\",MapCoordinateX=30.4,MapCoordinateY=81.4,MapId=1,L=\"20927:100,20931:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21610:17,21611:17,21615:17,23557:17,23558:17,23570:17,21612:17,21613:17,21614:17,55553:17,55554:17,55555:17\"},\n{Id=\"15727\",Name=\"C'Thun\",Story=\"C'Thun is the Old God of madness and chaos, one of the four ancient and powerful creatures who ruled the world of Azeroth long ago before being defeated and imprisoned by servants of the titans. C'Thun created the qiraji and resided within the city of Ahn'Qiraj in Silithus.\",Portrait=M..\"raids\\\\aq40\\\\cthun-portrait\",Frame=M..\"raids\\\\aq40\\\\cthun-frame\",MapCoordinateX=33.3,MapCoordinateY=49.1,MapId=1,L=\"20929:100,20933:100,21221:100,21126:8,21585:18,21586:18,21596:18,22730:18,22731:18,21134:8,21581:21,21582:21,21583:21,21839:8,22732:21,36550:1,21579:15,41077:8,60003:8\"},\n}}\nZLDB.R[\"BWL\"]={\nName=\"Blackwing Lair\",\nStory=\"In the dark recesses of the mountain's peak, Nefarian, the eldest son of Deathwing, conducts some of his most awful experimentation, controlling mighty beings like puppets and combining the eggs of different dragonflights with horrific results. Should he prove successful, even darker pursuits rest on the horizon. And, yet, the Lord of Blackrock is not a mere scientist - he is a great dragon cornered in his lair. Can he truly be defeated by mortal hands?\",\nBackground=M..\"raids\\\\bwl\\\\background\",\nGridBackground=M..\"raids\\\\bwl\\\\grid-background\",\nMapId=20,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=64.1,MapCoordinateY=71.7,MapZoneId=6}},\nType=T.Raid,\nKey=\"BWL\",\nBosses={\n{Id=\"12435\",Name=\"Razorgore the Untamed\",Story=\"Razorgore the Untamed is a dragonspawn of the black dragonflight. He has been tasked by the lord of Blackwing Lair, Nefarian, with guarding the numerous and precious black dragon eggs located in the first room of the instance. To this end, Razorgore has been given command of a cohort of orcs and other forces, and will stop at nothing to ensure that no harm comes to his grave charges.\",Portrait=M..\"raids\\\\bwl\\\\razorgore-portrait\",Frame=M..\"raids\\\\bwl\\\\razorgore-frame\",MapCoordinateX=54.1,MapCoordinateY=72.5,MapIsBelow=true,L=\"16904:11,16911:11,16918:11,16926:11,16934:11,16935:11,16943:11,16951:11,16959:11,19334:10,19335:10,19336:20,19337:20,19369:20,19370:20\"},\n{Id=\"13020\",Name=\"Vaelastrasz the Corrupt\",Story=\"Vaelastrasz the Corrupt was corrupted by Nefarian and now serves him unwillingly.\",Portrait=M..\"raids\\\\bwl\\\\vaelastrasz-portrait\",Frame=M..\"raids\\\\bwl\\\\vaelastrasz-frame\",MapCoordinateX=46.5,MapCoordinateY=47,MapIsBelow=true,L=\"16818:11,16903:11,16910:11,16925:11,16933:11,16936:11,16944:11,16952:11,16960:11,19339:20,19340:20,19346:10,19348:10,19371:20,19372:20\"},\n{Id=\"12017\",Name=\"Broodlord Lashlayer\",Story=\"Broodlord Lashlayer is a black drakonid in Nefarian's service who guards the Halls of Strife in Blackwing Lair, blocking the way into Nefarian's inner sanctum.\",Portrait=M..\"raids\\\\bwl\\\\broodlord-portrait\",Frame=M..\"raids\\\\bwl\\\\broodlord-frame\",MapCoordinateX=52,MapCoordinateY=66.3,L=\"20383:100,16898:11,16906:11,16912:11,16919:11,16927:11,16941:11,16949:11,16957:11,16965:11,19341:20,19342:20,19350:10,19351:10,19373:20,19374:20,33083:7\"},\n{Id=\"11983\",Name=\"Firemaw\",Story=\"Firemaw is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.\",Portrait=M..\"raids\\\\bwl\\\\firemaw-portrait\",Frame=M..\"raids\\\\bwl\\\\firemaw-frame\",MapCoordinateX=44.3,MapCoordinateY=42.1,L=\"19343:12,19344:12,19365:12,19398:12,19399:12,19400:12,19401:12,19402:12,16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7\"},\n{Id=\"ezzel\",Name=\"Ezzel Darkbrewer\",Story=\"Ezzel Darkbrewer might be a goblin of small stature but he is by no means a pushover. With an arsenal of chemical concoctions and a brilliant mind sharpened by many years in the field, he's ready to thwart any intruders stepping into his employer's laboratory. Oh, and don't forget the lumbering ogre he's atop of.\",Portrait=M..\"raids\\\\bwl\\\\ezzel-portrait\",Frame=M..\"raids\\\\bwl\\\\ezzel-frame\",MapCoordinateX=16.8,MapCoordinateY=55.8,L=\"33073:7,33074:7,33075:7,33076:7,33077:7,33078:7,33079:7,33080:7,33081:7,33086:7,33083:7,33084:7,33085:7\"},\n{Id=\"14601\",Name=\"Ebonroc\",Story=\"Ebonroc is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.\",Portrait=M..\"raids\\\\bwl\\\\ebonroc-portrait\",Frame=M..\"raids\\\\bwl\\\\ebonroc-frame\",MapCoordinateX=38.4,MapCoordinateY=32,L=\"16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7,19345:17,19368:17,19403:17,19405:17,19406:17,19407:17\"},\n{Id=\"11981\",Name=\"Flamegor\",Story=\"Flamegor is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.\",Portrait=M..\"raids\\\\bwl\\\\flamegor-portrait\",Frame=M..\"raids\\\\bwl\\\\flamegor-frame\",MapCoordinateX=45.7,MapCoordinateY=22.2,L=\"19357:17,19367:17,19430:17,19431:17,19432:17,19433:17,16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7\"},\n{Id=\"14020\",Name=\"Chromaggus\",Story=\"Chromaggus is a two-headed dragon beast creation of Nefarian, who acts as a dutiful protector of Blackwing Lair. Despite his canine appearance, he's actually a dragonkin (more specifically a drakeadon). The victims of Chromaggus' radiating affliction were transformed into drakonid.\",Portrait=M..\"raids\\\\bwl\\\\chromaggus-portrait\",Frame=M..\"raids\\\\bwl\\\\chromaggus-frame\",MapCoordinateX=49.4,MapCoordinateY=52,L=\"16832:11,16902:11,16917:11,16924:11,16932:11,16937:11,16945:11,16953:11,16961:11,19349:10,19352:10,19385:20,19387:20,19388:20,19389:20,19347:10,19361:10,19386:16,19390:16,19391:16,19392:16,19393:16,33084:20\"},\n{Id=\"11583\",Name=\"Nefarian\",Story=\"Nefarian is the eldest son of Deathwing and his Prime Consort Sintharia. Like his father and his younger twin sister Onyxia, he has a human guise, appearing as Victor Nefarius, Lord of Blackrock. Holding the Blackrock clan and various clans of ogres under his control, Nefarian rules from his lair at the top of Blackrock Spire\",Portrait=M..\"raids\\\\bwl\\\\nefarian-portrait\",Frame=M..\"raids\\\\bwl\\\\nefarian-frame\",MapCoordinateX=75.4,MapCoordinateY=52.1,L=\"19003:100,16897:11,16905:11,16916:11,16923:11,16931:11,16942:11,16950:11,16958:11,16966:11,19360:10,19363:10,19375:20,19376:20,19377:20,19378:20,19356:10,19364:10,19379:20,19380:20,19381:20,19382:20,36551:1\"},\n}}\nZLDB.R[\"ES\"]={\nName=\"Emerald Sanctum\",\nStory=\"The Emerald Sanctum, a sacred refuge within the Dreamway, has fallen under the shadow of an insidious darkness. Once a baston of tranquility where the Green Dragonflight performed their most holy rituals, it has become a staging ground for the Nightmare's corruption. Now, the very defenders of the Dream have succumbed to malevolent whispers, threatening to turn the power of the 'Awakening' against Azeroth itself.\",\nBackground=M..\"raids\\\\es\\\\background\",\nGridBackground=M..\"raids\\\\es\\\\grid-background\",\nMapId=38,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=20.6,MapCoordinateY=60.6,MapZoneId=15}},\nType=T.Raid,\nKey=\"ES\",\nBosses={\n{Id=\"60747\",Name=\"Erennius\",Story=\"Once a noble hero dedicated to the cause of the Green Dragonflight, Erennius could not withstand the relentless pull of the Nightmare. The corruption sank deep into his heart during the ritual of the Awakening, twisting him into a powerful agent of evil. He now stands as a tragic sentinel of the Sanctum, his former heroism replaced by an unyielding hunger to spread the taint that claimed him.\",Portrait=M..\"raids\\\\es\\\\erennius-portrait\",Frame=M..\"raids\\\\es\\\\erennius-frame\",MapCoordinateX=67.3,MapCoordinateY=39.3,L=\"61652:100\"},\n{Id=\"60748\",Name=\"Solnius\",Story=\"Known as Solnius the Awakener, this dragon was one of Ysera's most cherished children and the sworn protector of the sacred Awakening ritual. Having succumbed to the alluring whispers of the Nightmare, Solnius has betrayed his lineage. He now wields the sacred powers of the Dream to serve the darkness, overseeing the corruption of the very realm he was born to safeguard.\",Portrait=M..\"raids\\\\es\\\\solnius-portrait\",Frame=M..\"raids\\\\es\\\\solnius-frame\",MapCoordinateX=70.4,MapCoordinateY=23.2,L=\"30018:2,61205:17,61206:17,61208:17,61209:17,61211:17,61214:17,61207:17,61210:17,61212:17,61213:17,61239:17,61448:17,41076:17,61203:17,61204:17,61237:17,61238:17,61455:17,51361:15,61196:25,61215:100,61217:4,61218:4,61424:4,61428:4,61432:4,70000:4,61444:35,61733:2,61522:17:h,61523:17:h,61524:17:h,61525:17:h,61526:17:h,61527:17:h,42165:60:h\"},\n}}\nZLDB.R[\"KARA10\"]={\nName=\"Lower Karazhan Halls\",\nStory=\"The lower reaches of Karazhan are a haunting echo of the tower's vibrant past, where spectral guests and servants are eternally bound to a single moment in time. Councilmen and dukes wander these corridors as tormented phantoms, often unaware of their own demise and still demanding the luxuries of room service and fine wine. Beneath the surface of these ghostly festivities, however, lies a darker reality: the tower has become a focal point for cursed artifacts like the Scythe of Elune and is prowled by a vicious pack of worgen. Those who navigate these halls must contend with spirits trapped in a loop of madness and the undead castellan who keeps the master's secrets under lock and key.\",\nBackground=M..\"raids\\\\kara10\\\\background\",\nGridBackground=M..\"raids\\\\kara10\\\\grid-background\",\nMapId=29,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=43.6,MapCoordinateY=75.6,MapZoneId=9}},\nType=T.Raid,\nKey=\"KARA10\",\nBosses={\n{Id=\"61319\",Name=\"Master Blacksmith Rolfen\",Story=\"The blacksmiths of Karazhan were once tasked with maintaining the intricate weaponry and armor of Medivh's guests. In death, Master Blacksmith Rolfen remains at his anvil, though his work is now fueled by the spectral essences that permeate the tower. He is said to guard rare smithing plans that many would kill to possess, ensuring that even in the afterlife, the forge of the Prophet never truly grows cold.\",Portrait=M..\"raids\\\\kara10\\\\rolfen-portrait\",Frame=M..\"raids\\\\kara10\\\\rolfen-frame\",MapCoordinateX=60.8,MapCoordinateY=82.5,MapIsBelow=true,L=\"61805:1,61806:1,61807:1,61808:1\"},\n{Id=\"61221\",Name=\"Brood Queen Araxxna\",Story=\"The dark arcane energy leaking from Medivh's experiments has twisted the natural wildlife within the tower's foundations. Araxxna, a massive arachnid, has claimed the shadowed corners of the lower halls as her nesting ground. She and her endless brood feast on the lost spirits and unwary explorers who wander too far from the guest chambers, weaving webs of solidified mana to trap her prey.\",Portrait=M..\"raids\\\\kara10\\\\araxxna-portrait\",Frame=M..\"raids\\\\kara10\\\\araxxna-frame\",MapCoordinateX=82.6,MapCoordinateY=25.3,MapIsBelow=true,L=\"8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,37011:20,51217:100,58275:100,61243:20,61260:20,61268:20,61270:20,61297:20,61244:14,61245:14,61269:14,61272:14,61278:14,61283:14,61816:14,70102:1\"},\n{Id=\"61224\",Name=\"Grizikil\",Story=\"A hoarder by nature, the creature known as Grizikil lurks at the end of the guest halls, surrounded by a mountain of stolen trinkets. Among his most bizarre treasures is a comically large candle, a colossal candlestick said to be essential for strange experiments within the Master's Library. He is fiercely protective of his stash, viewing any who approach as common thieves looking to plunder his 'status symbols'.\",Portrait=M..\"raids\\\\kara10\\\\grizikil-portrait\",Frame=M..\"raids\\\\kara10\\\\grizikil-frame\",MapCoordinateX=90.6,MapCoordinateY=38.6,L=\"8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,61251:20,61253:20,61276:20,61291:20,61292:20,61252:14,61261:14,61267:14,61288:14,61289:14,61298:14,61450:14,70102:1\"},\n{Id=\"61223\",Name=\"Clawlord Howlfang\",Story=\"Clawlord Howlfang is the tyrannical leader of the worgen that have infested Karazhan. Attracted by the presence of the Scythe of Elune-which was brought to the tower by a mysterious Dark Rider-Howlfang has asserted his dominance over the various tribes lurking in the shadows. By severing his grasp, one might hope to quell the feral devastation that threatens to consume the lower halls.\",Portrait=M..\"raids\\\\kara10\\\\clawlord-portrait\",Frame=M..\"raids\\\\kara10\\\\clawlord-frame\",MapCoordinateX=69.1,MapCoordinateY=55.5,L=\"8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,55552:100,61248:20,61249:20,61273:20,61281:20,61293:20,61250:14,61263:14,61271:14,61274:14,61285:14,61290:14,61451:14,70102:1,70226:3\"},\n{Id=\"61222\",Name=\"Lord Blackwald II\",Story=\"Lord Blackwald II is a wretched being who reveled in the dark acquisition of the Scythe of Elune. His malevolence resonates through the halls, finding a twisted satisfaction in the possession of the powerful, cursed relic. He guards the artifact with a fanaticism born of long-term exposure to its shadow-bound power, serving as a grim reminder that Karazhan's residents are as much prisoners of their own desires as they are of the tower's walls.\",Portrait=M..\"raids\\\\kara10\\\\blackwald-portrait\",Frame=M..\"raids\\\\kara10\\\\blackwald-frame\",MapCoordinateX=69.1,MapCoordinateY=74.3,L=\"8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,61184:2,61246:20,61247:20,61262:20,61266:20,61443:20,61255:14,61279:14,61282:14,61286:14,61287:14,61294:14,61449:14,70102:1,70226:3,42166:10\"},\n{Id=\"61225\",Name=\"Moroes\",Story=\"The cursed and undead castellan of Karazhan, Moroes continues his duties as if the master were still in residence. He is a cunning and fierce protector of the tower's inner workings, specifically guarding the Key to the Upper Chambers. While he appears as a simple servant, his combat prowess and refusal to allow prying eyes into the forbidden sections of the tower make him one of the most formidable obstacles in Lower Karazhan.\",Portrait=M..\"raids\\\\kara10\\\\moroes-portrait\",Frame=M..\"raids\\\\kara10\\\\moroes-frame\",MapCoordinateX=34.9,MapCoordinateY=25.3,L=\"8547:1,13517:2,58401:1,61177:1,61178:1,61180:1,61189:2,61190:2,61191:2,61192:2,61219:2,61739:1,70001:2,51217:100,61256:10,61257:10,61264:10,61265:10,61275:10,61277:10,61284:10,61299:10,61453:10,61454:10,70102:2\"},\n}}\nZLDB.R[\"KARA40\"]={\nName=\"Tower of Karazhan\",\nStory=\"Built upon a volatile focal point of ley lines, the tower of the Guardian Medivh remains a place of shifting realities. While the lower halls are haunted by the spirits of the past, the upper reaches have torn open a gateway to the shattered remains of Outland. Within the 'Rock of Desolation' wing, the Burning Legion has established a bridgehead, led by their most cunning commanders who seek to use the tower's power to consume Azeroth.\",\nBackground=M..\"raids\\\\kara40\\\\background\",\nGridBackground=M..\"raids\\\\kara40\\\\grid-background\",\nMapId=40,\nZoneId=2,\nIconScale=1,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=45.9,MapCoordinateY=71.1,MapDestinationZoneId=2,MapZoneId=9}},\nType=T.Raid,\nKey=\"KARA40\",\nBosses={\n{Id=\"61939\",Name=\"Keeper Gnarlmoon\",Story=\"A bloodmage of legendary power and a foul 'pricolich,' Gnarlmoon has entrenched himself within the tower's heart. He draws upon the cursed ley lines of Deadwind Pass to fuel his malevolent blood magic and guard the tower's dark secrets.\",Portrait=M..\"raids\\\\kara40\\\\gnarlmoon-portrait\",Frame=M..\"raids\\\\kara40\\\\gnarlmoon-frame\",MapCoordinateX=61.7,MapCoordinateY=44.8,MapId=2,L=\"55078:25,55081:25,55084:25,55285:25,55079:25,55080:25,55082:25,55083:25\"},\n{Id=\"61946\",Name=\"Ley-Watcher Incantagos\",Story=\"Enthralled by the unpredictable power of the tower, this former defender of Kel'Theril now stands as a sentinel of the arcane. He is unable to break away from the very energies that have warped his mind into a weapon of the tower.\",Portrait=M..\"raids\\\\kara40\\\\incantagos-portrait\",Frame=M..\"raids\\\\kara40\\\\incantagos-frame\",MapCoordinateX=49.3,MapCoordinateY=80.5,MapId=2,MapIsBelow=true,L=\"41403:100,55085:25,55087:25,55090:25,55091:25,55086:25,55089:25,55099:25,55507:25\"},\n{Id=\"61951\",Name=\"Anomalus\",Story=\"A volatile elemental manifestation of pure arcane pressure created by the tower's intense magical convergence. Its 'cosmic residue' is so saturated with ley energy that it is essential for the restoration of the Guardian's legendary artifacts.\",Portrait=M..\"raids\\\\kara40\\\\anomalus-portrait\",Frame=M..\"raids\\\\kara40\\\\anomalus-frame\",MapCoordinateX=63.4,MapCoordinateY=77.2,MapId=2,L=\"55092:25,55095:25,55096:25,55279:25,55093:25,55097:25,55098:25,55106:25\"},\n{Id=\"61958\",Name=\"Echo of Medivh\",Story=\"A spectral trace of the Guardian's second life, lingering in the fabric of the tower's ley lines. This echo represents Medivh's power and regret, serving as the final gatekeeper for those seeking the knowledge of the Upper Chambers.\",Portrait=M..\"raids\\\\kara40\\\\medivh-portrait\",Frame=M..\"raids\\\\kara40\\\\medivh-frame\",MapCoordinateX=27.4,MapCoordinateY=39.8,MapId=2,L=\"55094:25,55107:25,55111:25,55112:25,55108:25,55109:25,55110:25,55276:25\"},\n{Id=\"59967\",Name=\"Chess Event\",Story=\"A twisted recreation of Medivh's favorite game, where the pieces are imbued with the spirits of the tower's victims. Survival requires both tactical mastery and the ability to withstand the lethal magical cheats orchestrated by the tower's lingering consciousness.\",Portrait=M..\"raids\\\\kara40\\\\king-portrait\",Frame=M..\"raids\\\\kara40\\\\king-frame\",MapCoordinateX=60.3,MapCoordinateY=35.5,MapId=2,L=\"55088:1,55100:1,55101:1,55102:1,55103:1,55104:1,55105:1,55274:1,55483:50,55484:50,20739:2,55482:20\"},\n{Id=\"59981\",Name=\"Sanv Tas'dal\",Story=\"A Draenei whose spirit was further fractured by the spatial anomalies within this wing of the tower. Trapped within the Rock of Desolation, Sanv Tas'dal has been driven to a feral desperation, wielding the remnants of his shamanic heritage and dark voodoo to defend his meager territory from any intruders.\",Portrait=M..\"raids\\\\kara40\\\\sanv-portrait\",Frame=M..\"raids\\\\kara40\\\\sanv-frame\",MapCoordinateX=44.7,MapCoordinateY=35.6,MapId=1,L=\"55113:14,55114:14,55115:14,55116:14,55117:14,55118:14,55119:14,55485:50,55486:50,55482:20,69001:100\"},\n{Id=\"59961\",Name=\"Rupturan the Broken\",Story=\"A massive, sentient formation of stone and earth that was shattered during the destruction of Draenor. Reconstituted by the chaotic energies of the tower's rift, this literal 'broken' monolith now stands as a mindless, crushing force of nature, physically embodying the shattered landscape of the Rock of Desolation.\",Portrait=M..\"raids\\\\kara40\\\\rupturan-portrait\",Frame=M..\"raids\\\\kara40\\\\rupturan-frame\",MapCoordinateX=49.3,MapCoordinateY=25,MapId=1,L=\"55120:14,55121:14,55122:14,55123:14,55124:14,55125:14,55126:14,55487:50,55488:50,55482:20\"},\n{Id=\"59991\",Name=\"Kruul\",Story=\"High Lord Kruul, the 'Burning Shadow,' has utilized the rift within Karazhan to lead a demonic vanguard. A Doomlord of immense malice, he seeks to claim the Guardian's power to fuel the Legion's conquest across the Twisting Nether.\",Portrait=M..\"raids\\\\kara40\\\\kruul-portrait\",Frame=M..\"raids\\\\kara40\\\\kruul-frame\",MapCoordinateX=48.9,MapCoordinateY=75.6,MapId=1,L=\"55127:11,55128:11,55129:11,55130:11,55131:11,55132:11,55489:50,55490:50,55506:11,55510:11,55511:11,55482:20\"},\n{Id=\"93333\",Name=\"Mephistroth\",Story=\"A master of Nathrezim manipulation who orchestrates the Legion's movements from the shadows of the Rock of Desolation. Mephistroth thrives on the despair of the tower's trapped spirits, aiming to turn Karazhan into a permanent gateway for the Burning Crusade.\",Portrait=M..\"raids\\\\kara40\\\\mephistroth-portrait\",Frame=M..\"raids\\\\kara40\\\\mephistroth-frame\",MapCoordinateX=52.2,MapCoordinateY=68.1,MapId=1,L=\"41447:100,55346:6,55347:6,55348:6,55349:6,55350:6,55351:8,55352:8,55353:8,55354:8,55355:8,55356:8,55357:8,55512:8,55513:8,55482:20,55491:100,55492:100,55579:100,92082:5\"},\n}}\nZLDB.R[\"MC\"]={\nName=\"Molten Core\",\nStory=\"The Molten Core lies at the very bottom of Blackrock Depths. It is the heart of Blackrock Mountain and the exact spot where, long ago in a desperate bid to turn the tide of the dwarven civil war, Emperor Thaurissan summoned the elemental Firelord, Ragnaros, into the world. Though the firelord is incapable of straying far from the blazing Core, it is believed that his elemental minions command the Dark Iron dwarves, who are in the midst of creating armies out of living stone. The burning lake where Ragnaros lies sleeping acts as a rift connecting to the plane of fire, allowing the malicious elementals to pass through. Chief among Ragnaros' agents is Majordomo Executus - for this cunning elemental is the only one capable of calling the Firelord from his slumber.\",\nBackground=M..\"raids\\\\mc\\\\background\",\nGridBackground=M..\"raids\\\\mc\\\\grid-background\",\nMapId=11,\nIconScale=0.9,\nMinLevel=58,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=38.3,MapCoordinateY=36.1,MapZoneId=6},{MapContinentId=14,MapCoordinateX=66.5,MapCoordinateY=29.3,MapZoneId=1}},\nType=T.Raid,\nKey=\"MC\",\nBosses={\n{Id=\"52145\",Name=\"Incindis\",Story=\"Documentation regarding Incindis is remarkably scarce, noting him only as a formidable resident of the Molten Core.\",Portrait=M..\"raids\\\\mc\\\\incindis-portrait\",Frame=M..\"raids\\\\mc\\\\incindis-frame\",MapCoordinateX=55.1,MapCoordinateY=11.1,L=\"16812:25,16826:25,16839:25,16860:25,16849:25,16862:25,17077:5,18861:5,18870:5,18872:5,18875:5,18878:5,18879:5,19145:5,19146:5,19147:5,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,58205:20,58206:20,58207:20,58208:20,58209:20\"},\n{Id=\"12118\",Name=\"Lucifron\",Story=\"Among the ranks of the flamewakers, overseers and their guards constantly jockey for higher status among the hierarchy of elementals in hopes of gaining favor with Ragnaros. Lucifron is no exception. He has clashed with Gehennas on several occasions, particularly during their incarceration within the Elemental Plane. This rivalry has now extended to the Molten Core where Lucifron quietly waits for his opportunity to capitalize on any weakness shown by the other flamewakers. Lucifron, and his two Flamewaker Protector guards, can be found watching over the enormous core hound Magmadar, favored pet of Ragnaros.\",Portrait=M..\"raids\\\\mc\\\\lucifron-portrait\",Frame=M..\"raids\\\\mc\\\\lucifron-frame\",MapCoordinateX=63.6,MapCoordinateY=44.9,L=\"16665:100,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16805:30,16863:30,17077:4,18861:4,18870:4,18872:4,18875:4,18878:4,18879:4,19145:4,19146:4,19147:4,16800:20,16829:20,16837:20,16859:20,17109:20\"},\n{Id=\"11982\",Name=\"Magmadar\",Story=\"A terrifying behemoth composed of igneous rock and roiling magma, Magmadar serves as the origin of the core hounds that roam the earthen halls of Molten Core. Favored among Ragnaros's pets, Magmadar is protected by the flamewaker Lucifron and surrounded by vicious packs of ravenous hounds. It is said that while Ragnaros was imprisoned in the Elemental Plane, the Firelord would feed the remains of his captured enemies to the eagerly awaiting twin maws of Magmadar. As a result, the hound grew strong and loyal, and even now Magmadar's savage ferocity remains uncontested.\",Portrait=M..\"raids\\\\mc\\\\magmadar-portrait\",Frame=M..\"raids\\\\mc\\\\magmadar-frame\",MapCoordinateX=67,MapCoordinateY=32.8,L=\"18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16796:20,16810:20,16814:20,16822:20,17069:20,16835:17,16843:17,16847:17,16855:17,16867:17,17065:17,17073:20,18203:20,18820:5,18821:5,18822:5,18823:5,18824:5,18829:5,18861:5,19136:5,19142:5,19143:5,19144:5\"},\n{Id=\"12057\",Name=\"Garr\",Story=\"As one of the two chief lieutenants serving under Ragnaros, Garr plays a key role in the current success of the Firelord and his spreading influence. Garr, like Baron Geddon, holds half of Bindings of the Windseeker, which contains the remaining essence of Thunderaan, Prince of Air. Tales say that after centuries of partnership, Geddon became suspicious of Garr and felt the elemental sought both halves of the talisman. Thus, relations between the two powers are strained. Both Garr and Baron Geddon draw their considerable might from the blazing runes carved deep into the floor of Molten Core.\",Portrait=M..\"raids\\\\mc\\\\garr-portrait\",Frame=M..\"raids\\\\mc\\\\garr-frame\",MapCoordinateX=32.7,MapCoordinateY=74.8,L=\"17782:4,18564:5,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16834:17,16842:17,16846:17,16854:17,16866:17,17066:17,16795:20,16808:20,16813:20,16821:20,17071:20,17105:20,18820:5,18821:5,18822:5,18823:5,18824:5,18829:5,18832:20,18861:5,19136:5,19142:5,19143:5,19144:5\"},\n{Id=\"12056\",Name=\"Baron Geddon\",Story=\"When Ragnaros was ripped from the Elemental Plane by the Sorcerer-Thane Thaurissan, several subjects from the Firelands followed in his wake. Baron Geddon fought against the titans and aided in the betrayal of Thunderaan, Prince of Air. The Firelord devoured the essence of the prince, but was unable to consume him entirely. Thus, the remaining energies were trapped within a talisman of elemental binding, which Ragnaros split into two perfect halves which he gave to his two lieutenants.\",Portrait=M..\"raids\\\\mc\\\\geddon-portrait\",Frame=M..\"raids\\\\mc\\\\geddon-frame\",MapCoordinateX=51.8,MapCoordinateY=80,L=\"18563:6,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16836:8,16844:30,18820:8,18821:8,18822:8,18823:8,18829:4,18861:8,19136:8,19142:8,19143:8,19144:8,16797:33,16807:33,17110:33,16856:8,18824:8\"},\n{Id=\"12264\",Name=\"Shazzrah\",Story=\"Of all the flamewakers who followed Ragnaros into the world of Azeroth, Shazzrah is the most talented in the realm of the arcane. He is aware that his colleague Baron Geddon suspects the elemental Garr of treachery. The conflict between Baron Geddon and Garr suits Shazzrah well, for in fact it is Shazzrah who seeks to posses both halves of the Talisman of Elemental Binding so that he might find a way to siphon its energies for his own use. Ragnaros was very likely aware of his underling's penchant for duplicity when he split the talisman in half and entrusted the pieces to Baron Geddon and Garr.\",Portrait=M..\"raids\\\\mc\\\\shazzrah-portrait\",Frame=M..\"raids\\\\mc\\\\shazzrah-frame\",MapCoordinateX=54.1,MapCoordinateY=85.2,L=\"18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16803:25,16811:25,16824:25,17077:2,18861:2,18870:2,18872:2,18875:2,18878:2,18879:2,19145:2,19146:2,19147:2,16801:33,16831:33,16852:33\"},\n{Id=\"12098\",Name=\"Sulfuron Harbinger\",Story=\"Among the most favored of the flamewakers, Sulfuron Harbinger is the terrifying herald of Ragnaros himself. From the infernal depths of the Molten Core, the Harbinger commands Ambassador Flamelash and the other lesser flamewakers in the outside world. Sulfuron Harbinger answers only to Executus and guards the rune of Koro, one of several runes that empower the Firelord's servants. Sulfuron Harbinger keeps Shazzrah in particular under close watch, believing that Shazzrah seeks to betray Ragnaros. Flanked by four of the Firelord's most fervid priests, the Harbinger prepares for the day when the elemental lord of fire claims the world of Azeroth for his own.\",Portrait=M..\"raids\\\\mc\\\\sulfuron-portrait\",Frame=M..\"raids\\\\mc\\\\sulfuron-frame\",MapCoordinateX=77.9,MapCoordinateY=84.9,L=\"16823:30,16868:30,17077:4,18861:4,18870:4,18872:4,18875:4,18878:4,18879:4,19145:4,19146:4,19147:4,16816:33,16848:33,17074:33\"},\n{Id=\"11988\",Name=\"Golemagg the Incinerator\",Story=\"The most feared soldiers of Ragnaros's elemental forces are the molten giants, and among them Golemagg the Incinerator is unrivaled for his sheer brutality and savage efficiency. So absolute is the molten behemoth's power that he has cowed two core ragers - offspring of the colossal beast Magmadar - which he now uses as pets. For this affront, he has earned Magmadar's eternal and unwavering ire, although the fearsome creature has yet to act on his savage impulses.\",Portrait=M..\"raids\\\\mc\\\\golemagg-portrait\",Frame=M..\"raids\\\\mc\\\\golemagg-frame\",MapCoordinateX=66,MapCoordinateY=65,L=\"17203:80,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16798:25,16809:25,16815:25,16820:25,16833:20,16841:20,16845:20,16853:20,16865:20,17072:25,17103:25,18820:2,18821:2,18822:2,18823:2,18824:2,18829:2,18842:25,18861:2,19136:2,19142:2,19143:2,19144:2\"},\n{Id=\"65020\",Name=\"Twin Golems\",Story=\"Apart from their confirmed status as guardians of the Firelord's domain, the history of the Twin Golems remains entirely unrecorded.\",Portrait=M..\"raids\\\\mc\\\\golems-portrait\",Frame=M..\"raids\\\\mc\\\\golems-frame\",MapCoordinateX=67.1,MapCoordinateY=49.6,L=\"18820:11,18821:11,18822:11,18823:11,18824:11,18829:11,18861:11,19136:11,19142:11,19143:11,19144:11,58210:17,58212:17,58215:17,58237:17,58238:17,58242:17,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,58211:25,58213:25,58239:25,58241:25,58246:100\"},\n{Id=\"57642\",Name=\"Sorcerer-Thane Thaurissan\",Story=\"Sorcerer-Thane Thaurissan was the leader of the shadowy sorcerers of the Dark Iron clan before and during the War of the Three Hammers. He was the one responsible for summoning the Firelord Ragnaros into Azeroth.\",Portrait=M..\"raids\\\\mc\\\\sorcerer-portrait\",Frame=M..\"raids\\\\mc\\\\sorcerer-frame\",MapCoordinateX=88.1,MapCoordinateY=45,L=\"18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,18820:11,18821:11,18822:11,18823:11,18824:11,18829:11,18861:11,19136:11,19142:11,19143:11,19144:11,58210:17,58212:17,58215:17,58237:17,58238:17,58242:17,58214:25,58240:25,58243:25,58244:25\"},\n{Id=\"12018\",Name=\"Majordomo Executus\",Story=\"At the top of the elemental hierarchy, just beneath Ragnaros himself, resides Majordomo Executus. This flamewaker gained his exalted status by proving to be nearly invincible in the battles that raged within the elemental plane. Rumor has it that Executus supplanted Baron Geddon, and the two have been rivals ever since. Although this rumor has yet to be confirmed, there is certainly no doubt that Ragnaros does not tolerate failure. Thus, the lesser flamewakers (and, of course, Baron Geddon) eagerly await a misstep by Executus, anticipating their chance to vie for the coveted attention of the Firelord.\",Portrait=M..\"raids\\\\mc\\\\executus-portrait\",Frame=M..\"raids\\\\mc\\\\executus-frame\",MapCoordinateX=79.3,MapCoordinateY=70.8,L=\"18806:20,18809:20,18810:20,18812:20,19140:20,18803:20,18805:20,18808:20,18811:20,19139:20,18646:50,18703:50,42178:30\"},\n{Id=\"11502\",Name=\"Ragnaros\",Story=\"Lying at the bottom of Blackrock Mountain, Ragnaros is striving to find a way home, as well as to gather his strength once again so he can burn away Azeroth and take it for his own. Meanwhile, in Sulfuron Keep and elsewhere across the Firelands, his elemental princes battle constantly for dominance. He and his dwarven minions took control of the Blackrock mountain's volcanic depths and made war on the orcs in the Upper Blackrock Spire, which served as the seat of power for Nefarian the black dragon. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain.\",Portrait=M..\"raids\\\\mc\\\\ragnaros-portrait\",Frame=M..\"raids\\\\mc\\\\ragnaros-frame\",MapCoordinateX=55.3,MapCoordinateY=60.3,L=\"17204:6,19017:100,16901:12,16909:12,16915:12,16922:12,16930:12,16938:12,16954:12,16962:12,18814:20,18815:20,18816:20,18817:20,19138:20,16946:12,17063:20,17102:20,17106:20,17107:20,19137:20,17076:8,17082:8,17104:8,92080:1,70171:100\"},\n}}\nZLDB.R[\"NAXX\"]={\nName=\"Naxxramas\",\nStory=\"Naxxramas was originally an ancient, subterranean nerubian ziggurat. During the War of the Spider, the undead Anub'arak led an army of Scourged nerubians to conquer the ziggurat for the Lich King Ner'zhul. Under Anub'arak's oversight, the Scourge then altered the structure into a potent war machine.\",\nBackground=M..\"raids\\\\naxx\\\\background\",\nGridBackground=M..\"raids\\\\naxx\\\\grid-background\",\nMapId=33,\nZoneId=1,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=41,MapCoordinateY=29.5,MapDestinationZoneId=1,MapZoneId=12}},\nType=T.Raid,\nKey=\"NAXX\",\nBosses={\n{Id=\"16028\",Name=\"Patchwerk\",Story=\"Patchwerk is one of Kel'Thuzad's most powerful abominations. His strength and speed came as a shock to those that faced him in combat. Far from a sluggish, mindless undead, Patchwerk used his immense power to pulverize any adversary with a flurry of potent, powerful attacks. When word of his existence first reached the ears of the Brotherhood, none believed the tales of an abomination with such immense speed and strength. Fewer still believed it when he fell the first time.\",Portrait=M..\"raids\\\\naxx\\\\patchwerk-portrait\",Frame=M..\"raids\\\\naxx\\\\patchwerk-frame\",MapCoordinateX=38.3,MapCoordinateY=45.7,MapId=1,L=\"22726:30,22354:33,22361:33,22368:33,22815:20,22818:20,22820:20,22960:20,22961:20\"},\n{Id=\"15931\",Name=\"Grobbulus\",Story=\"Carrying the same plague slime that flows through Naxxramas within its hulking form, Grobbulus is a flesh giant, the first successful one of its kind, created to build a formidable army capable of quickly spreading the undead plague by injecting the living ooze into the bodies of their foe. The recipient of this foul injection would usually flee to his allies, bringing them down with him.\",Portrait=M..\"raids\\\\naxx\\\\grobbulus-portrait\",Frame=M..\"raids\\\\naxx\\\\grobbulus-frame\",MapCoordinateX=47,MapCoordinateY=29.6,MapId=1,L=\"22726:30,22354:33,22361:33,22368:33,22803:20,22810:20,22967:20,22968:20,22988:20\"},\n{Id=\"15932\",Name=\"Gluth\",Story=\"The undead plague-dog Gluth sits obediently within Naxxramas, awaiting orders from his masters. Gluth's appetite is so voracious that even the living were not enough to satisfy his hunger. It is rumored that Feugen was said to feed him an army of zombies daily, which Gluth uses to knit his own decaying flesh back together, recycling the remains of undead too weak to use in combat.\",Portrait=M..\"raids\\\\naxx\\\\gluth-portrait\",Frame=M..\"raids\\\\naxx\\\\gluth-frame\",MapCoordinateX=37.9,MapCoordinateY=27,MapId=1,L=\"22726:30,22354:8,22355:8,22356:8,22358:8,22361:8,22362:8,22363:8,22365:8,22368:8,22369:8,22370:8,22372:8,22813:20,22981:20,22983:20,22994:20,23075:20\"},\n{Id=\"15928\",Name=\"Thaddius\",Story=\"Pieced together from the flesh of innocent women and children, this massive abomination dwells in one of Naxxramas' experimental laboratories, flanked by two huge wights-Stalagg and Feugen. Powerful bolts of electricity arc through the laboratory, supercharging Thaddius and his wight minions. It is said that the souls contained in Thaddius are fused together - eternally bound within that foul prison of flesh.\",Portrait=M..\"raids\\\\naxx\\\\thaddius-portrait\",Frame=M..\"raids\\\\naxx\\\\thaddius-frame\",MapCoordinateX=29,MapCoordinateY=13.3,MapId=1,L=\"22353:33,22360:33,22367:33,22801:20,22808:20,23000:20,23001:20,23070:20\"},\n{Id=\"15956\",Name=\"Anub'Rekhan\",Story=\"One of the minions raised by the Lich King was the Crypt Lord Anub'Rekhan. In life, he was one of the nerubians' most powerful spider lords. Now, he guards the doors of the Spider Wing.\",Portrait=M..\"raids\\\\naxx\\\\anubrekhan-portrait\",Frame=M..\"raids\\\\naxx\\\\anubrekhan-frame\",MapCoordinateX=54.9,MapCoordinateY=29,MapId=1,L=\"22726:30,22355:33,22362:33,22369:33,22935:20,22936:20,22937:20,22938:20,22939:20,42167:20\"},\n{Id=\"15953\",Name=\"Grand Widow Faerlina\",Story=\"Once one of the high-ranking members of the Cult of the Damned under Kel'Thuzad, in death she breeds and takes care of the seemingly endless amount of arachnids that swarm from the depths of the citadel. A master of poisons, she has a keen understanding of what makes mortals suffer. The poisons she concocts come from the spiderlings produced by Maexxna.\",Portrait=M..\"raids\\\\naxx\\\\faerlina-portrait\",Frame=M..\"raids\\\\naxx\\\\faerlina-frame\",MapCoordinateX=62.3,MapCoordinateY=23.2,MapId=1,L=\"22726:30,22355:33,22362:33,22369:33,22806:20,22940:20,22941:20,22942:20,22943:20\"},\n{Id=\"15952\",Name=\"Maexxna\",Story=\"A massive spider taken from the depths of Northrend's mountains many ages ago. She was captured within the dread citadel Naxxramas, where she gives birth to her brood. She feasts on those foolish enough to enter the necropolis, feeding her spawn with their corpses and producing spider after spider that Kel'Thuzad uses to his own foul ends.\",Portrait=M..\"raids\\\\naxx\\\\maexxna-portrait\",Frame=M..\"raids\\\\naxx\\\\maexxna-frame\",MapCoordinateX=75.9,MapCoordinateY=11.9,MapId=1,L=\"22726:30,22357:33,22364:33,22371:33,22804:20,22807:20,22947:20,22954:20,23220:20,37012:30\"},\n{Id=\"15954\",Name=\"Noth the Plaguebringer\",Story=\"Noth the Plaguebringer was once a reputable mage of Dalaran, who heard the call of the Lich King in much the same way Kel'Thuzad did. Also driven by power, he accepted the summons to serve the needs of the Scourge with his skills in necromancy and curse-weaving. However, when Noth saw that the Third War was taking numerous innocent lives, he began second-guessing his decision to join Kel'Thuzad. Kel'Thuzad swiftly dealt with Noth's growing compassion by freezing the living heart in Noth's chest.\",Portrait=M..\"raids\\\\naxx\\\\noth-portrait\",Frame=M..\"raids\\\\naxx\\\\noth-frame\",MapCoordinateX=56.5,MapCoordinateY=73.3,MapId=1,L=\"22726:30,22356:33,22363:33,22370:33,22816:14,23005:14,23006:14,23028:14,23029:14,23030:14,23031:14\"},\n{Id=\"15936\",Name=\"Heigan the Unclean\",Story=\"The mastermind behind the magic of the cauldrons that quickly spread the undead plague through Lordaeron, corrupting not just the humans but flora and fauna in the area as well. The entire wilderness surrounding Lordaeron is now referred to as \\\"the Plaguelands\\\" - thanks in no small part to Heigan's handiwork.\",Portrait=M..\"raids\\\\naxx\\\\heigan-portrait\",Frame=M..\"raids\\\\naxx\\\\heigan-frame\",MapCoordinateX=65.6,MapCoordinateY=67,MapId=1,L=\"22726:30,22356:33,22363:33,22370:33,23019:20,23033:20,23035:20,23036:20,23068:20\"},\n{Id=\"16011\",Name=\"Loatheb\",Story=\"A prime example of how the plague manifested in the local flora and fauna is the twisted fen creeper Loatheb. In a twisted mockery of the plant kingdom's natural ability to regenerate, Loatheb can summon deadly spores that quickly spread a sickening miasma that turns magical healing arts against those who wield them.\",Portrait=M..\"raids\\\\naxx\\\\loatheb-portrait\",Frame=M..\"raids\\\\naxx\\\\loatheb-frame\",MapCoordinateX=81,MapCoordinateY=56.4,MapId=1,L=\"22726:30,22352:33,22359:33,22366:33,22800:20,23037:20,23038:20,23039:20,23042:20\"},\n{Id=\"16061\",Name=\"Instructor Razuvious\",Story=\"The most feared of the Scourge’s death knight trainers, Instructor Razuvious was once the Lordaeronian knight Razuv Ivaldi, a veteran of the Horde’s siege during the Second War. In life he was a disciplined soldier, but in undeath he has become a ruthless instructor, shaping new death knights through brutality and absolute obedience. Surrounded by his loyal understudies, Razuvious enforces the will of the Scourge with unrelenting severity, forging his pupils into weapons as merciless as himself.\",Portrait=M..\"raids\\\\naxx\\\\razuvious-portrait\",Frame=M..\"raids\\\\naxx\\\\razuvious-frame\",MapCoordinateX=36.3,MapCoordinateY=66.9,MapId=1,L=\"22726:30,22358:33,22365:33,22372:33,23004:17,23009:17,23014:17,23017:17,23018:17,23219:17\"},\n{Id=\"16060\",Name=\"Gothik the Harvester\",Story=\"A master of necromancy and conjuration, Gothik is said to be able to beckon forth legions of the undead at a moment's notice. It is with his guidance that even the weakest of Death Knights can raise the dead.\",Portrait=M..\"raids\\\\naxx\\\\gothik-portrait\",Frame=M..\"raids\\\\naxx\\\\gothik-frame\",MapCoordinateX=49.4,MapCoordinateY=72.3,MapId=1,L=\"22726:30,22358:33,22365:33,22372:33,23020:20,23021:20,23023:20,23032:20,23073:20\"},\n{Id=\"16065\",Name=\"The Four Horsemen\",Story=\"The Four Horsemen are extremely powerful elite death knights originally created by the lich Kel'Thuzad to serve as his royal guard. The most feared and powerful soldiers of all the Scourge, the Archlich considered them his greatest creation.\",Portrait=M..\"raids\\\\naxx\\\\horsemen-portrait\",Frame=M..\"raids\\\\naxx\\\\horsemen-frame\",MapCoordinateX=28.8,MapCoordinateY=85.8,MapId=1,L=\"22349:33,22350:33,22351:33,22726:30,22691:1,22809:1,22811:1,23025:1,23027:1,23071:1\"},\n{Id=\"15989\",Name=\"Sapphiron\",Story=\"Sapphiron is an ancient agent of the blue dragonflight who was killed by Arthas Menethil and raised as a powerful frost wyrm. He was subsequently sent to the halls of Naxxramas, where he guards the inner sanctum of the citadel's dread master, Kel'Thuzad.\",Portrait=M..\"raids\\\\naxx\\\\sapphiron-portrait\",Frame=M..\"raids\\\\naxx\\\\sapphiron-frame\",MapCoordinateX=56.2,MapCoordinateY=67.2,MapId=2,L=\"23040:10,23041:10,23043:10,23045:10,23046:10,23047:10,23048:10,23049:10,23050:10,23242:10,23545:50,23547:50,23548:50,23549:50\"},\n{Id=\"15990\",Name=\"Kel'Thuzad\",Story=\"Once a prominent mage of the Kirin Tor, Kel'Thuzad was seduced by the dark whispers of the Lich King. Now a tremendously powerful Archlich, he serves as the ruler of Naxxramas and the commander of the Scourge in Lordaeron, zealously carrying out his master's will to extinguish all life on Azeroth.\",Portrait=M..\"raids\\\\naxx\\\\kelthuzad-portrait\",Frame=M..\"raids\\\\naxx\\\\kelthuzad-frame\",MapCoordinateX=36.4,MapCoordinateY=22.6,MapId=2,L=\"22520:100,22798:9,22799:9,22802:9,22812:9,22819:9,22821:9,23053:9,23054:9,23056:9,23057:9,23577:9,55581:33,55582:33,55583:33,36666:1,81283:100\"},\n}}\nZLDB.R[\"ONY\"]={\nName=\"Onyxia's Lair\",\nStory=\"Onyxia built the lair. The entrance to the lair was carved to look like the maw of the broodmother herself, with its inner pathway being magma-lined and the ground cracked, glowing with fire from beneath. The arching stone ceiling groans and shifts, creating constant rockfalls. The walls spill lava where the heat can't be contained.\",\nBackground=M..\"raids\\\\ony\\\\background\",\nGridBackground=M..\"raids\\\\ony\\\\grid-background\",\nMapId=16,\nIconScale=1.2,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=53.4,MapCoordinateY=77,MapZoneId=10}},\nType=T.Raid,\nKey=\"ONY\",\nBosses={\n{Id=\"axelus\",Name=\"Broodcommander Axelus\",Story=\"The brood does not speak of its commanders to outsiders - Broodcommander Axelus least of all.\",Portrait=M..\"raids\\\\ony\\\\axelus-portrait\",Frame=M..\"raids\\\\ony\\\\axelus-frame\",MapCoordinateX=46.6,MapCoordinateY=76.6,L=\"33087:8,33089:8,33098:8,33157:8,33149:8,33150:8,33151:8,33152:8,33153:8,33154:8,33155:8,33156:8\"},\n{Id=\"10184\",Name=\"Onyxia\",Story=\"Onyxia is the daughter of Deathwing and his Prime Consort Sintharia and the broodmother of the black dragonflight on Azeroth. Like her father and her older twin brother Nefarian, she has a human guise, appearing as the Stormwindian noblewoman Lady Katrana Prestor, though she is believed to have several other humanoid guises as well.\",Portrait=M..\"raids\\\\ony\\\\onyxia-portrait\",Frame=M..\"raids\\\\ony\\\\onyxia-frame\",MapCoordinateX=70.8,MapCoordinateY=25,Abilities={{Effect=\"Initially, Onyxian Whelps will only spawn when the nests of eggs are touched or knocked into.\\\n\\\nAfter Onyxia flies, Onyxian Whelps will start to occasionally spawn and attack the raid.\",Icon=\"INV_Misc_Head_Dragon_Black\",Id=\"11262\",Name=\"Onyxian Whelp\"},{Effect=\"This stage lasts until Onyxia is at 65% health.\",Id=\"onyxiastage1\",Name=\"Stage One: Ground Phase\",SubAbilities={{Effect=\"Onyxia sweeps her tail in a cone behind her, dealing 600 to 1,000 damage and knocking back all enemies hit.\\\n\\\nTanks should slowly turn her tail towards the entry to allow the raid to stay at her sides.\",Flags={F.Tank,F.Important},Icon=\"INV_Misc_MonsterScales_05\",Id=\"15847\",Name=\"Tail Sweep\"},{Effect=\"Onyxia knocks back enemies in a cone in front, inflicting 560 to 940 damage.\\\n\\\nTanks should position themselves against the back wall to avoid flying across the room.\",Flags={F.Tank},Icon=\"INV_Misc_MonsterScales_14\",Id=\"18500\",Name=\"Wing Buffet\"},{Effect=\"Onyxia breathes fire in a frontal cone, inflicting 3050 to 4000 fire damage to all enemies positioned in front of her.\",Icon=\"Spell_Fire_Fire\",Id=\"18435\",Name=\"Flame Breath\"}}},{Effect=\"Once Onyxia reaches 65% health, she will start walking towards the center of the room before taking flight.\\\n\\\nThis stage will continue until Onyxia is at 40% health.\",Id=\"onyxiastage2\",Name=\"Stage Two: Flying Phase\",SubAbilities={{Effect=\"Onyxia randomly targets players, inflicting 800 to 1200 fire damage to the player and anyone within an 8 yard radius.\\\n\\\nPlayers should spread out at least 8 yards apart from each other to minimize damage when Onyxia is not casting Deep Breath.\",Flags={F.Important},Icon=\"Spell_Fire_FlameBolt\",Id=\"18392\",Name=\"Fireball\"},{Effect=\"Onyxia will occasionally fly in a line through the middle of the room while breathing fire, dealing heavy fire damage to anyone in her path.\\\n\\\nPlayers must run to any side of whichever way she is facing to avoid taking damage.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Fire_Fire\",Id=\"17086\",Name=\"Deep Breath\"},{Effect=\"When Onyxia takes off, Cindarion lands. He will be active for the entire stage until he is killed.\",Flags={F.Tank,F.Important},Icon=\"INV_Misc_Head_Dragon_Black\",Id=\"cindarion\",Name=\"Cindarion\",SubAbilities={{Effect=\"Cindarion casts flame breath, dealing fire damage to all enemies in front of him.\",Flags={F.Deadly},Icon=\"Spell_Fire_Fire\",Id=\"cindarionflamebreath\",Name=\"Flame Breath\"}}}}},{Effect=\"Once Onyxia reaches 40% health, she will land back on the ground.\",Id=\"onyxiastage3\",Name=\"Stage Three: Ground Phase\",SubAbilities={{Effect=\"Onyxia sweeps her tail in a cone behind her, dealing 600 to 1,000 damage and knocking back all enemies hit.\\\n\\\nTanks should slowly turn her tail towards the entry to allow the raid to stay at her sides.\",Flags={F.Tank,F.Important},Icon=\"INV_Misc_MonsterScales_05\",Id=\"15847\",Name=\"Tail Sweep\"},{Effect=\"Onyxia knocks back enemies in a cone in front, inflicting 560 to 940 damage.\\\n\\\nTanks should position themselves against the back wall to avoid flying across the room.\",Flags={F.Tank},Icon=\"INV_Misc_MonsterScales_14\",Id=\"18500\",Name=\"Wing Buffet\"},{Effect=\"Onyxia breathes fire in a frontal cone, inflicting 3050 to 4000 fire damage to all enemies positioned in front of her.\",Icon=\"Spell_Fire_Fire\",Id=\"18435\",Name=\"Flame Breath\"},{Effect=\"Onyxia will cast Fear on everyone in intervals.\\\n\\\nPriests can use fear ward to help mitigate the fears on important members.\",Flags={F.Important},Icon=\"spell_shadow_charm\",Id=\"18431\",Name=\"Bellowing Roar\"},{Effect=\"Two Onyxian Hatcher appears after Onyxia lands back on the ground, assisting her for the rest of the fight.\",Flags={F.Tank,F.Important},Id=\"onyxianhatcher\",Name=\"Onyxian Hatcher\",SubAbilities={{Effect=\"Onyxian Hatcher casts rains of fire that appears around the room, dealing heavy fire damage to any enemies inside.\",Flags={F.Deadly,F.Important},Icon=\"spell_shadow_rainoffire\",Id=\"rainoffire\",Name=\"Rain of Fire\"}}}}}},L=\"17966:100,18423:100,18705:40,18813:25,16900:11,16908:11,16914:11,16921:11,16929:11,16939:11,16947:11,16955:11,16963:11,30017:2,17064:8,17068:8,17075:8,17067:25,17078:25,18205:25\"},\n}}\nZLDB.R[\"TH\"]={\nName=\"Timbermaw Hold\",\nStory=\"As ancient as Kalimdor itself, this enigmatic labyrinthine network of tunnels and caves beneath Mount Hyjal has been the home of the Furbolgs since well before the Sundering. Its halls are sacred among the tribes, a place of worship to their progenitors, the twin gods Ursoc and Ursol. Nowadays however, only wafts of putrid vapors escape the rotten caverns and whispers of venerating a foul god echo throughout Timbermaw Hold...\",\nBackground=M..\"raids\\\\th\\\\background\",\nGridBackground=M..\"raids\\\\th\\\\grid-background\",\nMapId=44,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=1,MapCoordinateX=16.8,MapCoordinateY=43.2,MapZoneId=30}},\nType=T.Raid,\nKey=\"TH\",\nBosses={\n{Id=\"karrsh\",Name=\"Karrsh the Sentinel\",Story=\"A sentinel stands watch over something worth protecting. What Karrsh guards now in the dark of Timbermaw Hold, no one has returned to report.\",Portrait=M..\"raids\\\\th\\\\karrsh-portrait\",Frame=M..\"raids\\\\th\\\\karrsh-frame\",MapCoordinateX=31,MapCoordinateY=73.5,L=\"33346:13,33345:13,33344:13,33343:13,33342:13,33341:13,33334:13,33333:13,33242:17,33241:17,33240:17,33239:17,33238:17,33237:17\"},\n{Id=\"rotgrowl\",Name=\"Rotgrowl\",Story=\"No title. No history. Only a name that the tunnels seem to have grown around, as if it were always there.\",Portrait=M..\"raids\\\\th\\\\rotgrowl-portrait\",Frame=M..\"raids\\\\th\\\\rotgrowl-frame\",MapCoordinateX=15.1,MapCoordinateY=59.3,L=\"135:2,33346:13,33345:13,33344:13,33343:13,33342:13,33341:13,33334:13,33333:13,33248:17,33247:17,33246:17,33245:17,33244:17,33243:17\"},\n{Id=\"loktanag\",Name=\"Loktanag the Vile\",Story=\"The epithet was given by someone. Under what circumstances, and whether they lived to regret the proximity, is not recorded.\",Portrait=M..\"raids\\\\th\\\\loktanag-portrait\",Frame=M..\"raids\\\\th\\\\loktanag-frame\",MapCoordinateX=14.7,MapCoordinateY=50,L=\"33249:13,33250:13,33251:13,33252:13,42290:2,42289:2,33256:13,33255:13,33254:13,33253:13\"},\n{Id=\"trioch\",Name=\"Trioch the Devourer\",Story=\"What Trioch has consumed, and what remains of it, are questions Timbermaw Hold has swallowed along with everything else.\",Portrait=M..\"raids\\\\th\\\\trioch-portrait\",Frame=M..\"raids\\\\th\\\\trioch-frame\",MapCoordinateX=54.7,MapCoordinateY=64.7,L=\"42291:2,33293:13,33292:13,33291:13,33290:13,33289:13,33288:13,33287:13,33088:13\"},\n{Id=\"selenaxx\",Name=\"Selenaxx Foulheart\",Story=\"Whether the heart was always foul, or became so within these walls, the caverns do not distinguish between the two.\",Portrait=M..\"raids\\\\th\\\\selenaxx-portrait\",Frame=M..\"raids\\\\th\\\\selenaxx-frame\",MapCoordinateX=45.7,MapCoordinateY=58.4,L=\"42190:2,42188:2,33286:13,33285:13,33284:13,33283:13,33282:13,33281:13,33280:13,33279:13\"},\n{Id=\"ormanos\",Name=\"Ormanos the Cracked\",Story=\"Something broke. The hold remembers neither what it was, nor what broke it - only that Ormanos remained after.\",Portrait=M..\"raids\\\\th\\\\ormanos-portrait\",Frame=M..\"raids\\\\th\\\\ormanos-frame\",MapCoordinateX=32.4,MapCoordinateY=36.3,L=\"42292:2,42189:2,33263:13,33262:13,33261:13,33260:13,33259:13,33258:13,33257:13,33091:13\"},\n{Id=\"partath\",Name=\"Chieftain Partath\",Story=\"He leads what the hold has become. Whether he led it there, or merely inherited the ruin, is a distinction the tunnels do not make.\",Portrait=M..\"raids\\\\th\\\\partath-portrait\",Frame=M..\"raids\\\\th\\\\partath-frame\",MapCoordinateX=22.2,MapCoordinateY=8.4,L=\"33271:13,33272:13,33273:13,33274:13,33275:13,33276:13,33277:13,33278:13,42287:2,42288:2\"},\n{Id=\"kronn\",Name=\"Archdruid Kronn\",Story=\"The title of Archdruid speaks to what Kronn once devoted himself to. The vapors drifting from Timbermaw Hold speak to what he devotes himself to now.\",Portrait=M..\"raids\\\\th\\\\kronn-portrait\",Frame=M..\"raids\\\\th\\\\kronn-frame\",MapCoordinateX=42.4,MapCoordinateY=30.7,L=\"33084:13,33264:13,33265:13,33266:13,33267:13,33268:13,33269:13,33270:13,33333:13,33334:13,33341:13,33342:13,33343:13,33344:13,33345:13,33346:13,42187:2,42284:2,42285:2\"},\n{Id=\"ursol\",Name=\"Ursol\",Story=\"Ursol was a god of the wilds, twin to Ursoc, beloved among the furbolg since before the Sundering. He was many things. What he is now is something the old texts did not anticipate.\",Portrait=M..\"raids\\\\th\\\\ursol-portrait\",Frame=M..\"raids\\\\th\\\\ursol-frame\",MapCoordinateX=49.5,MapCoordinateY=37.8,L=\"42177:100,33294:18,33295:18,33296:18,33297:18,33298:18,33300:18,33301:18,33302:18,33303:18,33304:18,33299:10,33305:10,58312:8\"},\n{Id=\"perotharn\",Name=\"Peroth'arn\",Story=\"He was a night elf, once. What he became afterward has many names, and what he is now has none that anyone has yet spoken aloud.\",Portrait=M..\"raids\\\\th\\\\perotharn-portrait\",Frame=M..\"raids\\\\th\\\\perotharn-frame\",MapCoordinateX=47.8,MapCoordinateY=30.5,L=\"42295:50,42307:50,33306:18,33307:18,33308:18,33310:18,33311:18,33313:18,33314:18,33315:18,33316:18,33317:18,33309:10,33312:10\"},\n}}\nZLDB.R[\"WORLD\"]={\nName=\"Azeroth\",\nStory=\"The world of Azeroth is a realm scarred by eternal conflict and ancient magic. Beyond the confines of dungeons and fortresses, immense threats roam the open wilderness. Among these are the Dragons of Nightmare, once-noble lieutenants of the Green Dragonflight who have been driven mad by an insidious corruption. They now step through the portals of the Great Trees, intent on spreading their dark taint across the waking world. As the years went on, more and more threat emerged, making Azeroth an even more chaotic land.\",\nBackground=M..\"raids\\\\world\\\\background\",\nGridBackground=M..\"raids\\\\world\\\\grid-background\",\nMapId=0,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nType=T.Raid,\nKey=\"WORLD\",\nBosses={\n{Id=\"6109\",Name=\"Azuregos\",Story=\"Azuregos is a powerful blue dragon who is trusted by Malygos with the safekeeping of the blue dragonflight's most precious artifacts.\",Portrait=M..\"raids\\\\world\\\\azuregos-portrait\",Frame=M..\"raids\\\\world\\\\azuregos-frame\",MapCoordinateX=56.9,MapCoordinateY=86.1,MapId=1,MapZoneId=2,L=\"18704:100,17070:10,18202:10,18208:10,18541:10,18542:10,18545:10,18547:10,19130:10,19131:10,19132:10,83544:40\"},\n{Id=\"59963\",Name=\"Cla'ckora\",Story=\"Very little is recorded in the annals of Azeroth regarding Cla'ckora. Whether an ancient beast awakened from the deep or a forgotten monstrosity of a bygone era, its true nature and origins remain a complete enigma to even the most seasoned adventurers.\",Portrait=M..\"raids\\\\world\\\\clackora-portrait\",Frame=M..\"raids\\\\world\\\\clackora-frame\",MapCoordinateX=69,MapCoordinateY=9.2,MapId=1,MapZoneId=2,L=\"55494:20,55495:20,55498:20,55501:20,55504:20,55496:17,55497:17,55499:17,55500:17,55502:17,55503:17,92020:5\"},\n{Id=\"92213\",Name=\"Concavius\",Story=\"Archivists and loremasters have found no definitive texts detailing the existence of Concavius. What dark forces summoned or birthed this entity is a mystery yet to be unraveled, leaving only terrifying rumors in its wake.\",Portrait=M..\"raids\\\\world\\\\concavius-portrait\",Frame=M..\"raids\\\\world\\\\concavius-frame\",MapCoordinateX=82.1,MapCoordinateY=79.9,MapId=1,MapZoneId=7,L=\"83233:1,83234:1,83237:1,83238:1,83239:1,83240:1\"},\n{Id=\"80936\",Name=\"Dark Reaver of Karazhan\",Story=\"Though the horrors of Medivh's tower are infamous, this particular dark rider leaves no trace in the histories of Deadwind Pass. Who this reaver was in life, and what specific curse binds it to the mortal plane now, is a secret lost to the arcane madness of Karazhan.\",Portrait=M..\"raids\\\\world\\\\reaver-portrait\",Frame=M..\"raids\\\\world\\\\reaver-frame\",MapCoordinateX=48.1,MapCoordinateY=75.8,MapId=2,MapZoneId=9,L=\"51769:1,51770:1,51771:1,51772:1,51773:1,51774:1,51775:1,51776:1,51777:1,51778:1,51779:1,51780:1,51781:1,51782:1,51783:1,51784:1,51785:1,51786:1,51787:1,51788:1,51789:1,51796:1,51797:1,51798:1,51799:1,51800:1\"},\n{Id=\"12397\",Name=\"Lord Kazzak\",Story=\"Kazzak is a battle-hardened doomlord and commander of Burning Legion forces. After the Third War, he remained on Azeroth in the Blasted Lands as Lord Kazzak.\",Portrait=M..\"raids\\\\world\\\\kazzak-portrait\",Frame=M..\"raids\\\\world\\\\kazzak-frame\",MapCoordinateX=36,MapCoordinateY=75.1,MapId=2,MapZoneId=7,L=\"17112:20,18204:20,18543:20,18546:20,19133:20,17111:20,17113:20,18544:20,19134:20,19135:20,16045:1,83547:1,83545:40\"},\n{Id=\"91799\",Name=\"Moo\",Story=\"Moo. Moo moo moo, moo moo moo moo moo moo moo! Moo moo moo, moo, moo moo moo moo...\",Portrait=M..\"raids\\\\world\\\\moo-portrait\",Frame=M..\"raids\\\\world\\\\moo-frame\",MapCoordinateX=50.7,MapCoordinateY=54.7,MapId=39,Abilities={{Effect=\"Moo moos.\",Flags={F.Tank,F.Deadly},Icon=\"Spell_Nature_Polymorph_Cow\",Id=\"moomoo\",Name=\"MOOOOOOOOO!\"}},L=\"51261:100,60486:25,60487:50,60489:50,60490:50\"},\n{Id=\"16184\",Name=\"Nerubian Overseer\",Story=\"While the scourge of the fallen spider-kingdom is well documented by the Explorers' League, this specific overseer operates entirely in the shadows. Its distinct directives and exact place within the nerubian hierarchy are currently undocumented.\",Portrait=M..\"raids\\\\world\\\\overseer-portrait\",Frame=M..\"raids\\\\world\\\\overseer-frame\",MapCoordinateX=9.6,MapCoordinateY=35.2,MapId=2,MapZoneId=12,L=\"83547:5,51730:1,51731:1,51732:1,51733:1,51734:1,51735:1,51736:1,51737:1,51738:1,51740:1,51739:100\"},\n{Id=\"80935\",Name=\"Ostarius\",Story=\"There are no surviving records in the great libraries of Dalaran or Ironforge that speak of Ostarius. The creature exists as a phantom in historical texts, with its motives and capabilities completely unknown to the scholars of the world.\",Portrait=M..\"raids\\\\world\\\\ostarius-portrait\",Frame=M..\"raids\\\\world\\\\ostarius-frame\",MapCoordinateX=36.5,MapCoordinateY=80.7,MapId=1,MapZoneId=24,L=\"83480:1,83481:1,83482:1,83483:1,83484:1,83532:1,83485:1,83486:1,83487:1,83488:1,83530:1,83531:1\"},\n{Id=\"14889\",Name=\"Emeriss\",Story=\"Corrupted by the insidious Nightmare within the Emerald Dream, Emeriss has become a rotting, plague-ridden mockery of her former self. The dark magic sustaining her has given her the grim ability to spread disease and raise fungal rot from the corpses of her fallen foes.\",Portrait=M..\"raids\\\\world\\\\emeriss-portrait\",Frame=M..\"raids\\\\world\\\\emeriss-frame\",MapCoordinateX=46.4,MapCoordinateY=36.1,MapId=2,MapZoneId=11,L=\"20644:100,20579:11,20580:11,20581:11,20582:11,20615:11,20616:11,20617:11,20618:11,20619:11,20599:14,20621:14,20622:14,20623:14,20624:14,65100:14,65101:14\"},\n{Id=\"14888\",Name=\"Lethon\",Story=\"Once a trusted lieutenant of Ysera, Lethon's mind was twisted by the Emerald Nightmare. His corrupted form is wreathed in dark magic, allowing him to drain the life essence from his enemies and unleash shadowy reflections of those who challenge him.\",Portrait=M..\"raids\\\\world\\\\lethon-portrait\",Frame=M..\"raids\\\\world\\\\lethon-frame\",MapCoordinateX=62.3,MapCoordinateY=23.3,MapId=2,MapZoneId=33,L=\"20644:100,20625:14,20626:14,20627:14,20628:14,20629:14,20630:14,65102:14,20579:11,20580:11,20581:11,20582:11,20615:11,20616:11,20617:11,20618:11,20619:11\"},\n{Id=\"14890\",Name=\"Taerar\",Story=\"The madness of the Nightmare has fractured Taerar's very sanity and physical form. This tormented dragon of the Green Dragonflight now possesses the terrifying ability to summon phantoms and split his essence into multiple, deadly reflections of himself during battle.\",Portrait=M..\"raids\\\\world\\\\taerar-portrait\",Frame=M..\"raids\\\\world\\\\taerar-frame\",MapCoordinateX=94.2,MapCoordinateY=35.7,MapId=1,MapZoneId=1,L=\"20644:100,20579:11,20580:11,20581:11,20582:11,20615:11,20616:11,20617:11,20618:11,20619:11,20577:17,20631:17,20632:17,20633:17,20634:17,65105:17\"},\n{Id=\"14887\",Name=\"Ysondre\",Story=\"Though Ysondre was once a benevolent guardian of the Emerald Dream, she has been driven to madness by the creeping Nightmare. She now roams the waking world, unleashing druidic magic twisted by corruption to strike down any mortals foolish enough to cross her path.\",Portrait=M..\"raids\\\\world\\\\ysondre-portrait\",Frame=M..\"raids\\\\world\\\\ysondre-frame\",MapCoordinateX=51.2,MapCoordinateY=10.9,MapId=1,MapZoneId=12,L=\"20644:100,20578:12,20635:12,20636:12,20637:12,20638:12,20639:12,65103:12,65104:12,20579:11,20580:11,20581:11,20582:11,20615:11,20616:11,20617:11,20618:11,20619:11\"},\n}}\nZLDB.R[\"ZG\"]={\nName=\"Zul'Gurub\",\nStory=\"Hundreds of years ago, Zul'Gurub served as the capital city for the Gurubashi Troll Tribe, however, it was eventually destroyed by civil war and corruption from within. Centuries later, Atal'ai Priests have reclaimed the city for their own evil deeds, with the intention to summon their Blood God, Hakkar.\",\nBackground=M..\"raids\\\\zg\\\\background\",\nGridBackground=M..\"raids\\\\zg\\\\grid-background\",\nMapId=12,\nIconScale=0.8,\nMinLevel=60,\nMaxLevel=60,\nEntrances={{MapContinentId=2,MapCoordinateX=52,MapCoordinateY=17.4,MapZoneId=29}},\nType=T.Raid,\nKey=\"ZG\",\nBosses={\n{Id=\"14517\",Name=\"High Priestess Jeklik\",Story=\"High Priestess Jeklik is the Zandalari High Priestess of the Primal Jungle God Hir'eek, the Bat. Sent to Zul'Gurub to stop Hakkar the Soulflayer, she was eventually turned by the blood god.\",Portrait=M..\"raids\\\\zg\\\\jeklik-portrait\",Frame=M..\"raids\\\\zg\\\\jeklik-frame\",MapCoordinateX=39.3,MapCoordinateY=73.3,Abilities={{Effect=\"Jeklik assumes the form of a bat until she is at 50% health.\",Id=\"jeklikstage1\",Name=\"Stage One: Bat Form\",SubAbilities={{Effect=\"Jeklik emits a piercing shriek, dealing 1,750 to 2,250 physical damage and silencing all enemies within a 30-yard radius for 10 seconds.\",Flags={F.Magic,F.Important},Icon=\"Spell_Shadow_Teleport\",Id=\"23918\",Name=\"Sonic Burst\"},{Effect=\"Jeklik charges towards an enemy between 8 and 40 yards away from her. The charge inflicts 1000 physical damage and silences its target for 5 seconds.\",Flags={F.Magic},Icon=\"Ability_Warrior_Charge\",Id=\"22911\",Name=\"Charge\"},{Effect=\"Jeklik summons a swarm of 6 to 8 bats, to help her throughout the battle.\\\n\\\nThis occurs one minute into the fight and every minute after.\",Flags={F.Tank,F.Important},Icon=\"Spell_Nature_InsectSwarm\",Id=\"5570\",Name=\"Bat Swarm\"}}},{Effect=\"Jeklik assumes her troll form when she reaches 50% health and alternates between her two spell casts.\",Id=\"jeklikstage2\",Name=\"Stage Two: Troll Form\",SubAbilities={{Effect=\"Jeklik begins casting a healing spell that restores 25% of her total health if not interrupted.\",Flags={F.Interruptible,F.Important},Icon=\"Spell_Holy_Heal\",Id=\"25807\",Name=\"Great Heal\"},{Effect=\"Jeklik channels a mind flay ability, dealing damage to a target and nearby allies if not interrupted.\",Flags={F.Interruptible,F.Heal},Icon=\"Spell_Shadow_SiphonMana\",Id=\"23953\",Name=\"Mind Flay\"},{Effect=\"Jeklik summons bat bombers that drop fire bombs on enemies, leaving burning patches on the ground that deal damage to anyone standing in them.\",Icon=\"Ability_Hunter_Pet_Bat\",Id=\"23974\",Name=\"Summon Bat Bombers\"}}}},L=\"19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19915:14,19918:14,19920:14,19923:14,19928:14,20262:14,20265:14,22711:10,22712:10,22713:10,22714:10,22715:10,22716:10,22718:10,22720:10,22721:10,22722:10\"},\n{Id=\"14507\",Name=\"High Priest Venoxis\",Story=\"High Priest Venoxis is the Zandalari High Priest of the Primal God Hethiss, the snake god. Sent to Zul'Gurub to stop Hakkar the Soulflayer, he was eventually turned by the blood god.\",Portrait=M..\"raids\\\\zg\\\\venoxis-portrait\",Frame=M..\"raids\\\\zg\\\\venoxis-frame\",MapCoordinateX=51,MapCoordinateY=54.3,Abilities={{Effect=\"Venoxis assumes his troll form until he is at 50% health.\",Id=\"venoxisstage1\",Name=\"Stage One: Troll Form\",SubAbilities={{Effect=\"Venoxis's four snake adds will start the encounter with him, helping him during the fight.\\\n\\\nThese adds should be killed before the beginning of stage two.\",Flags={F.DPS},Icon=\"Spell_Nature_GuardianWard\",Id=\"10713\",Name=\"Venoxis' Snake Adds\"},{Effect=\"Venoxis casts holy wrath, dealing 300 holy damage which increases for each enemy the spell bounces off of.\",Flags={F.Heal},Icon=\"Spell_Shadow_SiphonMana\",Id=\"23979\",Name=\"Holy Wrath\"},{Effect=\"Venoxis casts renew, healing himself for 2000 health every 3 seconds for 15 seconds.\",Icon=\"Spell_Holy_Renew\",Id=\"23895\",Name=\"Renew\"},{Effect=\"Venoxis creates an explosion of divine light, inflicting 875 to 1126 holy damage to nearby enemies.\",Flags={F.Heal},Icon=\"Spell_Holy_HolyBolt\",Id=\"23858\",Name=\"Holy Nova\"},{Effect=\"Venoxis cast holy fire, consuming an enemy in flames, dealing 2200 fire damage plus 125 fire damage every 2 seconds for 8 seconds.\",Flags={F.Heal,F.Magic},Icon=\"Spell_Holy_SearingLight\",Id=\"23860\",Name=\"Holy Fire\"}}},{Effect=\"Venoxis assumes the form of a snake when he reaches 50% health.\\\n\\\nVenoxis' damage is increased for the duration of the stage.\",Id=\"venoxisstage2\",Name=\"Stage Two: Snake Form\",SubAbilities={{Effect=\"Venoxis creates a poison cloud, dealing poison damage when stood in.\",Flags={F.Poison,F.Deadly,F.Important},Icon=\"Spell_Nature_Regenerate\",Id=\"12766\",Name=\"Poison Cloud\"},{Effect=\"Venoxis spits venom at an enemy, inflicting nature damage plus additional damage every 5 seconds for 10 seconds.\",Flags={F.Poison},Icon=\"Spell_Nature_CorrosiveBreath\",Id=\"6917\",Name=\"Venom Spit\"},{Effect=\"Venoxis spawns a parasitic serpent which attacks an enemy and poisoning them, dealing 300 nature damage every 2 seconds for 10 seconds.\",Flags={F.DPS,F.Poison},Icon=\"INV_Misc_MonsterHead_03\",Id=\"23865\",Name=\"Parasitic Serpent\"},{Effect=\"At 20% remaining health, Venoxis becomes enraged, increasing the damage he deals to his enemies significantly.\",Flags={F.Tank,F.Enrage},Icon=\"Spell_Shadow_UnholyFrenzy\",Id=\"3019\",Name=\"Enrage\"}}}},L=\"19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19900:17,19903:17,19904:17,19905:17,19906:17,19907:17,22711:10,22712:10,22713:10,22714:10,22715:10,22716:10,22718:10,22720:10,22721:10,22722:10\"},\n{Id=\"14510\",Name=\"High Priestess Mar'li\",Story=\"Mar'li is the high priestess of the spider loa, Shadra. Sent by King Rastakhan to Zul'Gurub to stop Hakkar the Soulflayer with the other loa high priests, she was eventually corrupted by the blood god.\",Portrait=M..\"raids\\\\zg\\\\marli-portrait\",Frame=M..\"raids\\\\zg\\\\marli-frame\",MapCoordinateX=48.8,MapCoordinateY=78.8,Abilities={{Effect=\"Randomly throughout the fight, Mar'li will assume her spider form, gaining new abilities.\",Flags={F.Important},Icon=\"INV_Misc_MonsterSpiderCarapace_01\",Id=\"marlispider\",Name=\"Spider Form\",SubAbilities={{Effect=\"Mar'li envelopes all enemies in a 10 yards radius with her webs, rooting them to the ground, increasing the time between their attacks by 100%, and preventing them from casting spells for 8 seconds.\\\n\\\nThe off-tank needs to be ready to generate threat instantly as this will reset every rooted player's threat.\",Flags={F.Tank,F.Deadly,F.Important},Icon=\"Spell_Nature_EarthBind\",Id=\"24110\",Name=\"Enveloping Webs\"}}},{Effect=\"After assuming her spider form, Mar'li will eventually return to her orignal troll form, regaining her standard abilities.\",Icon=\"inv_misc_head_troll_02\",Id=\"marlitroll\",Name=\"Troll Form\",SubAbilities={{Effect=\"Mar'li charges her target, dealing physical damage and stunning them.\",Icon=\"ability_warrior_charge\",Id=\"marlicharge\",Name=\"Charge\"},{Effect=\"Mar'li drains the life out of her target, draining 500 health every 1 second for 7 seconds.\",Flags={F.Magic,F.Interruptible,F.Important},Icon=\"Spell_Shadow_LifeDrain02\",Id=\"24300\",Name=\"Drain Life\"},{Effect=\"Mar'li hatches her eggs, birthing 4 Spawns of Mar'li that helps her throughout the fight.\\\n\\\nThese spiders need to be dealt with as soon as possible as they will grow stronger as the fight goes on.\",Flags={F.DPS},Icon=\"inv_egg_04\",Id=\"marliadds\",Name=\"Spawns of Mar'li\"},{Effect=\"Mar'li shoots poison to all enemies in a 30 yards range, dealing 375 immediate nature damage and 290 periodic damage every 2 seconds for 10 seconds.\",Flags={F.Poison},Icon=\"Spell_Nature_CorrosiveBreath\",Id=\"24099\",Name=\"Poison Bolt Volley\"}}}},L=\"19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19871:17,19919:17,19925:17,19927:17,19930:17,20032:17,22711:10,22712:10,22713:10,22714:10,22715:10,22716:10,22718:10,22720:10,22721:10,22722:10,81003:10\"},\n{Id=\"11382\",Name=\"Bloodlord Mandokir\",Story=\"Bloodlord Mandokir is a powerful jungle troll and leader of the Gurubashi tribe. His constant companion is his raptor mount, Ohgan. He serves the evil god Hakkar the Soulflayer in Zul'Gurub along with the rest of his tribe.\",Portrait=M..\"raids\\\\zg\\\\mandokir-portrait\",Frame=M..\"raids\\\\zg\\\\mandokir-frame\",MapCoordinateX=62.4,MapCoordinateY=69.6,Abilities={{Effect=\"Ohgan also becomes enraged when Mandakir is attacked, defending his master until death.\",Icon=\"Ability_Mount_Raptor\",Id=\"ohgan\",Name=\"Ohgan\",SubAbilities={{Effect=\"Ohgan sunders his target's armor, increasing the amount of damage they receive for every stack of Sunder Armor they are afflicted with.\",Flags={F.Tank},Icon=\"ability_warrior_sunder\",Id=\"ohgansunder\",Name=\"Sunder Armor\"}}},{Icon=\"INV_Misc_Head_Troll_01\",Id=\"mandokir\",Name=\"Mandokir\",SubAbilities={{Effect=\"Mandokir gazes threateningly at a random enemy. If the targeted enemy casts any spell, Mandokir will charge them, inflicting heavy damage.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Shadow_Charm\",Id=\"24314\",Name=\"Threatening Gaze\"},{Effect=\"Mandokir whirlwind into the enemies, dealing damage to every one of them in melee range.\",Flags={F.Deadly},Icon=\"Ability_Whirlwind\",Id=\"mandokirwhirlwind\",Name=\"Whirlwind\"},{Effect=\"Mandokir cleaves, dealing physical damage to all the enemies in front of him.\",Icon=\"Ability_Warrior_Cleave\",Id=\"mandokircleave\",Name=\"Cleave\"},{Effect=\"Mandokir charges at an enemy, dealing physical damage to them and stunning them for 2 seconds.\",Icon=\"Ability_Warrior_Charge\",Id=\"24408\",Name=\"Charge\"},{Effect=\"Every time three player gets resurrected by a Chained Spirit, Mandokir levels up, increasing the amount of damage he deals and reducing the amount of damage he receives.\",Flags={F.Important},Icon=\"Spell_Holy_InnerFire\",Id=\"mandokirlevelup\",Name=\"Level Up\"},{Effect=\"If Ohgan dies before Mandokir does, Mandokir becomes enraged for 1 minute, increasing the damage he deals to his enemies.\",Flags={F.Deadly,F.Enrage},Icon=\"Ability_BullRush\",Id=\"mandokirenrage\",Name=\"Enrage\"}}}},L=\"19872:2,22637:100,19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19863:8,19866:8,19867:8,19869:8,19870:8,19873:8,19874:8,19877:8,19878:8,19893:8,19895:8,20038:8\"},\n{Id=\"15082\",Name=\"Edge of Madness\",Story=\"Nearly nothing is known about the Edge of Madness, only the rumor that if you were to do an unknown invocation properly, one out of four possible legendary troll would be summoned...\",Portrait=M..\"raids\\\\zg\\\\edge-portrait\",Frame=M..\"raids\\\\zg\\\\edge-frame\",MapCoordinateX=59.8,MapCoordinateY=46.3,Abilities={{Icon=\"INV_Misc_Head_Troll_01\",Id=\"grilek\",Name=\"Gri'lek\",SubAbilities={{Effect=\"Throughout the fight, Gri'lek will turn into an avatar, increasing his size and damage significantly but also reducing his speed. He will then start pursuing a random enemy regardless of threat.\\\n\\\nThe targeted player must run away for the duration of the ability.\",Flags={F.Deadly,F.Important},Icon=\"Ability_Creature_Cursed_05\",Id=\"24646\",Name=\"Avatar\"},{Effect=\"Gri'lek creates ground tremors, stunning every enemies in a 20 yards radius for 2 seconds.\",Icon=\"Spell_Nature_Earthquake\",Id=\"6524\",Name=\"Ground Tremor\"},{Effect=\"Gri'lek roots an enemy, making them unable to move.\",Flags={F.Magic},Icon=\"Spell_Nature_StrangleVines\",Id=\"grilekroot\",Name=\"Entangling Roots\"}}},{Icon=\"Ability_Stealth\",Id=\"renataki\",Name=\"Renataki\",SubAbilities={{Effect=\"Renataki vanishes, preventing enemies from being able to see him. Once he reappears, he will ambush a random enemy, dealing heavy damage.\\\n\\\nPlayers need to find Renataki before he reappears. Use aoe abilities to try and break his stealth.\",Flags={F.Deadly,F.Important},Icon=\"Ability_Vanish\",Id=\"24699\",Name=\"Vanish\"},{Effect=\"Renataki enrages, increasing the damage he deals to his enemies.\",Flags={F.Enrage},Icon=\"spell_shadow_unholyfrenzy\",Id=\"renatakienrage\",Name=\"Enrage\"},{Effect=\"Renataki gouges an enemy, incapacitating them.\",Icon=\"ability_gouge\",Id=\"renatakigouge\",Name=\"Gouge\"}}},{Icon=\"Spell_Shadow_Metamorphosis\",Id=\"hazzarah\",Name=\"Hazza'rah\",SubAbilities={{Effect=\"Hazza'rah casts a chain mana burn, inflicting heavy mana and health point damage to enemies in his vicinity.\\\n\\\nHunter and warlocks need to keep draining the mana of Hazza'rah as he will otherwise keep casting this ability.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Shadow_ManaBurn\",Id=\"26046\",Name=\"Chain Mana Burn\"},{Effect=\"Hazza'rah summons 3 nightmares illusions that will assist him throughout the fight.\\\n\\\nDamage dealers must instantly target these adds as they have very little health but deal a lot of damage.\",Flags={F.DPS,F.Deadly,F.Important},Icon=\"Spell_Fire_SealOfFire\",Id=\"24729\",Name=\"Summon Nightmare Illusions\"},{Effect=\"Hazza'rah puts to sleep all enemies currently attacking him.\\\n\\\nShamans can use tremor totems to wake up their allies.\",Icon=\"Spell_Nature_Sleep\",Id=\"24664\",Name=\"Sleep\"}}},{Icon=\"Spell_Nature_Lightning\",Id=\"wushoolay\",Name=\"Wushoolay\",SubAbilities={{Effect=\"Wushoolay creates a lightning bolt that chains between all enemies in from of him.\",Icon=\"Spell_Nature_ChainLightning\",Id=\"23106\",Name=\"Chain Lightning\"},{Effect=\"Wushoolay creates a lightning cloud. All enemies caught inside of the cloud's striking radius will be dealt every damage.\\\n\\\nPlayers need to move out of the cloud immediately as it deals heavy damage.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Nature_CallStorm\",Id=\"26550\",Name=\"Lightning Cloud\"}}}},L=\"19961:43,19962:43,19967:45,19968:40,19963:45,19964:40,19965:45,19993:40\"},\n{Id=\"15114\",Name=\"Gahz'ranka\",Story=\"It is said that if a skilled fisherman were to cast his hook with a very specific bait at Pagle's Pointe, then a terrible creature would emerge from the water to devour them...\",Portrait=M..\"raids\\\\zg\\\\gahzranka-portrait\",Frame=M..\"raids\\\\zg\\\\gahzranka-frame\",MapCoordinateX=55.8,MapCoordinateY=36.1,Abilities={{Effect=\"Gahz'ranka inflicts 850 frost damage to enemies in a cone in front him, stealing their mana and reducing their movement speed for 5 seconds.\",Icon=\"Spell_Frost_FrostNova\",Id=\"21099\",Name=\"Frost Breath\"},{Effect=\"Gahz'ranka slams all target in front of him, dealing 250 physical damage and knocking them back.\",Icon=\"Ability_Devour\",Id=\"24326\",Name=\"Gahz'ranka Slam\"},{Effect=\"Gahz'ranka creates a massive geyser, lauching enemies into the air.\\\n\\\nPlayers should aim to land in the water to avoid taking unnecessary damage.\",Flags={F.Deadly,F.Important},Icon=\"Spell_Frost_SummonWaterElemental\",Id=\"22421\",Name=\"Massive Geyser\"}},L=\"19944:25,19945:25,19946:25,19947:25,22739:15\"},\n{Id=\"14509\",Name=\"High Priest Thekal\",Story=\"High Priest Thekal is the Zandalari High Priest of Shirvallah, the tiger loa. Sent to Zul'Gurub to stop Hakkar the Soulflayer, he was eventually turned by the blood god.\",Portrait=M..\"raids\\\\zg\\\\thekal-portrait\",Frame=M..\"raids\\\\zg\\\\thekal-frame\",MapCoordinateX=64.3,MapCoordinateY=34.7,Abilities={{Icon=\"Spell_Nature_Lightning\",Id=\"lorkhan\",Name=\"Zealot Lor'Khan\",SubAbilities={{Effect=\"Lor'Khan casts a great heal on himself or an ally, healing them for 69375 health.\",Flags={F.Interruptible,F.Important},Icon=\"Spell_Holy_Heal\",Id=\"25807\",Name=\"Great Heal\"},{Effect=\"Lor'Khan surrounds himself with a lightning shield, returning some of the damage he takes back to the attacker.\",Icon=\"Spell_Nature_LightningShield\",Id=\"23552\",Name=\"Lightning Shield\"},{Effect=\"Lor'Khan disarms his target, forcing them to stop wielding their weapon for 6 seconds.\",Icon=\"Ability_Warrior_Disarm\",Id=\"22691\",Name=\"Disarm\"},{Effect=\"Lor'Khan and his allies are overtaken by bloodlust, increasing their attack speed by 75% for 30 seconds.\",Icon=\"Spell_Nature_BloodLust\",Id=\"24185\",Name=\"Bloodlust\"}}},{Icon=\"Ability_Stealth\",Id=\"zath\",Name=\"Zealot Zath\",SubAbilities={{Effect=\"Zath does sweeping strikes, inflicting extra damage on another target for his next melee attack.\",Icon=\"Ability_Rogue_SliceDice\",Id=\"26654\",Name=\"Sweeping Strikes\"},{Effect=\"Zath gouges his target, incapacitating them.\",Flags={F.Tank,F.Important},Icon=\"Ability_Gouge\",Id=\"24698\",Name=\"Gouge\"},{Effect=\"Zath blinds his target, causing to wander around confused for up to 10 seconds.\",Flags={F.Tank,F.Important},Icon=\"Spell_Shadow_MindSteal\",Id=\"21060\",Name=\"Blind\"},{Effect=\"Zath kicks his target, dealing physical damage and interrupting any spell currently being cast for 6 seconds.\",Icon=\"Ability_Kick\",Id=\"27613\",Name=\"Kick\"}}},{Effect=\"Thekal assumes his troll form for the duration of the stage up until him and all adds are dead at the same time.\",Name=\"Stage One: Troll Form\",SubAbilities={{Effect=\"Thekal starts the fight with Zealot Lor'Khan, Zealot Zath and 2 Zulian tigers.\\\n\\\nBoth zealots need to be tanked while the 2 tigers can easily be killed.\\\n\\\nThekal, Lor'Khan, and Zath all need to die around the same time as they will otherwise resurrect each other.\",Flags={F.Tank,F.Important},Icon=\"Ability_Mount_JungleTiger\",Id=\"thekaladds\",Name=\"Thekal's Adds\"},{Effect=\"Thekal silences a random enemy, preventing them from casting any spells for 3 seconds.\",Flags={F.Magic},Icon=\"Spell_Holy_Silence\",Id=\"27559\",Name=\"Silence\"},{Effect=\"Thekal cleaves his current target, inflicting 150% weapon damage and leaving the target wounded, reducing the effectiveness of any healing by 50% for 5 seconds.\",Flags={F.Tank,F.Important},Icon=\"ability_warrior_savageblow\",Id=\"22859\",Name=\"Mortal Cleave\"}}},{Effect=\"Thekal gets resurrected ands assumes the form of a tiger for the duration of the stage up until his actual death.\",Name=\"Stage Two: Tiger Form\",SubAbilities={{Effect=\"Thekal punches every enemies in a 45 yards radius, dealing 850 physical damage and knocking them back.\\\n\\\nForce punch also resets the threat. One of the tank that isn't currently tanking needs to be ready to pull aggro.\",Flags={F.Tank},Icon=\"INV_Gauntlets_31\",Id=\"24189\",Name=\"Force Punch\"},{Effect=\"Thekal summons 2 Zulian tigers, assisting him for the duration of the fight.\\\n\\\nJust like the Zulian tigers in stage one, these tigers can easily be killed and should be prioritized.\",Icon=\"Ability_Mount_JungleTiger\",Id=\"thekaltigers\",Name=\"Summon Tigers\"},{Effect=\"Thekal charges an enemy, dealing damage and stunning them.\",Icon=\"Ability_Warrior_Charge\",Id=\"thekalcharge\",Name=\"Charge\"},{Effect=\"Thekal goes into a frenzy, increasing his size and his attack speed by 50%.\\\n\\\nHunters can use Tranquilizing Shot to remove frenzy from Thekal.\",Icon=\"Ability_Druid_ChallangingRoar\",Id=\"thekalfrenzy\",Name=\"Frenzy\"},{Effect=\"At 20% health remaining, Thekal becomes enraged, increasing the damage he deals to his enemies.\",Flags={F.Enrage},Icon=\"Spell_Shadow_UnholyFrenzy\",Id=\"thekalenrage\",Name=\"Enrage\"}}}},L=\"19902:2,19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19896:14,19897:14,19898:14,19899:14,19901:14,20260:14,20266:14,22711:10,22712:10,22713:10,22714:10,22715:10,22716:10,22718:10,22720:10,22721:10,22722:10\"},\n{Id=\"14515\",Name=\"High Priestess Arlokk\",Story=\"High Priestess Arlokk is the Zandalari High Priestess of the Primal God Bethekk, the panther goddess. Sent to Zul'Gurub to stop Hakkar the Soulflayer, she was eventually turned by the blood god.\",Portrait=M..\"raids\\\\zg\\\\arlokk-portrait\",Frame=M..\"raids\\\\zg\\\\arlokk-frame\",MapCoordinateX=47.6,MapCoordinateY=20.8,Abilities={{Effect=\"Arlokk periodically summons stealthed panthers from the pens to attack players.\\\n\\\nWhile she is in troll form, off-tanks should control the panthers as damage dealers focuses on Arlokk.\\\n\\\nWhen Arlokk vanishes, players should shift priority to eliminating the active panthers.\\\n\\\nUpon her death, all remaining panthers will unstealth and attack the raid.\",Flags={F.Tank},Icon=\"Ability_Mount_BlackPanther\",Id=\"arlokkadds\",Name=\"Stealthed Panthers\"},{Effect=\"Arlokk assumes her troll form, which she begins the encounter in.\\\n\\\nShe alternates between troll and panther forms throughout the fight, with transitions occurring more rapidly as the encounter progresses.\",Flags={F.DPS},Icon=\"inv_misc_head_troll_02\",Id=\"arlokktroll\",Name=\"Troll Form\",SubAbilities={{Effect=\"Arlokk gouges a target, inflicting 20 damage and stunning them for up to 4 sec.\\\n\\\nIf the tank is gouged, the off-tank should taunt Arlokk. The main tank can taunt her back once they're back in control.\",Flags={F.Tank},Icon=\"Ability_Gouge\",Id=\"12540\",Name=\"Gouge\"}}},{Effect=\"Arlokk vanishes and assumes her panther form. \\\n\\\nShe alternates between troll and panther forms throughout the fight, with transitions occurring more rapidly as the encounter progresses.\",Icon=\"Ability_Mount_BlackPanther\",Id=\"arlokkpanther\",Name=\"Panther Form\",SubAbilities={{Effect=\"While Arlokk is in stealth, she can mark a random player which causes every panther to focus on the marked target.\",Flags={F.Heal},Icon=\"Ability_Hunter_SniperShot\",Id=\"24210\",Name=\"Mark of Arlokk\"},{Effect=\"When Arlokk reappears in her Panther Form, she immediately casts Whirlwind, dealing heavy AoE damage to those nearby for two seconds.\\\n\\\nMelee should wait for the Whirlwind to fade before attacking Arlokk.\",Flags={F.Deadly},Icon=\"Ability_Whirlwind\",Id=\"24236\",Name=\"Whirlwind\"}}}},L=\"19914:18,19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19909:20,19910:20,19912:20,19913:20,19922:20,22711:10,22712:10,22713:10,22714:10,22715:10,22716:10,22718:10,22720:10,22721:10,22722:10\"},\n{Id=\"11380\",Name=\"Jin'do the Hexxer\",Story=\"Jin'do is a Gurubashi jungle troll witch doctor of considerable power. He is responsible for brainwashing the Zandalari priests Jeklik, Venoxis, Mar'li, Thekal, and Arlokk into the service of Hakkar, the Loa of Blood.\",Portrait=M..\"raids\\\\zg\\\\jindo-portrait\",Frame=M..\"raids\\\\zg\\\\jindo-frame\",MapCoordinateX=31.6,MapCoordinateY=24.9,Abilities={{Effect=\"Jin'do curses a player, inflicting 175 damage every 2 seconds and spawns a Shade of Jin'do.\\\n\\\nDespite this, players are advised not to decurse this ability since only those afflicted by the curse can see and damage the Shades of Jin'do.\",Flags={F.Curse},Icon=\"Spell_Shadow_UnholyFrenzy\",Id=\"24306\",Name=\"Delusions of Jin'do\"},{Effect=\"Jin'do transforms the player with the highest threat into a frog.\",Flags={F.Interruptible},Icon=\"Spell_Shaman_Hex\",Id=\"24053\",Name=\"Hex\"},{Effect=\"Jin'do teleports a random player into the skeleton pit in the middle of the room.\",Id=\"jindoteleportskeletonpit\",Name=\"Teleport to Skeleton Pit\"},{Effect=\"Jin'do curses players, spawning shades in his image, and summons wards that heal and brainwash throughout the battle to help him.\\\n\\\nPlayers should focus on killing all adds before attacking Jin'do.\",Flags={F.Important},Id=\"jindoadds\",Name=\"Jin'do's Adds\",SubAbilities={{Effect=\"Though Shades of Jin'do are only visible to those cursed by Delusions of Jin'do, shades can attack anyone in the raid. They are also immune to AoE damage, and must be focused with single-target abilities and spells.\\\n\\\nShades of Jin'do should be the first priority add to be killed.\",Icon=\"race_troll\",Id=\"14986\",Name=\"Shade of Jin'do\",SubAbilities={{Effect=\"Shade of Jin'do's melee attacks can interrupt spellcasts.\",Icon=\"ability_meleedamage\",Id=\"jindoshademelee\",Name=\"Melee Attack\"},{Effect=\"Shades of Jin'do casts dark magic that instantly lashes enemies, inflicting shadow damage.\",Icon=\"Spell_Shadow_ShadowBolt\",Id=\"24458\",Name=\"Shadow Shock\"}}},{Effect=\"Jin'do summons a powerful healing ward that heals Jin'do for more damage than the raid can deal.\\\n\\\nAll players not actively killing a Shade of Jin'do should focus on this totem.\\\n\\\nPowerful Healing Ward should be the second priority add to be killed.\",Flags={F.Heal,F.Important},Icon=\"INV_Relics_TotemofLife\",Id=\"14987\",Name=\"Powerful Healing Ward\"},{Effect=\"Jin'do summons a brainwashing totem that mind controls players. The mind control cannot be dispelled without breaking this totem.\\\n\\\nBrain Wash Totem should be the third priority add to be killed.\",Icon=\"INV_QirajIdol_Life\",Id=\"15112\",Name=\"Brain Wash Totem\"},{Effect=\"When Jin'do teleports players into the skeleton pit, Sacrificed Trolls will spawn and attack the summoned person.\\\n\\\nUse AoE attacks to quickly free the summoned raid member.\",Icon=\"INV_Misc_Bone_02\",Id=\"14826\",Name=\"Sacrificed Troll\"}}}},L=\"22637:100,19716:11,19717:11,19718:11,19719:11,19720:11,19721:11,19722:11,19723:11,19724:11,19875:8,19884:8,19885:8,19886:8,19887:8,19888:8,19889:8,19890:8,19891:8,19892:8,19894:8,19929:8\"},\n{Id=\"14834\",Name=\"Hakkar\",Story=\"Hakkar the Soulflayer, the Blood God, is a malevolent and destructive loa notably worshipped by the Gurubashi trolls, and known in the troll pantheon as the Loa of Blood. He has taken control the Gurubashi Empire's fallen capital, Zul'Gurub.\",Portrait=M..\"raids\\\\zg\\\\hakkar-portrait\",Frame=M..\"raids\\\\zg\\\\hakkar-frame\",MapCoordinateX=49.9,MapCoordinateY=39.8,Abilities={{Effect=\"Throughout the encounter, Sons of Hakkar spawn from the stairways leading into Hakkar’s chamber.\\\n\\\nWhen slain, they release a poison cloud that afflicts Poisonous Blood on any player who comes into contact with it.\",Flags={F.Important},Icon=\"Ability_Hunter_Pet_WindSerpent\",Id=\"11357\",Name=\"Son of Hakkar\",SubAbilities={{Effect=\"Poisons the player, dealing 100 damage every 3 seconds for 1.5 minutes.\\\n\\\nWhile afflicted, Blood Siphon will damage Hakkar instead of healing him.\",Flags={F.Poison,F.Important},Icon=\"Spell_Nature_Regenerate\",Id=\"24321\",Name=\"Poisonous Blood\"}}},{Effect=\"Hakkar stuns the entire raid and drains health from all players every second for 8 seconds, healing himself significantly.\\\n\\\nPlayers afflicted with Poisonous Blood instead cause Hakkar to take damage from this effect.\\\n\\\nTo counter this ability, most of the raid must be poisoned before Blood Siphon begins.\",Icon=\"Spell_Shadow_LifeDrain\",Id=\"24322\",Name=\"Blood Siphon\"},{Effect=\"Hakkar can be engaged immediately upon entering the instance. However, if any High Priests remain alive, they empower him with additional abilities based on their aspects.\",Flags={F.Deadly,F.Important},Id=\"hakkaraspects\",Name=\"Aspects of the High Priests\",SubAbilities={{Effect=\"Deals 1,300 to 1,700 damage to nearby enemies and silences them for 5 seconds.\",Icon=\"Spell_Shadow_Teleport\",Id=\"24687\",Name=\"Aspect of Jeklik\"},{Effect=\"Spits poison at nearby enemies, dealing Nature damage and additional damage every 2 seconds for 10 seconds.\",Icon=\"Spell_Nature_CorrosiveBreath\",Id=\"24688\",Name=\"Aspect of Venoxis\"},{Effect=\"Stuns the player with the highest threat for 6 seconds.\",Icon=\"Ability_Smash\",Id=\"24686\",Name=\"Aspect of Mar'li\"},{Effect=\"Increases Hakkar’s attack speed by 150%.\",Icon=\"Ability_Druid_ChallangingRoar\",Id=\"24689\",Name=\"Aspect of Thekal\"},{Effect=\"Gouges the player with the highest threat, stunning them for 2 seconds.\",Icon=\"Ability_Vanish\",Id=\"24690\",Name=\"Aspect of Arlokk\"}}},{Effect=\"Drives the player with the highest threat into a frenzy for 10 seconds, increasing their attack speed by 100% and movement speed by 150%, and causing them to attack nearby allies.\",Icon=\"Spell_Shadow_ShadowWordDominate\",Id=\"24327\",Name=\"Cause Insanity\"},{Effect=\"Approximately every 20 seconds, a player is afflicted with Corrupted Blood, taking 200 damage every 2 seconds for 10 seconds.\\\n\\\nThis effect spreads to nearby players.\",Icon=\"Spell_Shadow_CorpseExplode\",Id=\"24328\",Name=\"Corrupted Blood\"},{Effect=\"After 10 minutes, Hakkar becomes enraged, greatly increasing his damage output.\",Flags={F.Deadly,F.Enrage},Icon=\"Ability_Warrior_BattleShout\",Id=\"hakkarenrage\",Name=\"Enrage\"}},L=\"19802:100,19852:14,19853:14,19856:14,19857:14,19864:14,20257:14,20264:14,19854:14,19855:14,19859:14,19861:14,19862:14,19865:14,19876:14\"},\n}}\nZLDB.Notes={\"Emperor Dagran Thaurissan has to die last.\",\"Only drops from a tribute run.\",\"Vem has to die last.\",\"Princess Yauj has to die last.\",\"Lord Kri has to die last.\"}\nZLDB.IS={\n[24]=\"Formula: Enchant Bracer - Agility|inv_misc_note_01|Rare|Profession|Enchanting\",\n[31]=\"Formula: Enchant Boots - Lesser Intellect|inv_misc_note_01|Uncommon|Profession|Enchanting\",\n[64]=\"Fiery Cloak|INV_Helmet_48|Uncommon|Back|Cloth||LevelOneLunatic\",\n[69]=\"Pattern: Dragonmaw Armor Kit|inv_scroll_03|Rare|Profession|Leatherworking\",\n[70]=\"Plans: Steel Belt Buckle|inv_scroll_06|Uncommon|Profession|Blacksmithing\",\n[71]=\"Plans: Gold Belt Buckle|inv_scroll_06|Uncommon|Profession|Blacksmithing\",\n[74]=\"Pattern: Dragonmaw Gloves|inv_scroll_05|Rare|Profession|Leatherworking\",\n[75]=\"Pattern: Stormreaver Gloves|inv_scroll_03|Rare|Profession|Tailoring\",\n[76]=\"Plans: Refined Dwarven Necklace|inv_misc_note_01|Rare|Profession|Jewelcrafting\",\n[77]=\"Plans: Ancient Dwarven Gemstone|inv_misc_note_01|Rare|Profession|Jewelcrafting\",\n[83]=\"Recipe: Elixir of Rapid Growth|inv_scroll_05|Rare|Professi